#[cfg(test)]
fn managed_local_directory_enumeration_count(device_id: Uuid) -> u64 {
    MANAGED_LOCAL_DIRECTORY_ENUMERATIONS
        .lock()
        .unwrap()
        .get(&device_id)
        .copied()
        .unwrap_or(0)
}

#[cfg(test)]
fn record_managed_local_directory_enumeration(device_id: Uuid) {
    *MANAGED_LOCAL_DIRECTORY_ENUMERATIONS
        .lock()
        .unwrap()
        .entry(device_id)
        .or_default() += 1;
}

const MAX_WATCHER_OBSERVATIONS: usize = 256;
const MAX_WATCHER_PATH_BYTES: usize = 64 * 1024;
