/// Bound public request validation as well as actor intake. A batch above the
/// count cap is already known to require a full scan, so only inspect a fixed
/// prefix. The result is exact while it remains within the byte cap; once the
/// cap is crossed it is merely a bounded overflow witness.
fn bounded_watcher_path_bytes(observations: &[SyncWatcherObservation]) -> usize {
    let mut path_bytes = 0_usize;
    for observation in observations.iter().take(MAX_WATCHER_OBSERVATIONS) {
        path_bytes = path_bytes.saturating_add(observation.retained_path_bytes());
        if path_bytes > MAX_WATCHER_PATH_BYTES {
            break;
        }
    }
    path_bytes
}

fn validate_local_mutation_request(
    transaction: OperationTransaction,
) -> Result<OperationTransaction, SyncLocalMutationRequestError> {
    let size = bounded_local_mutation_size(&transaction);
    if local_size_exceeded(size) {
        return Err(SyncLocalMutationRequestError::RequestTooLarge(size));
    }
    if transaction.operations.iter().any(|operation| {
        matches!(
            operation,
            SemanticOperation::ReconcileExternalPageState { .. }
        )
    }) {
        return Err(SyncLocalMutationRequestError::InvalidTransaction);
    }
    OperationTransaction::new(transaction.operations)
        .map_err(|_| SyncLocalMutationRequestError::InvalidTransaction)
}

fn bounded_local_mutation_size(transaction: &OperationTransaction) -> SyncLocalMutationRequestSize {
    let mut size = SyncLocalMutationRequestSize {
        rows: 0,
        referenced_paths: 0,
        path_bytes: 0,
        text_bytes: 0,
    };
    for operation in transaction
        .operations
        .iter()
        .take(MAX_LOCAL_MUTATION_ROWS + 1)
    {
        charge_local_row(&mut size);
        match operation {
            SemanticOperation::CreatePage { name, path, .. }
            | SemanticOperation::ReconcileExternalPageState { name, path, .. } => {
                charge_local_text(&mut size, name.as_str().len());
                charge_local_path(&mut size, path);
            }
            SemanticOperation::EditPagePath { path, .. } => {
                charge_local_path(&mut size, path);
            }
            SemanticOperation::SetPagePreamble { preamble, .. } => {
                charge_local_text(&mut size, preamble.as_ref().map_or(0, String::len));
            }
            SemanticOperation::CreateBlock { order, content, .. } => {
                charge_local_text(&mut size, order.len());
                charge_local_text(&mut size, content.len());
            }
            SemanticOperation::EditBlockContent { content, .. } => {
                charge_local_text(&mut size, content.len());
            }
            SemanticOperation::MoveSubtree { order, .. }
            | SemanticOperation::ReorderBlock { order, .. } => {
                charge_local_text(&mut size, order.len());
            }
            SemanticOperation::RestoreSubtree { blocks, .. } => {
                for restore in blocks {
                    charge_local_row(&mut size);
                    charge_local_text(&mut size, restore.claim.order.len());
                    if size.rows > MAX_LOCAL_MUTATION_ROWS {
                        break;
                    }
                }
            }
            SemanticOperation::RenamePagesAndRewriteReferrers {
                page_changes,
                block_rewrites,
                page_preamble_rewrites,
            } => {
                for change in page_changes {
                    charge_local_row(&mut size);
                    charge_local_text(&mut size, change.new_name.as_str().len());
                    charge_local_path(&mut size, &change.new_path);
                    if size.rows > MAX_LOCAL_MUTATION_ROWS {
                        break;
                    }
                }
                if size.rows <= MAX_LOCAL_MUTATION_ROWS {
                    for rewrite in block_rewrites {
                        charge_local_row(&mut size);
                        charge_local_text(&mut size, rewrite.new_content.len());
                        if size.rows > MAX_LOCAL_MUTATION_ROWS {
                            break;
                        }
                    }
                }
                if size.rows <= MAX_LOCAL_MUTATION_ROWS {
                    for rewrite in page_preamble_rewrites {
                        charge_local_row(&mut size);
                        charge_local_text(
                            &mut size,
                            rewrite.new_preamble.as_ref().map_or(0, String::len),
                        );
                        if size.rows > MAX_LOCAL_MUTATION_ROWS {
                            break;
                        }
                    }
                }
            }
            SemanticOperation::SetPageKind { .. }
            | SemanticOperation::MutateBlockLogseqIdentity { .. }
            | SemanticOperation::DeleteSubtree { .. }
            | SemanticOperation::DeletePage { .. } => {}
        }
        if local_size_exceeded(size) {
            break;
        }
    }
    if transaction.operations.len() > MAX_LOCAL_MUTATION_ROWS {
        size.rows = MAX_LOCAL_MUTATION_ROWS + 1;
    }
    size
}

fn charge_local_row(size: &mut SyncLocalMutationRequestSize) {
    size.rows = bounded_charge(size.rows, 1, MAX_LOCAL_MUTATION_ROWS);
}

fn charge_local_path(size: &mut SyncLocalMutationRequestSize, path: &ManagedPath) {
    size.referenced_paths = bounded_charge(
        size.referenced_paths,
        1,
        MAX_LOCAL_MUTATION_REFERENCED_PATHS,
    );
    size.path_bytes = bounded_charge(
        size.path_bytes,
        path.as_str().len(),
        MAX_LOCAL_MUTATION_PATH_BYTES,
    );
}

fn charge_local_text(size: &mut SyncLocalMutationRequestSize, bytes: usize) {
    size.text_bytes = bounded_charge(size.text_bytes, bytes, MAX_LOCAL_MUTATION_TEXT_BYTES);
}

fn bounded_charge(current: usize, charge: usize, limit: usize) -> usize {
    current.saturating_add(charge).min(limit.saturating_add(1))
}

fn local_size_exceeded(size: SyncLocalMutationRequestSize) -> bool {
    size.rows > MAX_LOCAL_MUTATION_ROWS
        || size.referenced_paths > MAX_LOCAL_MUTATION_REFERENCED_PATHS
        || size.path_bytes > MAX_LOCAL_MUTATION_PATH_BYTES
        || size.text_bytes > MAX_LOCAL_MUTATION_TEXT_BYTES
}

fn map_local_actor_error(_: SyncRuntimeRequestError) -> SyncLocalMutationRequestError {
    SyncLocalMutationRequestError::ActorUnavailable
}

fn map_editor_actor_error(_: SyncRuntimeRequestError) -> SyncEditorRequestError {
    SyncEditorRequestError::ActorUnavailable
}

fn map_application_actor_error(_: SyncRuntimeRequestError) -> SyncApplicationPageRequestError {
    SyncApplicationPageRequestError::ActorUnavailable
}

fn check_query_limit(limit: usize, request_bytes: usize) -> Result<(), SyncRuntimeRequestError> {
    if limit == 0 || limit > MAX_SYNC_RUNTIME_QUERY_ROWS {
        return Err(SyncRuntimeRequestError::QueryTooLarge {
            limit,
            request_bytes,
        });
    }
    Ok(())
}

fn validate_query_request(
    request: &SyncRuntimeQueryRequest,
) -> Result<(), SyncRuntimeRequestError> {
    let mut bytes = 0_usize;
    let mut add = |value: &str| {
        bytes = bytes.saturating_add(value.len());
    };
    let limit = match request {
        SyncRuntimeQueryRequest::ResolvePage { path, name, .. } => {
            add(path);
            add(name);
            1
        }
        SyncRuntimeQueryRequest::ResolvePageByName { name, .. } => {
            add(name);
            2
        }
        SyncRuntimeQueryRequest::ListPages { limit, .. }
        | SyncRuntimeQueryRequest::Search { limit, .. }
        | SyncRuntimeQueryRequest::PropertiesForOwner { limit, .. }
        | SyncRuntimeQueryRequest::PropertiesNamed { limit, .. }
        | SyncRuntimeQueryRequest::Tags { limit, .. }
        | SyncRuntimeQueryRequest::Tasks { limit, .. }
        | SyncRuntimeQueryRequest::ReferencesToPageName { limit, .. }
        | SyncRuntimeQueryRequest::ReferencesToLogseqUuid { limit, .. } => {
            match request {
                SyncRuntimeQueryRequest::Search { query, .. } => add(query),
                SyncRuntimeQueryRequest::PropertiesNamed { name, value, .. } => {
                    add(name);
                    if let Some(value) = value {
                        add(value);
                    }
                }
                SyncRuntimeQueryRequest::Tags { tag, .. } => add(tag),
                SyncRuntimeQueryRequest::Tasks { marker, .. } => {
                    if let Some(marker) = marker {
                        add(marker);
                    }
                }
                SyncRuntimeQueryRequest::ReferencesToPageName { name, .. } => add(name),
                SyncRuntimeQueryRequest::ReferencesToLogseqUuid { logseq_uuid, .. } => {
                    add(logseq_uuid)
                }
                SyncRuntimeQueryRequest::ListPages { .. } => {}
                SyncRuntimeQueryRequest::PropertiesForOwner { owner, .. } => match owner {
                    SyncEntityId::Page(id) | SyncEntityId::Block(id) => add(id),
                },
                _ => unreachable!("all query request variants are covered"),
            }
            *limit
        }
        SyncRuntimeQueryRequest::LoadPage {
            page_id,
            block_limit,
        } => {
            add(page_id);
            *block_limit
        }
    };
    if bytes > MAX_SYNC_RUNTIME_QUERY_BYTES {
        return Err(SyncRuntimeRequestError::QueryTooLarge {
            limit,
            request_bytes: bytes,
        });
    }
    check_query_limit(limit, bytes)
}

/// Compose the already-proven inactive primitives without exposing any of
/// their proof-bearing capabilities outside this module.  Every operation
/// before the final actor open is explicitly requested by
/// `SyncLocalActivationRequest`; normal graph startup cannot reach here.
struct CleanRuntimeResources {
    graph: Graph,
    receipts: ProjectionReceiptStore,
    runtime: CleanLocalRuntime,
}

/// Actor-owned clean runtime core.
///
/// This is deliberately separate from the legacy `RuntimeActor` fields.  It
/// gives the production actor one small boundary to adopt: one clean runtime,
/// one graph/receipt pair and at most one affine post-manifest continuation.
/// In particular it does not recreate the managed-local journal or any
/// Patricia-backed promotion state merely to fit the old actor shape.
struct CleanRuntimeActorCore {
    runtime: CleanLocalRuntime,
    pending: Option<CleanPublishedContinuation>,
    /// Tracks consecutive identical failures of the retained continuation so a
    /// deterministic failure escalates to a named block instead of an
    /// unbounded per-tick retry. See `MAX_IDENTICAL_RETAINED_RETRY_ATTEMPTS`.
    retry_fingerprint: Option<CleanRetryFingerprint>,
    watcher: CleanWatcherState,
    full_scan: Option<CleanFullScanContinuation>,
    completed_full_scan: Option<(u64, BTreeSet<ManagedPath>)>,
    /// The worst single-turn document-read cost any full scan of this actor has
    /// paid. Published through `SyncWatcherStatus`.
    full_scan_worst_turn_reads: usize,
    /// Every full-scan document read this actor has performed, cumulative.
    full_scan_total_reads: usize,
    /// Handed forward by a pass during which a full-scan-forcing observation
    /// arrived; it bounds how much the next pass has to redo. Dropped as soon as
    /// such an observation arrives with no pass in flight, because then nothing
    /// is covered and the next pass owes a complete sweep.
    full_scan_resume: Option<CleanFullScanResume>,
    /// An externally authored manifest has committed, but its derived graph
    /// projection has not yet completed.  Keep the watcher admission open
    /// until the continuation succeeds, then report one observable change
    /// after any observations accumulated behind it are reconciled as well.
    external_change_pending_notification: bool,
    /// A provider batch has committed, but its derived projection may still be
    /// completing. Retain its identity until a later actor tick publishes the
    /// live-view notification, even if an interleaved application read owns the
    /// serialized actor and finishes the retained projection first.
    provider_change_pending_notification: Option<BatchId>,
}

#[derive(Default)]
struct CleanWatcherState {
    exact: BTreeSet<ManagedPath>,
    full_scan: bool,
    latest_enqueue: u64,
    acknowledged: u64,
}

/// One bounded continuation for a clean watcher full scan. Enumerating the
/// on-disk paths and the finite SQLite/manifest path inventory happens once;
/// later actor turns read and compare only a small slice. This keeps application
/// and enrollment requests from waiting behind an O(graph) actor turn while
/// preserving the exact same final changed-path set.
///
/// Document bytes are deliberately NOT captured up front. Reading them lazily,
/// one budgeted slice at a time, is what makes the FIRST turn of a rescan bounded
/// too: it used to be a two-pass byte-retaining capture of the whole graph
/// (`2 × N` file opens) in a single unbudgeted turn.
struct CleanFullScanContinuation {
    epoch: u64,
    candidates: Vec<ManagedPath>,
    next: usize,
    changed: BTreeSet<ManagedPath>,
    /// Set when a full-scan-forcing observation arrives while THIS scan runs.
    /// See [`CleanFullScanRecheck`].
    recheck: Option<CleanFullScanRecheck>,
}

/// How much of a completed pass a follow-up pass has to redo.
///
/// A scan reads its candidates in sorted order at increasing times. An
/// observation arriving when the cursor sits at candidate `p` is already covered
/// for every candidate from `p` onward — those are read *after* it arrived — and
/// uncovered only for the prefix read before it. So the follow-up pass has to
/// redo that prefix and nothing else.
///
/// This is the whole anti-chain property. Before it, an observation arriving
/// mid-scan left `CleanWatcherState::full_scan` set (the flag having been cleared
/// at *begin*), and the completed scan was immediately followed by a fresh
/// whole-graph pass with no idle gap — so a cycle that overran its window made
/// rescans back-to-back and the actor lane was never free. Now each follow-up
/// pass covers a strictly shorter prefix, so an overrun converges instead of
/// chaining.
#[derive(Clone, Debug, Eq, PartialEq)]
enum CleanFullScanRecheck {
    /// The pass had already read every candidate when the observation arrived.
    All,
    /// Candidates strictly before this path were read too early to have seen it.
    Before(ManagedPath),
}

/// What a completed pass hands to the pass that answers the observations which
/// arrived while it ran.
struct CleanFullScanResume {
    recheck: CleanFullScanRecheck,
    /// The completed pass's candidate list, so the follow-up can tell a path it
    /// already covered late in that pass from one that appeared afterwards.
    previous: Vec<ManagedPath>,
}

enum CleanFullScanStep {
    Pending,
    Complete {
        epoch: u64,
        changed: BTreeSet<ManagedPath>,
    },
}

const CLEAN_FULL_SCAN_PATH_BUDGET: usize = 16;
const CLEAN_FULL_SCAN_TIME_BUDGET: Duration = Duration::from_millis(25);

impl CleanWatcherState {
    fn enqueue(&mut self, observation: SyncWatcherObservation) {
        self.latest_enqueue = self.latest_enqueue.saturating_add(1);
        match observation {
            SyncWatcherObservation::ManagedPath(path) if !self.full_scan => {
                self.exact.insert(path);
            }
            SyncWatcherObservation::ManagedPath(_)
            | SyncWatcherObservation::UnknownPath
            | SyncWatcherObservation::NotifyError
            | SyncWatcherObservation::RescanRequired => {
                self.full_scan = true;
                self.exact.clear();
            }
        }
    }

    fn seed_full_scan(&mut self) {
        self.enqueue(SyncWatcherObservation::RescanRequired);
    }

    fn pending(&self) -> bool {
        self.full_scan || !self.exact.is_empty()
    }

    fn status(&self) -> SyncWatcherStatus {
        SyncWatcherStatus {
            latest_enqueue: self.latest_enqueue,
            acknowledged: self.acknowledged,
            pending: self.pending(),
            pending_requires_full_scan: self.full_scan,
            ..SyncWatcherStatus::default()
        }
    }

    fn settle(&mut self) -> u64 {
        self.acknowledged = self.latest_enqueue;
        self.full_scan = false;
        self.exact.clear();
        self.acknowledged
    }

    fn begin_full_scan(&mut self) -> Option<u64> {
        if !self.full_scan {
            return None;
        }
        let epoch = self.latest_enqueue;
        self.full_scan = false;
        self.exact.clear();
        Some(epoch)
    }

    fn settle_through(&mut self, epoch: u64) {
        self.acknowledged = self.acknowledged.max(epoch);
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum CleanActorMutationOutcome {
    Durable(BatchId),
    /// THIS submission's manifest commit is durable; only disposable derived
    /// state (SQLite and/or exact Markdown projection) is still retained in
    /// `CleanRuntimeActorCore::pending`. `batch_id` names the caller's own
    /// batch, so a caller may settle it and then report its request applied.
    DurablePending {
        batch_id: BatchId,
        phase: OperationalPhase,
    },
    /// A retained continuation from an EARLIER batch still occupies the clean
    /// actor, so this submission was never executed. `batch_id` names that
    /// earlier batch, never the caller's work: settling it says nothing about
    /// this request, and reporting the request applied would be a lie.
    RetainedPriorPending {
        batch_id: BatchId,
        phase: OperationalPhase,
    },
    /// The retained continuation failed identically on consecutive attempts
    /// and is not a bounded-slice resume. The durable commit stays retained
    /// and every tick keeps retrying (identical text does not prove the
    /// failure is deterministic); this outcome only NAMES the persisting
    /// failure instead of reporting it as an ordinary pending retry.
    DurableStuck {
        batch_id: BatchId,
        phase: OperationalPhase,
        detail: String,
    },
}

enum CleanActorExternalOutcome {
    Noop,
    Durable(BatchId),
    DurablePending {
        batch_id: BatchId,
        phase: OperationalPhase,
    },
}

/// Consecutive identical non-continuation failures of one retained
/// continuation before the actor stops re-running the coordinator and names
/// the block. Bounded-slice resumes are exempt (see
/// `OperationalCoordinatorError::continuation_required`); any change in the
/// failure text resets the count, so only a deterministic failure escalates.
/// The count is process-local: a restart retries fresh.
const MAX_IDENTICAL_RETAINED_RETRY_ATTEMPTS: u32 = 3;

#[derive(Debug)]
struct CleanRetryFingerprint {
    batch_id: BatchId,
    phase: OperationalPhase,
    detail: String,
    attempts: u32,
    escalated: bool,
}

#[derive(Debug)]
struct CleanActorMutationFailure {
    phase: OperationalPhase,
    detail: String,
}

impl From<OperationalCoordinatorError> for CleanActorMutationFailure {
    fn from(error: OperationalCoordinatorError) -> Self {
        Self {
            phase: error.phase(),
            detail: error.detail().to_owned(),
        }
    }
}

impl CleanRuntimeActorCore {
    fn new(runtime: CleanLocalRuntime, seed_full_scan: bool) -> Self {
        let mut watcher = CleanWatcherState::default();
        if seed_full_scan {
            watcher.seed_full_scan();
        }
        Self {
            runtime,
            pending: None,
            retry_fingerprint: None,
            watcher,
            full_scan: None,
            completed_full_scan: None,
            full_scan_resume: None,
            full_scan_worst_turn_reads: 0,
            full_scan_total_reads: 0,
            external_change_pending_notification: false,
            provider_change_pending_notification: None,
        }
    }

    fn execute_local(
        &mut self,
        graph: &Graph,
        receipts: &ProjectionReceiptStore,
        transaction: &OperationTransaction,
    ) -> Result<CleanActorMutationOutcome, CleanActorMutationFailure> {
        if let Some(pending) = self.pending.as_ref() {
            return Ok(CleanActorMutationOutcome::RetainedPriorPending {
                batch_id: pending.batch_id(),
                phase: pending.failure().phase(),
            });
        }
        let state = {
            let mut session = self.runtime.admit_clean_mutation(graph).map_err(|error| {
                CleanActorMutationFailure {
                    phase: OperationalPhase::Bindings,
                    detail: error.to_string(),
                }
            })?;
            OperationalCoordinator::execute_clean_local(&mut session, graph, receipts, transaction)
                .map_err(CleanActorMutationFailure::from)?
        };
        Ok(self.retain_outcome(state))
    }

    /// Repair one exact graph file only when its bytes are the authenticated
    /// retained rendering of a manifest head superseded by a concurrent merge.
    /// The projection writer still guards the exact observed bytes, so a real
    /// external edit races or refuses instead of being overwritten.
    fn repair_superseded_projection(
        &self,
        graph: &Graph,
        receipts: &ProjectionReceiptStore,
        path: &ManagedPath,
    ) -> Result<bool, CleanActorMutationFailure> {
        let observed =
            graph
                .read_projection_input(path)
                .map_err(|error| CleanActorMutationFailure {
                    phase: OperationalPhase::ProjectionDrain,
                    detail: error.to_string(),
                })?;
        let Some(observed) = observed else {
            return Ok(false);
        };
        let engine = self.runtime.engine();
        let Some(page_id) = engine
            .authorize_clean_superseded_projection_repair(path, &observed)
            .map_err(|error| CleanActorMutationFailure {
                phase: OperationalPhase::ProjectionDrain,
                detail: error.to_string(),
            })?
        else {
            return Ok(false);
        };
        crate::oplog::projection::write_projection_exact(
            graph,
            receipts,
            engine,
            page_id,
            Some(&observed),
        )
        .map_err(|error| CleanActorMutationFailure {
            phase: OperationalPhase::ProjectionDrain,
            detail: error.to_string(),
        })?;
        Ok(true)
    }

    fn execute_local_correlated(
        &mut self,
        graph: &Graph,
        receipts: &ProjectionReceiptStore,
        batch_id: BatchId,
        transaction: &OperationTransaction,
        persist_fingerprint: impl FnMut(ContentDigest) -> Result<(), String>,
    ) -> Result<CleanActorMutationOutcome, CleanActorMutationFailure> {
        if let Some(pending) = self.pending.as_ref() {
            return Ok(CleanActorMutationOutcome::RetainedPriorPending {
                batch_id: pending.batch_id(),
                phase: pending.failure().phase(),
            });
        }
        let state = {
            let mut session = self.runtime.admit_clean_mutation(graph).map_err(|error| {
                CleanActorMutationFailure {
                    phase: OperationalPhase::Bindings,
                    detail: error.to_string(),
                }
            })?;
            OperationalCoordinator::execute_clean_local_correlated(
                &mut session,
                graph,
                receipts,
                batch_id,
                transaction,
                persist_fingerprint,
            )
            .map_err(CleanActorMutationFailure::from)?
        };
        Ok(self.retain_outcome(state))
    }

    fn execute_provider(
        &mut self,
        graph: &Graph,
        receipts: &ProjectionReceiptStore,
        prepared: &PreparedBatch,
    ) -> Result<CleanActorMutationOutcome, CleanActorMutationFailure> {
        if let Some(pending) = self.pending.as_ref() {
            return Ok(CleanActorMutationOutcome::RetainedPriorPending {
                batch_id: pending.batch_id(),
                phase: pending.failure().phase(),
            });
        }
        let state = {
            let mut session = self.runtime.admit_clean_mutation(graph).map_err(|error| {
                CleanActorMutationFailure {
                    phase: OperationalPhase::Bindings,
                    detail: error.to_string(),
                }
            })?;
            OperationalCoordinator::ingest_clean_prepared(&mut session, graph, receipts, prepared)
                .map_err(CleanActorMutationFailure::from)?
        };
        let outcome = self.retain_outcome(state);
        self.provider_change_pending_notification = Some(match &outcome {
            CleanActorMutationOutcome::Durable(batch_id)
            | CleanActorMutationOutcome::DurablePending { batch_id, .. }
            | CleanActorMutationOutcome::RetainedPriorPending { batch_id, .. }
            | CleanActorMutationOutcome::DurableStuck { batch_id, .. } => *batch_id,
        });
        Ok(outcome)
    }

    /// The retained continuation's own failure, verbatim.
    ///
    /// `DurablePending` only says derived work remains; this says WHY it was
    /// retained. On Android that reason is the real defect (a durability
    /// barrier that fails or defers on shared storage), and it survives only
    /// until `retry_pending` consumes the continuation — so callers that
    /// intend to settle must read it first.
    fn pending_failure(&self) -> Option<(BatchId, OperationalPhase, String)> {
        self.pending.as_ref().map(|pending| {
            (
                pending.batch_id(),
                pending.failure().phase(),
                pending.failure().detail().to_owned(),
            )
        })
    }

    fn retry_pending(
        &mut self,
        graph: &Graph,
        receipts: &ProjectionReceiptStore,
    ) -> Option<CleanActorMutationOutcome> {
        // Escalation never stops the retries: an identical detail string three
        // times is not proof the failure is deterministic (a transient
        // filesystem condition can repeat verbatim), so every tick still
        // attempts recovery and escalation only changes what a persisting
        // failure is REPORTED as — the named stuck state instead of a silent
        // pending retry.
        let pending = self.pending.take()?;
        let state = match self.runtime.admit_clean_derived_recovery(graph) {
            Ok(mut session) => {
                OperationalCoordinator::retry_clean_local(&mut session, graph, receipts, pending)
            }
            Err(admission) => {
                self.pending = Some(pending);
                let pending = self.pending.as_ref().expect("pending was restored");
                let batch_id = pending.batch_id();
                let phase = pending.failure().phase();
                if let Some(outcome) = self.note_retry_failure(
                    batch_id,
                    phase,
                    format!("clean recovery admission failed: {admission}"),
                ) {
                    return Some(outcome);
                }
                return Some(CleanActorMutationOutcome::DurablePending { batch_id, phase });
            }
        };
        if let CleanLocalMutationState::DurablePending(pending) = &state {
            if !pending.failure().is_continuation_required() {
                if let Some(outcome) = self.note_retry_failure(
                    pending.batch_id(),
                    pending.failure().phase(),
                    pending.failure().detail().to_owned(),
                ) {
                    if let CleanLocalMutationState::DurablePending(pending) = state {
                        self.pending = Some(pending);
                    }
                    return Some(outcome);
                }
            } else {
                self.retry_fingerprint = None;
            }
        } else {
            self.retry_fingerprint = None;
        }
        Some(self.retain_outcome(state))
    }

    /// Record one non-continuation failure of the retained continuation.
    /// Returns the escalated outcome once the same batch has failed with the
    /// same phase and detail `MAX_IDENTICAL_RETAINED_RETRY_ATTEMPTS` times in
    /// a row; any difference restarts the count at one.
    fn note_retry_failure(
        &mut self,
        batch_id: BatchId,
        phase: OperationalPhase,
        detail: String,
    ) -> Option<CleanActorMutationOutcome> {
        let repeat = self.retry_fingerprint.as_ref().is_some_and(|fingerprint| {
            fingerprint.batch_id == batch_id
                && fingerprint.phase == phase
                && fingerprint.detail == detail
        });
        let attempts = if repeat {
            self.retry_fingerprint
                .as_ref()
                .expect("repeat implies a fingerprint")
                .attempts
                .saturating_add(1)
        } else {
            1
        };
        let escalated = attempts >= MAX_IDENTICAL_RETAINED_RETRY_ATTEMPTS;
        self.retry_fingerprint = Some(CleanRetryFingerprint {
            batch_id,
            phase,
            detail: detail.clone(),
            attempts,
            escalated,
        });
        escalated.then_some(CleanActorMutationOutcome::DurableStuck {
            batch_id,
            phase,
            detail,
        })
    }

    fn observe(&mut self, observations: Vec<SyncWatcherObservation>) {
        for observation in observations {
            // Only an observation that forces a whole-graph sweep can create a
            // follow-up pass, so only that kind moves the recheck bound.
            let forces_full_scan = !matches!(observation, SyncWatcherObservation::ManagedPath(_));
            self.watcher.enqueue(observation);
            if !forces_full_scan {
                continue;
            }
            match self.full_scan.as_mut() {
                Some(continuation) => {
                    // Everything from the cursor onward will be read after this
                    // observation arrived, so it is already covered.
                    continuation.recheck =
                        Some(match continuation.candidates.get(continuation.next) {
                            Some(path) => CleanFullScanRecheck::Before(path.clone()),
                            None => CleanFullScanRecheck::All,
                        });
                }
                // No pass is running, so nothing is covered: whatever a previous
                // pass handed forward no longer bounds the work this observation
                // demands.
                None => self.full_scan_resume = None,
            }
        }
    }

    fn watcher_status(&self) -> SyncWatcherStatus {
        let mut status = self.watcher.status();
        status.full_scan_documents_read_in_slowest_turn = self.full_scan_worst_turn_reads;
        status.full_scan_documents_read = self.full_scan_total_reads;
        if self.full_scan.is_some() || self.completed_full_scan.is_some() {
            status.pending = true;
            status.pending_requires_full_scan = true;
            status.drain_in_flight = true;
        }
        status
    }

    fn begin_full_scan(&mut self, graph: &Graph) -> Result<(), CleanActorMutationFailure> {
        if self.full_scan.is_some() {
            return Ok(());
        }
        if !self.watcher.full_scan {
            return Ok(());
        }
        let epoch = self.watcher.latest_enqueue;
        // Paths only. The bytes are read lazily by `advance_full_scan`, inside
        // its per-turn budget; capturing them here is what made this turn an
        // unbudgeted `2 × N` file-open sweep of the whole graph.
        let disk = graph.clean_watcher_managed_text_paths().map_err(|error| {
            CleanActorMutationFailure {
                phase: OperationalPhase::Planning,
                detail: format!("clean watcher full graph capture failed: {error}"),
            }
        })?;
        let read = self
            .runtime
            .database()
            .materialized_read()
            .map_err(|error| CleanActorMutationFailure {
                phase: OperationalPhase::Planning,
                detail: format!("clean watcher SQLite inventory failed: {error}"),
            })?;
        let mut candidates = disk.into_iter().collect::<BTreeSet<_>>();
        let mut cursor = None;
        loop {
            let pages = read
                .page_inventory_after(
                    cursor.as_ref().map(|(path, page_id)| (path, *page_id)),
                    None,
                    512,
                )
                .map_err(|error| CleanActorMutationFailure {
                    phase: OperationalPhase::Planning,
                    detail: format!("clean watcher page inventory failed: {error}"),
                })?;
            if pages.is_empty() {
                break;
            }
            for page in &pages {
                candidates.insert(page.path.clone());
            }
            let last = pages.last().expect("nonempty page inventory batch");
            cursor = Some((last.path.clone(), last.page_id));
            if pages.len() < 512 {
                break;
            }
        }
        candidates.extend(
            self.runtime
                .engine()
                .clean_manifest_projection_paths()
                .map_err(|error| CleanActorMutationFailure {
                    phase: OperationalPhase::Planning,
                    detail: format!("clean watcher manifest path inventory failed: {error}"),
                })?,
        );
        // A pass that ran while observations arrived told us exactly how much of
        // itself those observations did NOT cover. Redo that and nothing else,
        // so an overrunning cycle converges instead of chaining whole-graph
        // passes back to back.
        let candidates: Vec<ManagedPath> = match self.full_scan_resume.take() {
            None => candidates.into_iter().collect(),
            Some(CleanFullScanResume {
                recheck: CleanFullScanRecheck::All,
                ..
            }) => candidates.into_iter().collect(),
            Some(CleanFullScanResume {
                recheck: CleanFullScanRecheck::Before(bound),
                previous,
            }) => candidates
                .into_iter()
                .filter(|path| *path < bound || previous.binary_search(path).is_err())
                .collect(),
        };
        let retained_epoch = self
            .watcher
            .begin_full_scan()
            .expect("full scan remains pending until its continuation is installed");
        debug_assert_eq!(retained_epoch, epoch);
        self.full_scan = Some(CleanFullScanContinuation {
            epoch,
            candidates,
            next: 0,
            changed: BTreeSet::new(),
            recheck: None,
        });
        Ok(())
    }

    fn advance_full_scan(
        &mut self,
        graph: &Graph,
    ) -> Result<CleanFullScanStep, CleanActorMutationFailure> {
        let continuation = self
            .full_scan
            .as_mut()
            .expect("full scan advance requires an initialized continuation");
        let read = self
            .runtime
            .database()
            .materialized_read()
            .map_err(|error| CleanActorMutationFailure {
                phase: OperationalPhase::Planning,
                detail: format!("clean watcher SQLite inventory failed: {error}"),
            })?;
        let started = Instant::now();
        let mut processed = 0_usize;
        while continuation.next < continuation.candidates.len() {
            let path = continuation.candidates[continuation.next].clone();
            processed += 1;
            // One document read, charged to this turn's budget. Reconciliation
            // recaptures every path it is handed under its own two-pass
            // authority, so this read is a filter, never publication evidence --
            // and reading it here rather than in `begin_full_scan` is what keeps
            // the whole scan inside a bound.
            let disk = graph
                .clean_watcher_managed_text_read(&path)
                .map_err(|error| CleanActorMutationFailure {
                    phase: OperationalPhase::Planning,
                    detail: format!("clean watcher read for {path} failed: {error}"),
                })?;
            let owners =
                read.pages_by_path(&path, 2)
                    .map_err(|error| CleanActorMutationFailure {
                        phase: OperationalPhase::Planning,
                        detail: format!("clean watcher SQLite owner for {path} failed: {error}"),
                    })?;
            let sqlite_owner = match owners.as_slice() {
                [] => None,
                [owner] => Some(owner.page_id),
                _ => {
                    return Err(CleanActorMutationFailure {
                        phase: OperationalPhase::Planning,
                        detail: format!(
                            "clean watcher SQLite contains more than one owner for {path}"
                        ),
                    });
                }
            };
            let predecessor = self
                .runtime
                .engine()
                .clean_observed_projection(&path, sqlite_owner)
                .map_err(|error| CleanActorMutationFailure {
                    phase: OperationalPhase::Planning,
                    detail: format!("clean watcher observation for {path} failed: {error}"),
                })?;
            let differs = match (disk.as_ref(), &predecessor) {
                (None, None)
                | (None, Some(crate::oplog::hot_engine::CleanObservedProjection::Released)) => {
                    false
                }
                (
                    Some(bytes),
                    Some(crate::oplog::hot_engine::CleanObservedProjection::Present(prior)),
                ) => bytes != prior,
                _ => true,
            };
            if differs {
                if std::env::var_os("TINE_CLEAN_WATCHER_TRACE").is_some() {
                    eprintln!(
                        "clean watcher changed path {path}: disk={} predecessor={}",
                        disk.as_ref().map_or_else(
                            || "absent".to_owned(),
                            |bytes| format!(
                                "{}:{:?}",
                                bytes.len(),
                                crate::oplog::BlobDescription::of(bytes)
                            )
                        ),
                        match &predecessor {
                            None => "absent".to_owned(),
                            Some(crate::oplog::hot_engine::CleanObservedProjection::Present(
                                bytes,
                            )) => format!(
                                "present:{}:{:?}",
                                bytes.len(),
                                crate::oplog::BlobDescription::of(bytes)
                            ),
                            Some(crate::oplog::hot_engine::CleanObservedProjection::Released) =>
                                "released".to_owned(),
                        }
                    );
                }
                continuation.changed.insert(path);
            }
            continuation.next += 1;
            if processed >= CLEAN_FULL_SCAN_PATH_BUDGET
                || started.elapsed() >= CLEAN_FULL_SCAN_TIME_BUDGET
            {
                return Ok(CleanFullScanStep::Pending);
            }
        }
        let completed = self
            .full_scan
            .take()
            .expect("completed full scan continuation remains installed");
        // Flush what this pass found FIRST -- an observation arriving mid-pass
        // must never be able to postpone reconciliation of what the pass already
        // proved changed -- and hand the follow-up pass its bound.
        self.full_scan_resume = completed.recheck.map(|recheck| CleanFullScanResume {
            recheck,
            previous: completed.candidates,
        });
        Ok(CleanFullScanStep::Complete {
            epoch: completed.epoch,
            changed: completed.changed,
        })
    }

    fn execute_external_paths(
        &mut self,
        graph: &Graph,
        receipts: &ProjectionReceiptStore,
        paths: &BTreeSet<ManagedPath>,
    ) -> Result<CleanActorExternalOutcome, CleanActorMutationFailure> {
        if let Some(pending) = self.pending.as_ref() {
            return Ok(CleanActorExternalOutcome::DurablePending {
                batch_id: pending.batch_id(),
                phase: pending.failure().phase(),
            });
        }
        let requested = paths.iter().map(ManagedPath::as_str).collect::<Vec<_>>();
        let state = {
            let mut session = self.runtime.admit_clean_mutation(graph).map_err(|error| {
                CleanActorMutationFailure {
                    phase: OperationalPhase::Bindings,
                    detail: error.to_string(),
                }
            })?;
            OperationalCoordinator::execute_clean_external(
                &mut session,
                graph,
                receipts,
                &requested,
            )
            .map_err(CleanActorMutationFailure::from)?
        };
        Ok(match state {
            CleanExternalMutationState::Noop => CleanActorExternalOutcome::Noop,
            CleanExternalMutationState::Complete(batch_id) => {
                CleanActorExternalOutcome::Durable(batch_id)
            }
            CleanExternalMutationState::DurablePending(pending) => {
                let batch_id = pending.batch_id();
                let phase = pending.failure().phase();
                self.pending = Some(pending);
                self.external_change_pending_notification = true;
                CleanActorExternalOutcome::DurablePending { batch_id, phase }
            }
        })
    }

    fn retain_outcome(&mut self, state: CleanLocalMutationState) -> CleanActorMutationOutcome {
        match state {
            CleanLocalMutationState::Complete(batch_id) => {
                debug_assert!(self.pending.is_none());
                CleanActorMutationOutcome::Durable(batch_id)
            }
            CleanLocalMutationState::DurablePending(pending) => {
                let batch_id = pending.batch_id();
                let phase = pending.failure().phase();
                self.pending = Some(pending);
                CleanActorMutationOutcome::DurablePending { batch_id, phase }
            }
        }
    }

    fn load_current_editor_page(
        &self,
        page_id: PageId,
    ) -> Result<Option<EditorCurrentPage>, SyncEditorRequestError> {
        load_current_editor_page_from_projection(
            self.runtime.engine(),
            self.runtime.database(),
            page_id,
        )
    }
}

fn clean_baseline_directory(archive_root: &Path) -> PathBuf {
    archive_root.join(crate::oplog::lazy_genesis::LAZY_GENESIS_BASELINE_DIRECTORY)
}

fn clean_operation_archive_directory(archive_root: &Path) -> PathBuf {
    archive_root.join(CLEAN_OPERATION_ARCHIVE_DIRECTORY)
}

/// Construct the production clean runtime, retracting the disposable archive if
/// the attempt refuses before any authority exists.
///
/// Nothing this lane builds before the activation marker is authority: the
/// Markdown/Org tree is still the sole one, and the whole archive is
/// reconstructible from current Direct Files. Leaving it behind is therefore not
/// neutral, it is fatal — the next activation finds an archive with no
/// enrollment beside it and no private activation reservation to attribute it
/// (this lane records none), so `discover_startup` classifies it
/// `AmbiguousOrForeignResidue { ArchiveResidue, SyncConflict }` and every later
/// attempt refuses the same way, for good.
///
/// That is reachable in one ordinary step: another writer touching the graph
/// during activation makes the final source proof refuse `Retryable {
/// durable_stage: Absent }` — the refusal a physical Android reported on
/// CI 32108957903 — after this lane has already created the archive. Only what
/// THIS attempt created is retracted; a pre-existing archive is left exactly
/// where it is, so genuinely foreign residue is still refused.
fn activate_clean_runtime_resources(
    request: &SyncLocalActivationRequest,
    graph: Graph,
    progress: &mut dyn FnMut(SyncLocalActivationProgress),
) -> Result<CleanRuntimeResources, String> {
    let archive_predates_this_attempt = request.archive_root.exists();
    let result = activate_clean_runtime_resources_retaining_archive(request, graph, progress);
    if result.is_err() && !archive_predates_this_attempt {
        if let Err(error) = remove_disposable_clean_archive(&request.archive_root) {
            return Err(match result {
                Err(detail) => format!(
                    "{detail}; retracting the disposable clean archive also failed: {error}"
                ),
                Ok(_) => unreachable!("the result was just observed to be an error"),
            });
        }
    }
    result
}

/// Remove an archive tree that carries no authority. It is private state under
/// the app's own directory; no graph path is ever reachable from here.
fn remove_disposable_clean_archive(archive_root: &Path) -> std::io::Result<()> {
    match fs::remove_dir_all(archive_root) {
        Ok(()) => Ok(()),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(error),
    }
}

fn activate_clean_runtime_resources_retaining_archive(
    request: &SyncLocalActivationRequest,
    graph: Graph,
    progress: &mut dyn FnMut(SyncLocalActivationProgress),
) -> Result<CleanRuntimeResources, String> {
    progress(SyncLocalActivationProgress::Phase {
        phase: SyncLocalActivationPhase::PrivateSetup,
    });
    prepare_activation_private_paths(request)
        .map_err(|error| format!("prepare clean private activation paths: {error}"))?;
    fs::create_dir_all(&request.archive_root)
        .map_err(|error| format!("create clean archive root: {error}"))?;
    let endpoint = ProjectionEndpointBinding::enroll_graph(
        &graph,
        request.identities.endpoint_id,
        request.identities.device_id,
    )
    .map_err(|error| format!("identify clean graph projection endpoint: {error}"))?;
    let receipts = open_reconstructible_activation_receipts(request, endpoint)?;
    let operation_archive_path = clean_operation_archive_directory(&request.archive_root);
    let operation_store =
        ObjectStore::open(&operation_archive_path, request.identities.workspace_id)
            .map_err(|error| format!("open clean operation archive: {error}"))?;

    progress(SyncLocalActivationProgress::Phase {
        phase: SyncLocalActivationPhase::SourceCapture,
    });
    let capture = graph
        .capture_inactive_bootstrap_sources(&request.capture_root)
        .map_err(display)?;
    progress(SyncLocalActivationProgress::Phase {
        phase: SyncLocalActivationPhase::BootstrapImportPreparation,
    });
    let preparation = prepare_clean_activation(
        &graph,
        capture,
        request.identities.workspace_id,
        request.identities.lineage_digest,
        request.identities.catalog_document_id,
        &request.preparation_root,
        &request.database_path,
        &ReferenceCatalogPolicyV1::default(),
    )
    .map_err(display)?;
    progress(SyncLocalActivationProgress::ReadinessSample {
        largest_page_path: preparation.instrumentation().largest_source_path.clone(),
    });
    #[cfg(test)]
    LAST_CLEAN_ACTIVATION_INSTRUMENTATION.with(|slot| {
        *slot.borrow_mut() = Some(preparation.instrumentation().clone());
    });
    progress(SyncLocalActivationProgress::Phase {
        phase: SyncLocalActivationPhase::ImmutablePublicationInstall,
    });
    let committed = commit_clean_activation(
        &graph,
        preparation,
        &clean_baseline_directory(&request.archive_root),
        &request.enrollment_root,
    )
    .map_err(display)?;
    let (baseline, projection, accepted_frontier, marker) = committed.into_parts();
    if marker.workspace_id() != request.identities.workspace_id
        || marker.lineage_digest() != request.identities.lineage_digest
    {
        return Err("clean activation marker differs from explicit identities".into());
    }

    let mut engine = ShardedHotEngine::new(
        request.identities.workspace_id,
        request.identities.lineage_digest,
        request.identities.catalog_document_id,
    );
    engine
        .configure_reference_catalog_policy(ReferenceCatalogPolicyV1::default())
        .map_err(display)?;
    engine
        .install_lazy_genesis_baseline(Arc::new(baseline))
        .map_err(display)?;
    engine
        .attach_clean_archive_store(operation_store)
        .map_err(display)?;
    engine
        .attach_clean_projection_endpoint(&graph, &receipts)
        .map_err(display)?;
    progress(SyncLocalActivationProgress::Phase {
        phase: SyncLocalActivationPhase::SqliteOpenBuild,
    });
    let store = ObjectStore::open(&operation_archive_path, request.identities.workspace_id)
        .map_err(display)?;
    let lease =
        WorkspaceRuntimeLease::acquire(&store, request.identities.workspace_id).map_err(display)?;
    let projection = LeasedWorkspaceProjection::adopt_clean_genesis(
        lease,
        &request.database_path,
        ProjectionClaim::current(
            request.identities.workspace_id,
            request.identities.lineage_digest,
        ),
        &accepted_frontier,
        &store,
        &engine,
        projection,
    )
    .map_err(|(_, error)| display(error))?;
    let runtime = CleanLocalRuntime::from_open_parts(
        request.identities.session_id,
        endpoint,
        engine,
        projection,
    )
    .map_err(display)?;
    Ok(CleanRuntimeResources {
        graph,
        receipts,
        runtime,
    })
}

/// Reconstruct the clean runtime from its sole authority marker, immutable
/// baseline and committed operation manifests. SQLite and Markdown projection
/// are repaired before mutation authority is returned.
fn open_clean_runtime_resources(
    request: &SyncRuntimeOpenRequest,
) -> Result<Option<CleanRuntimeResources>, String> {
    open_clean_runtime_resources_with_progress(request, &mut |_| {})
}

fn open_clean_runtime_resources_with_progress(
    request: &SyncRuntimeOpenRequest,
    progress: &mut dyn FnMut(SyncLocalActivationProgress),
) -> Result<Option<CleanRuntimeResources>, String> {
    let identities = request.clean_identities.as_ref().ok_or_else(|| {
        "clean managed runtime open has no persisted local identity record".to_owned()
    })?;
    if request
        .enrollment_root
        .join(crate::oplog::lazy_genesis::LAZY_GENESIS_ACTIVATION_MARKER_FILE)
        .is_file()
    {
        // This is progress only, never admission authority. The authenticated
        // marker is still decoded and verified by `open_clean_activation`.
        progress(SyncLocalActivationProgress::Phase {
            phase: SyncLocalActivationPhase::RetainedRuntimeOpen,
        });
    }
    let Some(opened) = open_clean_activation_authority(
        &request.enrollment_root,
        &clean_baseline_directory(&request.archive_root),
        identities.catalog_document_id,
        ReferenceCatalogPolicyV1::default(),
    )
    .map_err(display)?
    else {
        return Ok(None);
    };
    let graph = Graph::open_checked(&request.graph_root).map_err(display)?;
    let endpoint = ProjectionEndpointBinding::enroll_graph(
        &graph,
        identities.endpoint_id,
        identities.device_id,
    )
    .map_err(display)?;
    let receipts = ProjectionReceiptStore::open_for_endpoint(
        &request.receipt_root,
        identities.workspace_id,
        endpoint,
    )
    .map_err(display)?;
    if opened.marker().workspace_id() != identities.workspace_id
        || opened.marker().lineage_digest() != identities.lineage_digest
    {
        return Err("clean activation marker differs from persisted local identities".into());
    }
    let (mut engine, baseline, _) = opened.into_parts();
    let operation_archive_path = clean_operation_archive_directory(&request.archive_root);
    engine
        .attach_clean_archive_store(
            ObjectStore::open(&operation_archive_path, identities.workspace_id).map_err(display)?,
        )
        .map_err(display)?;
    let baseline_claim_source = engine
        .clean_transient_projection_claim_snapshot()
        .map_err(display)?
        .ok_or_else(|| "clean runtime has no immutable baseline claim snapshot".to_owned())?;
    progress(SyncLocalActivationProgress::Phase {
        phase: SyncLocalActivationPhase::RetainedRuntimeTailReplay,
    });
    let replayed = engine
        .replay_clean_committed_tail(baseline_claim_source.as_ref())
        .map_err(display)?;
    drop(baseline_claim_source);
    let store =
        ObjectStore::open(&operation_archive_path, identities.workspace_id).map_err(display)?;
    let lease = WorkspaceRuntimeLease::acquire(&store, identities.workspace_id).map_err(display)?;
    let projection = if replayed == 0 {
        let expected = engine.accepted_frontier_root().map_err(display)?;
        let baseline_projection = open_or_rebuild_clean_genesis_projection(
            &request.database_path,
            ProjectionClaim::current(identities.workspace_id, identities.lineage_digest),
            &baseline,
            ReferenceCatalogPolicyV1::default(),
        )
        .map_err(display)?;
        LeasedWorkspaceProjection::adopt_clean_genesis(
            lease,
            &request.database_path,
            ProjectionClaim::current(identities.workspace_id, identities.lineage_digest),
            &expected,
            &store,
            &engine,
            baseline_projection,
        )
        .map_err(|(_, error)| display(error))?
    } else {
        let application_runtime =
            ApplicationRuntimeRoot::open_explicit_private(&request.application_runtime_root)
                .map_err(display)?;
        let source = RebuildSource::new(&engine, &store).map_err(display)?;
        LeasedWorkspaceProjection::open_under(lease, |slot| {
            let opened = crate::oplog::SqliteFrontier::open_or_rebuild_with_applier_slot(
                &request.database_path,
                &application_runtime,
                ProjectionClaim::current(identities.workspace_id, identities.lineage_digest),
                source,
                slot,
            )?;
            Ok::<_, crate::oplog::SqliteProjectionError>((opened, ()))
        })
        .map(|(projection, ())| projection)
        .map_err(|(_, error)| display(error))?
    };
    engine
        .attach_clean_projection_endpoint(&graph, &receipts)
        .map_err(display)?;
    let endpoint = engine
        .projection_endpoint_binding()
        .ok_or_else(|| "clean runtime has no projection endpoint".to_owned())?;
    let terminal_work = engine.clean_terminal_projection_work().map_err(display)?;
    progress(SyncLocalActivationProgress::Phase {
        phase: SyncLocalActivationPhase::RetainedRuntimeProjectionRepair,
    });
    let receiver_local = terminal_work
        .iter()
        .filter(|work| work.endpoint_id() != endpoint.endpoint_id())
        .collect::<Vec<_>>();
    for work in terminal_work
        .iter()
        .filter(|work| work.endpoint_id() == endpoint.endpoint_id())
    {
        let executed = crate::oplog::projection::execute_clean_manifested_projection_work(
            &graph,
            &receipts,
            projection.database(),
            &mut engine,
            work,
        );
        match executed {
            Ok(()) => {}
            Err(crate::oplog::ProjectionError::WorkNotReady)
                if engine
                    .accepted_batch_projection_is_superseded(work.batch_id())
                    .map_err(display)? =>
            {
                // This endpoint's recorded rendering was superseded by a
                // concurrently accepted history, so the merge decides the page
                // now and the recorded bytes must not be replayed verbatim.
                // Skip instead of refusing to open: reopen always seeds a
                // clean full scan, and the receipt store re-projects any page
                // whose disk bytes are an earlier receipted render (GH #351).
            }
            Err(error) => return Err(display(error)),
        }
    }
    let foreign = receiver_local;
    if !foreign.is_empty() {
        let handoff = graph
            .mint_handoff_safe(identities.workspace_id, endpoint)
            .map_err(display)?;
        handoff
            .verify_binding(&graph, identities.workspace_id, endpoint)
            .map_err(display)?;
        let published = handoff.into_publisher_guard().into_published_latch();
        for work in foreign {
            let source = {
                let archive = engine
                    .archive_store()
                    .ok_or_else(|| "clean runtime has no operation archive".to_owned())?;
                crate::oplog::projection::decode_manifested_projection_work(archive, work)
                    .map_err(display)?
                    .manifested()
                    .clone()
            };
            crate::oplog::projection::execute_receiver_local_projection_under_handoff(
                &graph,
                &receipts,
                &engine,
                Some(projection.database()),
                &source,
                &published,
                true,
            )
            .map_err(display)?;
        }
        published.complete();
    }
    let runtime =
        CleanLocalRuntime::from_open_parts(identities.session_id, endpoint, engine, projection)
            .map_err(display)?;
    Ok(Some(CleanRuntimeResources {
        graph,
        receipts,
        runtime,
    }))
}

fn open_reconstructible_activation_receipts(
    request: &SyncLocalActivationRequest,
    endpoint: ProjectionEndpointBinding,
) -> Result<ProjectionReceiptStore, String> {
    let first = ProjectionReceiptStore::open_for_endpoint(
        &request.receipt_root,
        request.identities.workspace_id,
        endpoint,
    );
    match first {
        Ok(receipts) => Ok(receipts),
        Err(first_error) => {
            #[cfg(target_os = "android")]
            {
                // No enrollment binding exists yet, so Markdown/Org is still
                // the sole authority and this receipt tree cannot contain a
                // promoted mutation. Older Android candidates may have left a
                // partially initialized tree whose directory handles or modes
                // the current app UID cannot reuse. Preserve one diagnostic
                // copy, then prove that ordinary creation can start cleanly.
                archive_pre_promotion_receipts(&request.receipt_root).map_err(|error| {
                    format!(
                        "create private projection receipts: {first_error}; archive reconstructible pre-promotion receipt state: {error}"
                    )
                })?;
                return ProjectionReceiptStore::open_for_endpoint(
                    &request.receipt_root,
                    request.identities.workspace_id,
                    endpoint,
                )
                .map_err(|retry_error| {
                    format!(
                        "create private projection receipts: {first_error}; clean Android receipt rebuild also failed: {retry_error}"
                    )
                });
            }

            #[cfg(not(target_os = "android"))]
            Err(format!("create private projection receipts: {first_error}"))
        }
    }
}

#[cfg(any(test, target_os = "android"))]
fn archive_pre_promotion_receipts(receipt_root: &Path) -> Result<(), String> {
    let metadata = match fs::symlink_metadata(receipt_root) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(()),
        Err(error) => {
            return Err(format!("inspect {}: {error}", receipt_root.display()));
        }
    };
    if metadata.file_type().is_symlink() || !metadata.is_dir() {
        return Err(format!(
            "{} is not a real private directory",
            receipt_root.display()
        ));
    }
    let name = receipt_root
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or_else(|| "private receipt root has no UTF-8 filename".to_owned())?;
    let archived = receipt_root.with_file_name(format!("{name}.pre-promotion-failed"));
    match fs::remove_dir_all(&archived) {
        Ok(()) => {}
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => {
            return Err(format!(
                "remove prior diagnostic {}: {error}",
                archived.display()
            ));
        }
    }
    fs::rename(receipt_root, &archived).map_err(|error| {
        format!(
            "move {} to {}: {error}",
            receipt_root.display(),
            archived.display()
        )
    })
}

fn runtime_open_request_from_activation(
    request: &SyncLocalActivationRequest,
) -> SyncRuntimeOpenRequest {
    SyncRuntimeOpenRequest {
        profile: SyncStorageProfile::ExperimentalLocal,
        clean_identities: Some(request.identities.clone()),
        graph_root: request.graph_root.clone(),
        enrollment_root: request.enrollment_root.clone(),
        archive_root: request.archive_root.clone(),
        receipt_root: request.receipt_root.clone(),
        database_path: request.database_path.clone(),
        application_runtime_root: request.application_runtime_root.clone(),
        provider_root: request.provider_root.clone(),
        provider_journal_root: request.provider_journal_root.clone(),
    }
}

fn activation_open_clean_resources(
    request: SyncLocalActivationRequest,
    resources: CleanRuntimeResources,
    recovery: SyncRuntimeRecovery,
) -> SyncLocalActivationResult {
    let opened = SyncRuntimeHandle::open_from_clean_resources(
        runtime_open_request_from_activation(&request),
        request.identities.clone(),
        resources,
        recovery,
    );
    match opened {
        SyncRuntimeOpenResult {
            status: SyncRuntimeOpenStatus::Active,
            handle: Some(handle),
        } => SyncLocalActivationResult {
            status: SyncLocalActivationStatus::Active,
            handle: Some(handle),
        },
        SyncRuntimeOpenResult { status, .. } => activation_retryable(
            SyncLocalActivationStage::LocalActive,
            format!("clean managed runtime actor open refused after commit: {status:?}"),
        ),
    }
}

fn activation_retryable(
    durable_stage: SyncLocalActivationStage,
    detail: String,
) -> SyncLocalActivationResult {
    SyncLocalActivationResult {
        status: SyncLocalActivationStatus::Retryable {
            durable_stage,
            detail,
        },
        handle: None,
    }
}

fn activation_enrollment_failure(
    durable_stage: SyncLocalActivationStage,
    error: EnrollmentError,
) -> SyncLocalActivationResult {
    match classify_enrollment_error(error) {
        DiscoveryClassification::Retryable(_, detail) => {
            activation_retryable(durable_stage, detail)
        }
        DiscoveryClassification::UnsupportedOrIncompatible(component, scenario) => {
            SyncLocalActivationResult {
                status: SyncLocalActivationStatus::UnsupportedOrIncompatible {
                    component: map_component(component),
                    scenario,
                },
                handle: None,
            }
        }
        DiscoveryClassification::CorruptOrUnreadable(component, scenario) => {
            SyncLocalActivationResult {
                status: SyncLocalActivationStatus::CorruptOrUnreadable {
                    component: map_component(component),
                    scenario,
                },
                handle: None,
            }
        }
        DiscoveryClassification::AmbiguousOrForeignResidue(evidence, scenario) => {
            SyncLocalActivationResult {
                status: SyncLocalActivationStatus::AmbiguousOrForeignResidue {
                    evidence: map_ambiguous_evidence(evidence),
                    scenario,
                },
                handle: None,
            }
        }
        DiscoveryClassification::LegacyDefault
        | DiscoveryClassification::Absent
        | DiscoveryClassification::ExistingLocalActive(_)
        | DiscoveryClassification::ExistingNonActive(_)
        | DiscoveryClassification::Blocked(_) => {
            unreachable!("an enrollment error classifier returned a non-error state")
        }
    }
}

fn activation_blocked(reason_code: impl Into<String>) -> SyncLocalActivationResult {
    SyncLocalActivationResult {
        status: SyncLocalActivationStatus::Blocked {
            reason_code: reason_code.into(),
        },
        handle: None,
    }
}

fn identities_match_binding(
    identities: &SyncLocalActivationIdentities,
    binding: &EnrollmentBindingV1,
) -> bool {
    identities.workspace_id == binding.workspace_id()
        && identities.lineage_digest == binding.lineage_digest()
        && identities.catalog_document_id == binding.catalog_document_id()
        && identities.endpoint_id == binding.endpoint_id()
        && identities.device_id == binding.device_id()
}

fn local_activation_identity(
    request: &SyncLocalActivationRequest,
    graph_resource_id: crate::oplog::CanonicalGraphResourceId,
) -> LocalActivationIdentityV1 {
    LocalActivationIdentityV1::new(
        request.identities.workspace_id,
        request.identities.lineage_digest,
        request.identities.catalog_document_id,
        request.identities.endpoint_id,
        request.identities.device_id,
        graph_resource_id,
        PreparationId::from_uuid(request.identities.preparation_id),
        request.identities.session_id,
    )
}

struct ApplicationBlockRef<'a> {
    block: &'a BlockDto,
    parent: Option<usize>,
    depth: usize,
}

fn flatten_application_blocks(blocks: &[BlockDto]) -> Vec<ApplicationBlockRef<'_>> {
    let mut output = Vec::new();
    let mut stack = blocks
        .iter()
        .rev()
        .map(|block| (block, None, 1_usize))
        .collect::<Vec<_>>();
    while let Some((block, parent, depth)) = stack.pop() {
        let index = output.len();
        output.push(ApplicationBlockRef {
            block,
            parent,
            depth,
        });
        stack.extend(
            block
                .children
                .iter()
                .rev()
                .map(|child| (child, Some(index), depth.saturating_add(1))),
        );
    }
    output
}

fn flatten_application_blocks_bounded(
    blocks: &[BlockDto],
    block_limit: usize,
) -> Result<Vec<ApplicationBlockRef<'_>>, SyncApplicationPageRequestError> {
    if blocks.len() > block_limit {
        return Err(SyncApplicationPageRequestError::RequestTooLarge(
            SyncEditorRequestSize {
                blocks: block_limit + 1,
                ..SyncEditorRequestSize::default()
            },
        ));
    }
    let mut output = Vec::with_capacity(blocks.len());
    let mut stack = blocks
        .iter()
        .rev()
        .map(|block| (block, None, 1_usize))
        .collect::<Vec<_>>();
    let mut max_depth = 0_usize;
    while let Some((block, parent, depth)) = stack.pop() {
        max_depth = max_depth.max(depth);
        if output.len() == block_limit || depth > MAX_SYNC_EDITOR_DEPTH {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(
                SyncEditorRequestSize {
                    blocks: output.len().saturating_add(1),
                    depth: max_depth,
                    ..SyncEditorRequestSize::default()
                },
            ));
        }
        let retained_after_current = output.len().saturating_add(stack.len()).saturating_add(1);
        if block.children.len() > block_limit.saturating_sub(retained_after_current) {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(
                SyncEditorRequestSize {
                    blocks: block_limit + 1,
                    depth: max_depth,
                    ..SyncEditorRequestSize::default()
                },
            ));
        }
        let index = output.len();
        output.push(ApplicationBlockRef {
            block,
            parent,
            depth,
        });
        stack.extend(
            block
                .children
                .iter()
                .rev()
                .map(|child| (child, Some(index), depth.saturating_add(1))),
        );
    }
    Ok(output)
}

fn validate_application_load_request(
    request: &SyncApplicationPageLoadRequest,
) -> Result<(), SyncApplicationPageRequestError> {
    match &request.page {
        SyncApplicationPageSelector::Logical { name, .. } => {
            if name.len() > MAX_SYNC_EDITOR_REQUEST_BYTES {
                return Err(SyncApplicationPageRequestError::RequestTooLarge(
                    SyncEditorRequestSize {
                        text_bytes: MAX_SYNC_EDITOR_REQUEST_BYTES + 1,
                        ..SyncEditorRequestSize::default()
                    },
                ));
            }
            LogicalPageName::parse(name.clone()).map_err(|_| {
                SyncApplicationPageRequestError::InvalidRequest(
                    SyncApplicationPageInvalidRequest::InvalidName,
                )
            })?;
        }
        SyncApplicationPageSelector::ExactPath { path } => {
            if path.len() > MAX_LOCAL_MUTATION_PATH_BYTES {
                return Err(SyncApplicationPageRequestError::RequestTooLarge(
                    SyncEditorRequestSize {
                        text_bytes: MAX_SYNC_EDITOR_REQUEST_BYTES.min(path.len()),
                        ..SyncEditorRequestSize::default()
                    },
                ));
            }
            ManagedPath::parse(path.clone()).map_err(|_| {
                SyncApplicationPageRequestError::InvalidRequest(
                    SyncApplicationPageInvalidRequest::InvalidPath,
                )
            })?;
        }
    }
    Ok(())
}

fn validate_application_navigation_request(
    request: &SyncApplicationNavigationRequest,
) -> Result<(), SyncApplicationPageRequestError> {
    if let SyncApplicationNavigationRequest::BacklinkFilterContext { name, targets } = request {
        let text_bytes = name
            .len()
            .checked_add(
                targets
                    .iter()
                    .map(|target| target.page.len().saturating_add(target.block_id.len()))
                    .try_fold(0_usize, usize::checked_add)
                    .unwrap_or(usize::MAX),
            )
            .unwrap_or(usize::MAX);
        if targets.len() > MAX_SYNC_APPLICATION_RESULT_ROWS
            || text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES
        {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(
                SyncEditorRequestSize {
                    blocks: targets.len(),
                    text_bytes,
                    ..SyncEditorRequestSize::default()
                },
            ));
        }
        return Ok(());
    }
    if let SyncApplicationNavigationRequest::PropertyFacets {
        hidden_properties,
        max_items,
        max_bytes,
        ..
    } = request
    {
        let text_bytes = hidden_properties
            .iter()
            .map(String::len)
            .try_fold(0_usize, usize::checked_add)
            .unwrap_or(usize::MAX);
        if hidden_properties.len() > MAX_SYNC_APPLICATION_PAGE_BLOCKS
            || text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES
            || *max_items == 0
            || *max_items > MAX_SYNC_APPLICATION_RESULT_ROWS
            || *max_bytes == 0
            || *max_bytes > MAX_SYNC_APPLICATION_RESULT_BYTES
        {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(
                SyncEditorRequestSize {
                    blocks: hidden_properties.len().max(*max_items),
                    text_bytes: text_bytes.max(*max_bytes),
                    ..SyncEditorRequestSize::default()
                },
            ));
        }
        return Ok(());
    }
    if let SyncApplicationNavigationRequest::ExportQuerySubtrees {
        specs,
        max_queries,
        max_roots,
        max_nodes,
        max_bytes,
    } = request
    {
        let text_bytes = specs
            .iter()
            .map(|spec| spec.key.len().saturating_add(spec.query.len()))
            .try_fold(0_usize, usize::checked_add)
            .unwrap_or(usize::MAX);
        if specs.len() > MAX_SYNC_APPLICATION_RESULT_ROWS
            || text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES
            || *max_queries == 0
            || *max_queries > MAX_SYNC_APPLICATION_RESULT_ROWS
            || *max_roots == 0
            || *max_roots > MAX_SYNC_APPLICATION_RESULT_ROWS
            || *max_nodes == 0
            || *max_nodes > MAX_SYNC_APPLICATION_PAGE_BLOCKS
            || *max_bytes == 0
            || *max_bytes > MAX_SYNC_APPLICATION_RESULT_BYTES
        {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(
                SyncEditorRequestSize {
                    blocks: specs.len().max(*max_nodes),
                    text_bytes: text_bytes.max(*max_bytes),
                    ..SyncEditorRequestSize::default()
                },
            ));
        }
        return Ok(());
    }
    if let SyncApplicationNavigationRequest::AdvancedQuery {
        query,
        current_page,
        max_rows,
        max_bytes,
    } = request
    {
        let text_bytes = query
            .len()
            .saturating_add(current_page.as_ref().map_or(0, String::len));
        if !crate::query::query_source_within_limit(query)
            || !crate::query::query_nesting_within_limit(query)
            || *max_rows == 0
            || *max_rows > MAX_SYNC_APPLICATION_RESULT_ROWS
            || *max_bytes == 0
            || *max_bytes > MAX_SYNC_APPLICATION_RESULT_BYTES
            || text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES
        {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(
                SyncEditorRequestSize {
                    blocks: *max_rows,
                    text_bytes: text_bytes.max(*max_bytes),
                    ..SyncEditorRequestSize::default()
                },
            ));
        }
        return Ok(());
    }
    if let SyncApplicationNavigationRequest::GraphSearch {
        source,
        page_limit,
        block_limit,
        lane,
        scope,
        ..
    } = request
    {
        let rows = page_limit.saturating_add(*block_limit);
        let text_bytes = source
            .len()
            .saturating_add(lane.as_ref().map_or(0, String::len))
            .saturating_add(scope.as_ref().map_or(0, |scope| {
                scope
                    .name
                    .len()
                    .saturating_add(scope.path.as_ref().map_or(0, String::len))
            }));
        if rows > MAX_SYNC_APPLICATION_RESULT_ROWS || text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(
                SyncEditorRequestSize {
                    blocks: rows,
                    text_bytes,
                    ..SyncEditorRequestSize::default()
                },
            ));
        }
        return Ok(());
    }
    if let SyncApplicationNavigationRequest::BlockSearch { query, limit, lane } = request {
        let text_bytes = query
            .len()
            .saturating_add(lane.as_ref().map_or(0, String::len));
        if *limit > MAX_SYNC_APPLICATION_RESULT_ROWS || text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(
                SyncEditorRequestSize {
                    blocks: *limit,
                    text_bytes,
                    ..SyncEditorRequestSize::default()
                },
            ));
        }
        return Ok(());
    }
    let (names, query, limit) = match request {
        SyncApplicationNavigationRequest::ReferencedPageNames { .. }
        | SyncApplicationNavigationRequest::PageAliases
        | SyncApplicationNavigationRequest::ListTemplates
        | SyncApplicationNavigationRequest::OrphanAssets => (&[][..], None, None),
        SyncApplicationNavigationRequest::PageIcons { names }
        | SyncApplicationNavigationRequest::ExistingPageNames { names } => {
            (names.as_slice(), None, None)
        }
        SyncApplicationNavigationRequest::QuickSwitch { query, limit } => {
            (&[][..], Some(query.as_str()), Some(*limit))
        }
        SyncApplicationNavigationRequest::ResolveBlocks { uuids } => {
            (uuids.as_slice(), None, Some(uuids.len()))
        }
        SyncApplicationNavigationRequest::PreviewBlock {
            uuid,
            max_nodes,
            max_bytes,
        } => {
            if *max_nodes == 0
                || *max_nodes > MAX_SYNC_APPLICATION_PAGE_BLOCKS
                || *max_bytes == 0
                || *max_bytes > MAX_SYNC_APPLICATION_RESULT_BYTES
            {
                return Err(SyncApplicationPageRequestError::RequestTooLarge(
                    SyncEditorRequestSize {
                        blocks: *max_nodes,
                        text_bytes: *max_bytes,
                        ..SyncEditorRequestSize::default()
                    },
                ));
            }
            (&[][..], Some(uuid.as_str()), None)
        }
        SyncApplicationNavigationRequest::BlockReferenceCounts => (&[][..], None, None),
        SyncApplicationNavigationRequest::BlockReferrers {
            uuid,
            max_rows,
            max_bytes,
        } => {
            if *max_rows == 0
                || *max_rows > MAX_SYNC_APPLICATION_RESULT_ROWS
                || *max_bytes == 0
                || *max_bytes > MAX_SYNC_APPLICATION_RESULT_BYTES
            {
                return Err(SyncApplicationPageRequestError::RequestTooLarge(
                    SyncEditorRequestSize {
                        blocks: *max_rows,
                        text_bytes: *max_bytes,
                        ..SyncEditorRequestSize::default()
                    },
                ));
            }
            (&[][..], Some(uuid.as_str()), None)
        }
        SyncApplicationNavigationRequest::Backlinks {
            name,
            max_rows,
            max_bytes,
        }
        | SyncApplicationNavigationRequest::UnlinkedReferences {
            name,
            max_rows,
            max_bytes,
        } => {
            if name.len() > MAX_MATERIALIZATION_QUERY_BYTES
                || *max_rows == 0
                || *max_rows > MAX_SYNC_APPLICATION_RESULT_ROWS
                || *max_bytes == 0
                || *max_bytes > MAX_SYNC_APPLICATION_RESULT_BYTES
            {
                return Err(SyncApplicationPageRequestError::RequestTooLarge(
                    SyncEditorRequestSize {
                        blocks: *max_rows,
                        text_bytes: *max_bytes,
                        ..SyncEditorRequestSize::default()
                    },
                ));
            }
            (&[][..], Some(name.as_str()), None)
        }
        SyncApplicationNavigationRequest::SimpleQuery {
            query,
            max_rows,
            max_bytes,
        } => {
            if !crate::query::query_source_within_limit(query)
                || !crate::query::query_nesting_within_limit(query)
                || *max_rows == 0
                || *max_rows > MAX_SYNC_APPLICATION_RESULT_ROWS
                || *max_bytes == 0
                || *max_bytes > MAX_SYNC_APPLICATION_RESULT_BYTES
            {
                return Err(SyncApplicationPageRequestError::RequestTooLarge(
                    SyncEditorRequestSize {
                        blocks: *max_rows,
                        text_bytes: query.len().max(*max_bytes),
                        ..SyncEditorRequestSize::default()
                    },
                ));
            }
            (&[][..], Some(query.as_str()), None)
        }
        SyncApplicationNavigationRequest::BacklinkFilterContext { .. } => unreachable!(),
        SyncApplicationNavigationRequest::PropertyFacets { .. } => unreachable!(),
        SyncApplicationNavigationRequest::GraphSearch { .. }
        | SyncApplicationNavigationRequest::BlockSearch { .. }
        | SyncApplicationNavigationRequest::AdvancedQuery { .. }
        | SyncApplicationNavigationRequest::ExportQuerySubtrees { .. } => unreachable!(),
    };
    if names.len() > MAX_SYNC_APPLICATION_PAGE_BLOCKS {
        return Err(SyncApplicationPageRequestError::RequestTooLarge(
            SyncEditorRequestSize {
                blocks: names.len(),
                ..SyncEditorRequestSize::default()
            },
        ));
    }
    let text_bytes = names
        .iter()
        .map(String::len)
        .chain(query.into_iter().map(str::len))
        .try_fold(0_usize, usize::checked_add)
        .unwrap_or(usize::MAX);
    if text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES
        || limit.is_some_and(|limit| limit > MAX_MATERIALIZATION_QUERY_ROWS)
    {
        return Err(SyncApplicationPageRequestError::RequestTooLarge(
            SyncEditorRequestSize {
                text_bytes,
                blocks: limit.unwrap_or_default(),
                ..SyncEditorRequestSize::default()
            },
        ));
    }
    Ok(())
}

fn validate_application_save_request(
    request: &SyncApplicationPageSaveRequest,
) -> Result<(), SyncApplicationPageRequestError> {
    let mut size = validate_application_page_bounds(&request.page)?;
    match &request.target {
        SyncApplicationPageSaveTarget::Existing { path, revision }
        | SyncApplicationPageSaveTarget::ResolveConflict {
            path,
            observed_revision: revision,
        } => {
            if path.len() > MAX_LOCAL_MUTATION_PATH_BYTES {
                editor_charge_text(&mut size, path.len());
                return Err(SyncApplicationPageRequestError::RequestTooLarge(size));
            }
            if ManagedPath::parse(path.clone()).is_err() {
                return Err(SyncApplicationPageRequestError::InvalidRequest(
                    SyncApplicationPageInvalidRequest::InvalidPath,
                ));
            }
            editor_charge_text(&mut size, path.len());
            editor_charge_text(&mut size, revision.len());
        }
        SyncApplicationPageSaveTarget::New { name, .. } => {
            LogicalPageName::parse(name.clone()).map_err(|_| {
                SyncApplicationPageRequestError::InvalidRequest(
                    SyncApplicationPageInvalidRequest::InvalidName,
                )
            })?;
            editor_charge_text(&mut size, name.len());
        }
    }
    if application_page_request_too_large(size) {
        return Err(SyncApplicationPageRequestError::RequestTooLarge(size));
    }
    Ok(())
}

fn validate_application_move_request(
    request: &SyncApplicationMoveSubtreesRequest,
) -> Result<(), SyncApplicationPageRequestError> {
    if Uuid::parse_str(&request.episode_id).is_err() || request.roots.is_empty() {
        return Err(SyncApplicationPageRequestError::InvalidRequest(
            SyncApplicationPageInvalidRequest::MalformedPage,
        ));
    }
    for path in [&request.source_path, &request.destination_path] {
        if path.len() > MAX_LOCAL_MUTATION_PATH_BYTES || ManagedPath::parse(path.clone()).is_err() {
            return Err(SyncApplicationPageRequestError::InvalidRequest(
                SyncApplicationPageInvalidRequest::InvalidPath,
            ));
        }
    }
    let mut size = SyncEditorRequestSize {
        blocks: request.roots.len().min(MAX_SYNC_EDITOR_BLOCKS + 1),
        ..SyncEditorRequestSize::default()
    };
    for value in [
        request.episode_id.as_str(),
        request.source_path.as_str(),
        request.source_revision.as_str(),
        request.destination_path.as_str(),
        request.destination_revision.as_str(),
    ] {
        editor_charge_text(&mut size, value.len());
    }
    for root in request.roots.iter().take(MAX_SYNC_EDITOR_BLOCKS + 1) {
        editor_charge_text(&mut size, root.identity.len());
        if let Some(rewrite) = &root.raw_rewrite {
            editor_charge_text(&mut size, rewrite.expected_raw.len());
            editor_charge_text(&mut size, rewrite.desired_raw.len());
        }
    }
    if let SyncApplicationMovePlacement::Child {
        parent_identity, ..
    } = &request.placement
    {
        editor_charge_text(&mut size, parent_identity.len());
    }
    if request.roots.len() > MAX_SYNC_EDITOR_BLOCKS || application_page_request_too_large(size) {
        return Err(SyncApplicationPageRequestError::RequestTooLarge(size));
    }
    Ok(())
}

fn application_move_request_digest(
    request: &SyncApplicationMoveSubtreesRequest,
) -> Result<ContentDigest, SyncApplicationPageRequestError> {
    // Admission is binding-generation evidence, not move semantics. Excluding
    // it lets an exact already-authored episode resolve after native limits
    // change while every identity, revision, placement, and rewrite remains
    // byte-for-byte bound.
    let bytes = postcard::to_allocvec(&(
        b"tine/application-move-request/v2".as_slice(),
        request.episode_id.as_str(),
        request.source_path.as_str(),
        request.source_revision.as_str(),
        request.destination_path.as_str(),
        request.destination_revision.as_str(),
        &request.roots,
        &request.placement,
    ))
    .map_err(|_| SyncApplicationPageRequestError::ActorRefusedAt("move_episode_digest"))?;
    Ok(ContentDigest::of(&bytes))
}

fn validate_application_graph_mutation_request(
    request: &SyncApplicationGraphMutationRequest,
) -> Result<(), SyncApplicationPageRequestError> {
    if let SyncApplicationGraphMutationRequest::TrashJournalFile { name } = request {
        if name.is_empty()
            || name.contains('/')
            || name.contains('\\')
            || name.len() > MAX_LOCAL_MUTATION_PATH_BYTES
        {
            return Err(SyncApplicationPageRequestError::InvalidRequest(
                SyncApplicationPageInvalidRequest::InvalidPath,
            ));
        }
        return Ok(());
    }
    if let SyncApplicationGraphMutationRequest::ResolveSyncConflict {
        winner_path,
        conflict_path,
        decisions,
        base_revision,
        conflict_revision,
        pre_choice,
    } = request
    {
        if decisions.len() > MAX_SYNC_APPLICATION_PAGE_BLOCKS
            || ManagedPath::parse(winner_path.clone()).is_err()
            || ManagedPath::parse(conflict_path.clone()).is_err()
        {
            return Err(SyncApplicationPageRequestError::InvalidRequest(
                SyncApplicationPageInvalidRequest::InvalidPath,
            ));
        }
        let text_bytes = [
            winner_path.len(),
            conflict_path.len(),
            base_revision.len(),
            conflict_revision.len(),
            pre_choice.len(),
        ]
        .into_iter()
        .chain(
            decisions
                .iter()
                .flat_map(|(key, value)| [key.len(), value.len()]),
        )
        .try_fold(0_usize, usize::checked_add)
        .unwrap_or(usize::MAX);
        if text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(
                SyncEditorRequestSize {
                    text_bytes,
                    ..SyncEditorRequestSize::default()
                },
            ));
        }
        return Ok(());
    }
    let (names, paths): (Vec<&str>, Vec<&str>) = match request {
        SyncApplicationGraphMutationRequest::RenamePage {
            old,
            new,
            expected_path,
        } => (
            vec![old.as_str(), new.as_str()],
            expected_path.as_deref().into_iter().collect(),
        ),
        SyncApplicationGraphMutationRequest::DeletePage {
            name,
            expected_path,
            ..
        } => (
            vec![name.as_str()],
            expected_path.as_deref().into_iter().collect(),
        ),
        SyncApplicationGraphMutationRequest::MergePages {
            source_path,
            destination_path,
            rename_from,
            rename_to,
        } => (
            rename_from
                .iter()
                .chain(rename_to.iter())
                .map(String::as_str)
                .collect(),
            vec![source_path.as_str(), destination_path.as_str()],
        ),
        SyncApplicationGraphMutationRequest::RenameFileToPage { path, new_name } => {
            (vec![new_name.as_str()], vec![path.as_str()])
        }
        SyncApplicationGraphMutationRequest::TrashJournalFile { .. } => unreachable!(),
        SyncApplicationGraphMutationRequest::ResolveSyncConflict { .. } => unreachable!(),
    };
    let text_bytes = names
        .iter()
        .chain(paths.iter())
        .try_fold(0_usize, |total, value| total.checked_add(value.len()))
        .unwrap_or(usize::MAX);
    if text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES {
        return Err(SyncApplicationPageRequestError::RequestTooLarge(
            SyncEditorRequestSize {
                text_bytes,
                ..SyncEditorRequestSize::default()
            },
        ));
    }
    for name in names {
        LogicalPageName::parse(name.to_owned()).map_err(|_| {
            SyncApplicationPageRequestError::InvalidRequest(
                SyncApplicationPageInvalidRequest::InvalidName,
            )
        })?;
    }
    for path in paths {
        if path.len() > MAX_LOCAL_MUTATION_PATH_BYTES
            || ManagedPath::parse(path.to_owned()).is_err()
        {
            return Err(SyncApplicationPageRequestError::InvalidRequest(
                SyncApplicationPageInvalidRequest::InvalidPath,
            ));
        }
    }
    Ok(())
}

fn validate_application_page_bounds(
    page: &PageDto,
) -> Result<SyncEditorRequestSize, SyncApplicationPageRequestError> {
    let flattened =
        flatten_application_blocks_bounded(&page.blocks, MAX_SYNC_APPLICATION_PAGE_BLOCKS)?;
    let mut size = SyncEditorRequestSize {
        blocks: flattened.len().min(MAX_SYNC_APPLICATION_PAGE_BLOCKS + 1),
        ..SyncEditorRequestSize::default()
    };
    for value in [
        Some(page.name.as_str()),
        Some(page.title.as_str()),
        page.pre_block.as_deref(),
        page.rev.as_deref(),
        Some(page.path.as_str()),
    ]
    .into_iter()
    .flatten()
    {
        editor_charge_text(&mut size, value.len());
    }
    if flattened.len() > MAX_SYNC_APPLICATION_PAGE_BLOCKS {
        return Err(SyncApplicationPageRequestError::RequestTooLarge(size));
    }
    let mut identities = HashSet::with_capacity(flattened.len());
    for item in flattened {
        size.depth = size.depth.max(item.depth);
        size.temporary_key_bytes = bounded_charge(
            size.temporary_key_bytes,
            item.block.id.len(),
            MAX_SYNC_EDITOR_REQUEST_BYTES,
        );
        if !identities.insert(item.block.id.as_str()) {
            return Err(SyncApplicationPageRequestError::InvalidRequest(
                SyncApplicationPageInvalidRequest::DuplicateBlockId,
            ));
        }
        for value in [
            Some(item.block.id.as_str()),
            Some(item.block.raw.as_str()),
            item.block.marker.as_deref(),
            item.block.priority.as_deref(),
            item.block.scheduled.as_deref(),
            item.block.deadline.as_deref(),
        ]
        .into_iter()
        .flatten()
        {
            editor_charge_text(&mut size, value.len());
        }
        for value in &item.block.breadcrumb {
            editor_charge_text(&mut size, value.len());
        }
        for value in &item.block.tags {
            editor_charge_text(&mut size, value.len());
        }
        for (name, value) in &item.block.properties {
            editor_charge_text(&mut size, name.len());
            editor_charge_text(&mut size, value.len());
        }
        if item.block.page_property {
            return Err(SyncApplicationPageRequestError::InvalidRequest(
                SyncApplicationPageInvalidRequest::MalformedPage,
            ));
        }
        if application_page_request_too_large(size) {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(size));
        }
    }
    Ok(size)
}

fn validate_editor_load_request(
    request: &SyncEditorLoadRequest,
) -> Result<(), SyncEditorRequestError> {
    match &request.page {
        SyncEditorPageSelector::PageId { page_id } => {
            parse_editor_page_id(page_id)?;
            if page_id.len() > MAX_SYNC_EDITOR_REQUEST_BYTES {
                return Err(editor_too_large(0, 0, 0, page_id.len()));
            }
        }
        SyncEditorPageSelector::Name { name, .. } => {
            LogicalPageName::parse(name.clone()).map_err(|_| {
                SyncEditorRequestError::InvalidRequest(SyncEditorInvalidRequest::InvalidName)
            })?;
            if name.len() > MAX_SYNC_EDITOR_REQUEST_BYTES {
                return Err(editor_too_large(0, 0, 0, name.len()));
            }
        }
    }
    Ok(())
}

fn validate_editor_save_request(
    request: &SyncEditorSaveRequest,
) -> Result<(), SyncEditorRequestError> {
    let mut size = SyncEditorRequestSize {
        blocks: request.blocks.len().min(MAX_SYNC_EDITOR_BLOCKS + 1),
        ..SyncEditorRequestSize::default()
    };
    match &request.target {
        SyncEditorSaveTarget::Existing { page_id, revision } => {
            parse_editor_page_id(page_id)?;
            editor_charge_text(&mut size, page_id.len());
            editor_charge_text(&mut size, revision.len());
        }
        SyncEditorSaveTarget::New { name, revision, .. } => {
            LogicalPageName::parse(name.clone()).map_err(|_| {
                SyncEditorRequestError::InvalidRequest(SyncEditorInvalidRequest::InvalidName)
            })?;
            editor_charge_text(&mut size, name.len());
            editor_charge_text(&mut size, revision.len());
        }
    }
    editor_charge_text(&mut size, request.preamble.as_ref().map_or(0, String::len));
    if request.blocks.len() > MAX_SYNC_EDITOR_BLOCKS {
        return Err(SyncEditorRequestError::RequestTooLarge(size));
    }

    let mut indexes = HashMap::with_capacity(request.blocks.len());
    for (index, block) in request.blocks.iter().enumerate() {
        validate_editor_key(&block.key, &mut size)?;
        if indexes.insert(block.key.clone(), index).is_some() {
            return Err(SyncEditorRequestError::InvalidRequest(
                SyncEditorInvalidRequest::DuplicateKey,
            ));
        }
        if let Some(parent) = &block.parent {
            validate_editor_key(parent, &mut size)?;
        }
        editor_charge_text(&mut size, block.content.len());
        if editor_request_too_large(size) {
            return Err(SyncEditorRequestError::RequestTooLarge(size));
        }
    }

    let mut children = vec![Vec::new(); request.blocks.len()];
    let mut indegree = vec![0_u8; request.blocks.len()];
    for (index, block) in request.blocks.iter().enumerate() {
        let Some(parent) = &block.parent else {
            continue;
        };
        let Some(parent_index) = indexes.get(parent).copied() else {
            return Err(SyncEditorRequestError::InvalidRequest(
                SyncEditorInvalidRequest::UnknownParent,
            ));
        };
        children[parent_index].push(index);
        indegree[index] = 1;
    }
    let mut queue = VecDeque::new();
    let mut depths = vec![0_usize; request.blocks.len()];
    for (index, degree) in indegree.iter().enumerate() {
        if *degree == 0 {
            depths[index] = 1;
            queue.push_back(index);
        }
    }
    let mut visited = 0_usize;
    while let Some(index) = queue.pop_front() {
        visited += 1;
        size.depth = size.depth.max(depths[index]);
        if size.depth > MAX_SYNC_EDITOR_DEPTH {
            return Err(SyncEditorRequestError::RequestTooLarge(size));
        }
        for child in &children[index] {
            depths[*child] = depths[index].saturating_add(1);
            indegree[*child] -= 1;
            if indegree[*child] == 0 {
                queue.push_back(*child);
            }
        }
    }
    if visited != request.blocks.len() {
        return Err(SyncEditorRequestError::InvalidRequest(
            SyncEditorInvalidRequest::CyclicOutline,
        ));
    }
    if editor_request_too_large(size) {
        return Err(SyncEditorRequestError::RequestTooLarge(size));
    }
    Ok(())
}

fn validate_editor_key(
    key: &SyncEditorBlockKey,
    size: &mut SyncEditorRequestSize,
) -> Result<(), SyncEditorRequestError> {
    match key {
        SyncEditorBlockKey::Existing(id) => {
            parse_editor_block_id(id)?;
            editor_charge_text(size, id.len());
        }
        SyncEditorBlockKey::Temporary(key) => {
            if key.is_empty() {
                return Err(SyncEditorRequestError::InvalidRequest(
                    SyncEditorInvalidRequest::EmptyTemporaryKey,
                ));
            }
            if key
                .chars()
                .any(|character| matches!(character, '\0' | '\r' | '\n'))
            {
                return Err(SyncEditorRequestError::InvalidRequest(
                    SyncEditorInvalidRequest::InvalidTemporaryKey,
                ));
            }
            size.temporary_key_bytes = bounded_charge(
                size.temporary_key_bytes,
                key.len(),
                MAX_SYNC_EDITOR_REQUEST_BYTES,
            );
            editor_charge_text(size, key.len());
            if key.len() > MAX_SYNC_EDITOR_TEMP_KEY_BYTES {
                return Err(SyncEditorRequestError::RequestTooLarge(*size));
            }
        }
    }
    Ok(())
}

fn validate_activation_paths(
    request: &SyncLocalActivationRequest,
    graph_root: &Path,
) -> Result<(), String> {
    let canonical_graph = fs::canonicalize(graph_root)
        .map_err(|error| format!("cannot canonicalize graph root for activation: {error}"))?;
    let expected_provider = canonical_graph.join(".tine-sync").join("v2").join("shared");
    if normalize_absolute(&request.provider_root)? != expected_provider {
        return Err(
            "provider_root must be exactly the graph's .tine-sync/v2/shared namespace".into(),
        );
    }

    let private_paths = [
        (&request.archive_root, "archive_root"),
        (&request.enrollment_root, "enrollment_root"),
        (&request.receipt_root, "receipt_root"),
        (
            &request.application_runtime_root,
            "application_runtime_root",
        ),
        (&request.capture_root, "capture_root"),
        (&request.preparation_root, "preparation_root"),
        (&request.provider_journal_root, "provider_journal_root"),
    ];
    for (path, label) in private_paths {
        require_private_path_outside_graph(path, label, &canonical_graph)?;
    }
    let database_parent = request
        .database_path
        .parent()
        .ok_or_else(|| "database_path has no parent directory".to_owned())?;
    require_private_path_outside_graph(database_parent, "database_path", &canonical_graph)?;
    Ok(())
}

fn prepare_activation_private_paths(request: &SyncLocalActivationRequest) -> Result<(), String> {
    for path in [&request.capture_root, &request.preparation_root] {
        fs::create_dir_all(path)
            .map_err(|error| format!("cannot create private activation directory: {error}"))?;
        let metadata = fs::symlink_metadata(path)
            .map_err(|error| format!("cannot inspect private activation directory: {error}"))?;
        if metadata.file_type().is_symlink() || !metadata.is_dir() {
            return Err("private activation path is not a real directory".into());
        }
    }
    let database_parent = request
        .database_path
        .parent()
        .ok_or_else(|| "database_path has no parent directory".to_owned())?;
    fs::create_dir_all(database_parent)
        .map_err(|error| format!("cannot create private database parent: {error}"))?;
    Ok(())
}

fn require_private_path_outside_graph(
    path: &Path,
    label: &str,
    graph_root: &Path,
) -> Result<(), String> {
    let normalized = normalize_absolute(path)?;
    if normalized == graph_root || normalized.starts_with(graph_root) {
        return Err(format!("{label} must be outside the graph root"));
    }
    let mut existing = normalized.clone();
    loop {
        match fs::symlink_metadata(&existing) {
            Ok(_) => break,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                if !existing.pop() {
                    return Err(format!("{label} has no existing ancestor"));
                }
            }
            Err(error) => {
                return Err(format!("cannot inspect {label} ancestor: {error}"));
            }
        }
    }
    let canonical_existing = fs::canonicalize(&existing)
        .map_err(|error| format!("cannot canonicalize {label} ancestor: {error}"))?;
    if canonical_existing == graph_root || canonical_existing.starts_with(graph_root) {
        return Err(format!("{label} resolves inside the graph root"));
    }
    Ok(())
}

fn normalize_absolute(path: &Path) -> Result<PathBuf, String> {
    let input = if path.is_absolute() {
        path.to_path_buf()
    } else {
        std::env::current_dir()
            .map_err(|error| format!("cannot determine current directory: {error}"))?
            .join(path)
    };
    let mut normalized = PathBuf::new();
    for component in input.components() {
        match component {
            Component::Prefix(prefix) => normalized.push(prefix.as_os_str()),
            Component::RootDir => normalized.push(component.as_os_str()),
            Component::CurDir => {}
            Component::ParentDir => {
                if !normalized.pop() {
                    return Err("activation path escapes its root".into());
                }
            }
            Component::Normal(part) => normalized.push(part),
        }
    }
    Ok(normalized)
}

fn editor_charge_text(size: &mut SyncEditorRequestSize, bytes: usize) {
    size.text_bytes = bounded_charge(size.text_bytes, bytes, MAX_SYNC_EDITOR_REQUEST_BYTES);
}

fn editor_request_too_large(size: SyncEditorRequestSize) -> bool {
    size.blocks > MAX_SYNC_EDITOR_BLOCKS
        || size.depth > MAX_SYNC_EDITOR_DEPTH
        || size.text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES
}

fn application_page_request_too_large(size: SyncEditorRequestSize) -> bool {
    size.blocks > MAX_SYNC_APPLICATION_PAGE_BLOCKS
        || size.depth > MAX_SYNC_EDITOR_DEPTH
        || size.text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES
}

fn editor_too_large(
    blocks: usize,
    depth: usize,
    temporary_key_bytes: usize,
    text_bytes: usize,
) -> SyncEditorRequestError {
    SyncEditorRequestError::RequestTooLarge(SyncEditorRequestSize {
        blocks,
        depth,
        temporary_key_bytes,
        text_bytes,
    })
}

fn parse_editor_page_id(value: &str) -> Result<PageId, SyncEditorRequestError> {
    uuid::Uuid::parse_str(value)
        .map(PageId::from_uuid)
        .map_err(|_| {
            SyncEditorRequestError::InvalidRequest(SyncEditorInvalidRequest::InvalidExistingId)
        })
}

fn parse_editor_block_id(value: &str) -> Result<BlockId, SyncEditorRequestError> {
    uuid::Uuid::parse_str(value)
        .map(BlockId::from_uuid)
        .map_err(|_| {
            SyncEditorRequestError::InvalidRequest(SyncEditorInvalidRequest::InvalidExistingId)
        })
}

fn refused(detail: String) -> SyncRuntimeOpenResult {
    SyncRuntimeOpenResult {
        status: SyncRuntimeOpenStatus::OpenRefused { detail },
        handle: None,
    }
}

fn map_discovery(classification: DiscoveryClassification) -> SyncRuntimeOpenStatus {
    match classification {
        DiscoveryClassification::LegacyDefault => SyncRuntimeOpenStatus::LegacyDefault,
        DiscoveryClassification::Absent => SyncRuntimeOpenStatus::Absent,
        DiscoveryClassification::ExistingLocalActive(_) => SyncRuntimeOpenStatus::Active,
        DiscoveryClassification::ExistingNonActive(advisory) => {
            SyncRuntimeOpenStatus::ExistingNonActive(match advisory.stage {
                NonActiveStage::ShadowImport => SyncNonActiveStage::ShadowImport,
                NonActiveStage::VerifiedLocal => SyncNonActiveStage::VerifiedLocal,
            })
        }
        DiscoveryClassification::Blocked(advisory) => SyncRuntimeOpenStatus::Blocked {
            reason_code: advisory.reason_code,
        },
        DiscoveryClassification::Retryable(_, detail) => {
            SyncRuntimeOpenStatus::OpenRefused { detail }
        }
        DiscoveryClassification::UnsupportedOrIncompatible(component, scenario) => {
            SyncRuntimeOpenStatus::UnsupportedOrIncompatible {
                component: map_component(component),
                scenario,
            }
        }
        DiscoveryClassification::CorruptOrUnreadable(component, scenario) => {
            SyncRuntimeOpenStatus::CorruptOrUnreadable {
                component: map_component(component),
                scenario,
            }
        }
        DiscoveryClassification::AmbiguousOrForeignResidue(evidence, scenario) => {
            SyncRuntimeOpenStatus::AmbiguousOrForeignResidue {
                evidence: map_ambiguous_evidence(evidence),
                scenario,
            }
        }
    }
}

fn shared_namespace_digest(workspace_id: WorkspaceId) -> ContentDigest {
    let mut hasher = Sha256::new();
    hasher.update(b"tine/shared-provider-namespace/v1\0");
    hasher.update(workspace_id.to_string().as_bytes());
    ContentDigest::from_bytes(hasher.finalize().into())
}

fn publish_provider_object_exact(
    provider: &mut SharedProviderTransport,
    digest: ContentDigest,
    bytes: &[u8],
) -> Result<(), SyncRuntimeRequestError> {
    if ContentDigest::of(bytes) != digest {
        return Err(SyncRuntimeRequestError::ActorRefused(format!(
            "local provider object bytes do not match {digest}"
        )));
    }
    // Physical visibility is not publication completion. The transport owns
    // both the authenticated retry journal and the exact-existing durability
    // proof, including directory sync and same-file identity revalidation.
    provider
        .publish_object_exact(digest, bytes)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))
}

/// Publish the complete clean accepted tail without manufacturing legacy
/// enrollment recovery records.  Objects become visible first and each
/// manifest remains the commit marker.  The clean enrollment descriptor is
/// published only after this function returns, so a partially copied prefix
/// cannot advertise a joinable graph.
fn publish_complete_clean_archive(
    store: &ObjectStore,
    provider: &mut SharedProviderTransport,
    workspace_id: WorkspaceId,
    lineage_digest: LineageDigest,
) -> Result<(), SyncRuntimeRequestError> {
    let manifests = store
        .committed_manifests()
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    for manifest in &manifests {
        if manifest.workspace_id() != workspace_id || manifest.lineage_digest() != lineage_digest {
            return Err(SyncRuntimeRequestError::ActorRefused(format!(
                "clean accepted manifest {} is outside the sharing namespace",
                manifest.batch_id()
            )));
        }
        for object in manifest.required_objects() {
            let bytes = store
                .read_object_bytes(object.content_digest())
                .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
            publish_provider_object_exact(provider, object.content_digest(), &bytes)?;
        }
    }
    for manifest in manifests {
        let bytes = store
            .read_manifest_bytes(manifest.batch_id())
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        if OperationBatch::decode(&bytes)
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
            != manifest
        {
            return Err(SyncRuntimeRequestError::ActorRefused(format!(
                "clean accepted manifest {} changed during provider publication",
                manifest.batch_id()
            )));
        }
        publish_clean_manifest_exact(provider, manifest.batch_id(), &bytes)?;
    }
    Ok(())
}

fn clean_baseline_index_provider_path(root: ContentDigest) -> String {
    format!("{SHARED_PROVIDER_CLEAN_BASELINES_NAMESPACE}/{root}.index")
}

fn clean_baseline_chunk_provider_path(
    root: ContentDigest,
    file_ordinal: usize,
    chunk_ordinal: usize,
) -> String {
    format!(
        "{SHARED_PROVIDER_CLEAN_BASELINES_NAMESPACE}/{root}.{file_ordinal:08}.{chunk_ordinal:08}.chunk"
    )
}

/// Publish one exact lazy-genesis pack without routing its potentially large
/// files through an unbounded provider-journal blob. Every file is split into
/// fixed-size exact chunks; the small index is published last and is itself
/// bound into the shared descriptor, which remains the final joinability
/// marker.
fn publish_complete_clean_baseline(
    engine: &ShardedHotEngine,
    provider: &mut SharedProviderTransport,
) -> Result<BlobDescription, SyncRuntimeRequestError> {
    let index = engine
        .clean_baseline_provider_index()
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    for (file_ordinal, (name, expected)) in index.file_descriptions().into_iter().enumerate() {
        let bytes = engine
            .clean_baseline_provider_file(&name)
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        if BlobDescription::of(&bytes) != expected {
            return Err(SyncRuntimeRequestError::ActorRefused(format!(
                "clean baseline file {name} changed during provider publication"
            )));
        }
        for (chunk_ordinal, chunk) in bytes.chunks(LAZY_GENESIS_PROVIDER_CHUNK_BYTES).enumerate() {
            let path = clean_baseline_chunk_provider_path(
                index.baseline_root(),
                file_ordinal,
                chunk_ordinal,
            );
            provider
                .publish_clean_baseline_part(&path, chunk)
                .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        }
    }
    let bytes = index
        .encode()
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    provider
        .publish_clean_baseline_part(
            &clean_baseline_index_provider_path(index.baseline_root()),
            &bytes,
        )
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    Ok(BlobDescription::of(&bytes))
}

struct CleanJoinCandidate {
    staging_root: PathBuf,
    baseline_directory: PathBuf,
    operation_archive_directory: PathBuf,
    engine: Option<ShardedHotEngine>,
    baseline_frontier_digest: ContentDigest,
}

impl Drop for CleanJoinCandidate {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.staging_root);
    }
}

#[derive(Debug, Eq, PartialEq)]
struct CleanJoinUserPage {
    path: String,
    kind: ManagedTextKind,
    preamble: Option<String>,
    outline: Vec<(usize, String, Option<LogseqUuid>)>,
}

const CLEAN_JOIN_MAX_MISMATCH_DETAILS: usize = 32;

#[derive(Debug, Eq, PartialEq)]
enum CleanJoinMismatchDetail {
    LocalOnly(String),
    SharedOnly(String),
    Changed {
        path: String,
        kind: bool,
        preamble: bool,
        outline: bool,
        explicit_ids: bool,
    },
}

#[derive(Debug, Eq, PartialEq)]
struct CleanJoinSemanticDiff {
    local_pages: usize,
    shared_pages: usize,
    local_only: usize,
    shared_only: usize,
    changed: usize,
    changed_kind: usize,
    changed_preamble: usize,
    changed_outline: usize,
    changed_explicit_ids: usize,
    details: Vec<CleanJoinMismatchDetail>,
}

impl CleanJoinSemanticDiff {
    fn record(&mut self, detail: CleanJoinMismatchDetail) {
        match &detail {
            CleanJoinMismatchDetail::LocalOnly(_) => self.local_only += 1,
            CleanJoinMismatchDetail::SharedOnly(_) => self.shared_only += 1,
            CleanJoinMismatchDetail::Changed {
                kind,
                preamble,
                outline,
                explicit_ids,
                ..
            } => {
                self.changed += 1;
                self.changed_kind += usize::from(*kind);
                self.changed_preamble += usize::from(*preamble);
                self.changed_outline += usize::from(*outline);
                self.changed_explicit_ids += usize::from(*explicit_ids);
            }
        }
        if self.details.len() < CLEAN_JOIN_MAX_MISMATCH_DETAILS {
            self.details.push(detail);
        }
    }

    fn mismatch_count(&self) -> usize {
        self.local_only + self.shared_only + self.changed
    }
}

impl fmt::Display for CleanJoinSemanticDiff {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            formatter,
            "sync join refused: notes not in the shared provider frontier; local-pages={} shared-pages={} local-only={} shared-only={} changed={} (kind={} preamble={} outline={} explicit-ids={}); authorities unchanged",
            self.local_pages,
            self.shared_pages,
            self.local_only,
            self.shared_only,
            self.changed,
            self.changed_kind,
            self.changed_preamble,
            self.changed_outline,
            self.changed_explicit_ids,
        )?;
        for detail in &self.details {
            match detail {
                CleanJoinMismatchDetail::LocalOnly(path) => write!(
                    formatter,
                    "\nclean join mismatch detail: local-only path={path:?}"
                )?,
                CleanJoinMismatchDetail::SharedOnly(path) => write!(
                    formatter,
                    "\nclean join mismatch detail: shared-only path={path:?}"
                )?,
                CleanJoinMismatchDetail::Changed {
                    path,
                    kind,
                    preamble,
                    outline,
                    explicit_ids,
                } => {
                    let mut categories = Vec::new();
                    if *kind {
                        categories.push("kind");
                    }
                    if *preamble {
                        categories.push("preamble");
                    }
                    if *outline {
                        categories.push("outline");
                    }
                    if *explicit_ids {
                        categories.push("explicit-ids");
                    }
                    write!(
                        formatter,
                        "\nclean join mismatch detail: changed path={path:?} categories={}",
                        categories.join(",")
                    )?;
                }
            }
        }
        let omitted = self.mismatch_count().saturating_sub(self.details.len());
        if omitted > 0 {
            write!(
                formatter,
                "\nclean join mismatch detail: {omitted} additional mismatches omitted"
            )?;
        }
        Ok(())
    }
}

fn clean_join_semantic_diff(
    local: &[CleanJoinUserPage],
    shared: &[CleanJoinUserPage],
) -> Option<CleanJoinSemanticDiff> {
    let mut diff = CleanJoinSemanticDiff {
        local_pages: local.len(),
        shared_pages: shared.len(),
        local_only: 0,
        shared_only: 0,
        changed: 0,
        changed_kind: 0,
        changed_preamble: 0,
        changed_outline: 0,
        changed_explicit_ids: 0,
        details: Vec::new(),
    };
    let (mut local_index, mut shared_index) = (0, 0);
    while local_index < local.len() || shared_index < shared.len() {
        match (local.get(local_index), shared.get(shared_index)) {
            (Some(local_page), Some(shared_page)) => match local_page.path.cmp(&shared_page.path) {
                std::cmp::Ordering::Less => {
                    diff.record(CleanJoinMismatchDetail::LocalOnly(local_page.path.clone()));
                    local_index += 1;
                }
                std::cmp::Ordering::Greater => {
                    diff.record(CleanJoinMismatchDetail::SharedOnly(
                        shared_page.path.clone(),
                    ));
                    shared_index += 1;
                }
                std::cmp::Ordering::Equal => {
                    let kind = local_page.kind != shared_page.kind;
                    let preamble = local_page.preamble != shared_page.preamble;
                    let outline = local_page.outline.len() != shared_page.outline.len()
                        || local_page.outline.iter().zip(&shared_page.outline).any(
                            |(
                                (local_depth, local_content, _),
                                (shared_depth, shared_content, _),
                            )| {
                                local_depth != shared_depth || local_content != shared_content
                            },
                        );
                    let explicit_ids = !outline
                        && local_page.outline.iter().zip(&shared_page.outline).any(
                            |((_, _, local_uuid), (_, _, shared_uuid))| local_uuid != shared_uuid,
                        );
                    if kind || preamble || outline || explicit_ids {
                        diff.record(CleanJoinMismatchDetail::Changed {
                            path: local_page.path.clone(),
                            kind,
                            preamble,
                            outline,
                            explicit_ids,
                        });
                    }
                    local_index += 1;
                    shared_index += 1;
                }
            },
            (Some(local_page), None) => {
                diff.record(CleanJoinMismatchDetail::LocalOnly(local_page.path.clone()));
                local_index += 1;
            }
            (None, Some(shared_page)) => {
                diff.record(CleanJoinMismatchDetail::SharedOnly(
                    shared_page.path.clone(),
                ));
                shared_index += 1;
            }
            (None, None) => break,
        }
    }
    (diff.mismatch_count() > 0).then_some(diff)
}

fn clean_join_user_semantics(
    snapshot: CanonicalSnapshot,
) -> Result<Vec<CleanJoinUserPage>, SyncRuntimeRequestError> {
    if !snapshot.path_conflicts.is_empty() {
        return Err(SyncRuntimeRequestError::ActorRefused(
            "clean join cannot compare a graph with conflicting live page paths".into(),
        ));
    }
    let preambles = snapshot
        .page_preambles
        .into_iter()
        .map(|state| (state.page_id, state.preamble))
        .collect::<BTreeMap<_, _>>();
    let blocks = snapshot
        .blocks
        .into_iter()
        .map(|block| {
            let external_uuid = matches!(
                block.logseq_identity_origin,
                Some(LogseqIdentityOrigin::ExternalImported)
            )
            .then_some(block.logseq_uuid)
            .flatten();
            (block.block_id, (block.content, external_uuid))
        })
        .collect::<BTreeMap<_, _>>();
    let mut memberships = BTreeMap::<PageId, Vec<_>>::new();
    for membership in snapshot.memberships {
        memberships
            .entry(membership.page_id)
            .or_default()
            .push(membership);
    }
    let mut pages = Vec::new();
    for (page_id, state) in snapshot.pages {
        let PageState::Live { path, kind, .. } = state else {
            continue;
        };
        let page_memberships = memberships.remove(&page_id).unwrap_or_default();
        let mut children = BTreeMap::<Option<BlockId>, Vec<_>>::new();
        for membership in page_memberships {
            children
                .entry(membership.parent)
                .or_default()
                .push(membership);
        }
        for siblings in children.values_mut() {
            siblings.sort_unstable_by(|left, right| {
                left.order
                    .cmp(&right.order)
                    .then_with(|| left.block_id.cmp(&right.block_id))
            });
        }
        let mut outline = Vec::new();
        let mut pending = children
            .remove(&None)
            .unwrap_or_default()
            .into_iter()
            .rev()
            .map(|membership| (0_usize, membership))
            .collect::<Vec<_>>();
        let mut visited = BTreeSet::new();
        while let Some((depth, membership)) = pending.pop() {
            if !visited.insert(membership.block_id) {
                return Err(SyncRuntimeRequestError::ActorRefused(
                    "clean join semantic comparison found cyclic block structure".into(),
                ));
            }
            let (content, external_uuid) = blocks.get(&membership.block_id).ok_or_else(|| {
                SyncRuntimeRequestError::ActorRefused(
                    "clean join semantic comparison found a missing visible block".into(),
                )
            })?;
            outline.push((depth, content.clone(), *external_uuid));
            if let Some(descendants) = children.remove(&Some(membership.block_id)) {
                pending.extend(
                    descendants
                        .into_iter()
                        .rev()
                        .map(|child| (depth.saturating_add(1), child)),
                );
            }
        }
        if !children.is_empty() {
            return Err(SyncRuntimeRequestError::ActorRefused(
                "clean join semantic comparison found an unreachable block parent".into(),
            ));
        }
        pages.push(CleanJoinUserPage {
            path: path.as_str().to_owned(),
            kind,
            preamble: preambles.get(&page_id).cloned().flatten(),
            outline,
        });
    }
    if !memberships.is_empty() {
        return Err(SyncRuntimeRequestError::ActorRefused(
            "clean join semantic comparison found blocks owned by a missing page".into(),
        ));
    }
    pages.sort_unstable_by(|left, right| left.path.cmp(&right.path));
    Ok(pages)
}

fn matching_clean_join_heads(
    provider: &SharedProviderTransport,
    descriptor: &CleanSharedEnrollmentDescriptorV1,
) -> Result<Vec<SharedProviderFrontierHeadV1>, SyncRuntimeRequestError> {
    let descriptor_digest = descriptor
        .digest()
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    let mut cursor = provider
        .head_observation_cursor()
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    let mut enrollment_head = None;
    let mut heads = BTreeMap::new();
    loop {
        match provider
            .next_observed_path(&mut cursor)
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
        {
            SharedProviderObservation::Path(path)
                if path.starts_with(&format!("{SHARED_PROVIDER_FRONTIER_HEADS_NAMESPACE}/")) =>
            {
                let bytes = provider
                    .read_exact(&path)
                    .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
                    .ok_or_else(|| {
                        SyncRuntimeRequestError::ActorRefused(format!(
                            "clean join frontier head disappeared at {path}"
                        ))
                    })?;
                let head = SharedProviderFrontierHeadV1::decode(&path, &bytes)
                    .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
                if head.workspace_id() == descriptor.workspace_id()
                    && head.lineage_digest() == descriptor.lineage_digest()
                    && head.descriptor_digest() == descriptor_digest
                {
                    if head.author_device_id() == descriptor.initiator_device_id()
                        && head.accepted_frontier_root() == descriptor.accepted_frontier_digest()
                    {
                        if enrollment_head.as_ref().is_some_and(
                            |prior: &SharedProviderFrontierHeadV1| {
                                prior.accepted_generation() != head.accepted_generation()
                                    || prior.frontier_tips() != head.frontier_tips()
                            },
                        ) {
                            return Err(SyncRuntimeRequestError::ActorRefused(
                                "clean join found conflicting initiator heads for the descriptor frontier"
                                    .into(),
                            ));
                        }
                        enrollment_head = Some(head.clone());
                    }
                    heads.insert(path, head);
                }
            }
            SharedProviderObservation::Path(_) => {}
            SharedProviderObservation::ChunkBoundary => cursor.begin_next_chunk(),
            SharedProviderObservation::Complete => break,
        }
    }
    enrollment_head.ok_or_else(|| {
        SyncRuntimeRequestError::ActorRefused(
            "clean shared baseline is present but its matching initiator frontier head has not arrived"
                .into(),
        )
    })?;
    Ok(heads.into_values().collect())
}

fn download_clean_join_tail(
    provider: &SharedProviderTransport,
    descriptor: &CleanSharedEnrollmentDescriptorV1,
    store: &ObjectStore,
    heads: &[SharedProviderFrontierHeadV1],
) -> Result<(), SyncRuntimeRequestError> {
    let mut pending = heads
        .iter()
        .flat_map(|head| head.frontier_tips().iter().copied())
        .collect::<Vec<_>>();
    let mut seen = BTreeSet::new();
    while let Some(batch_id) = pending.pop() {
        if !seen.insert(batch_id) {
            continue;
        }
        let manifest_path = format!("manifests/{batch_id}.manifest");
        let manifest_bytes = provider
            .read_exact(&manifest_path)
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
            .ok_or_else(|| {
                SyncRuntimeRequestError::ActorRefused(format!(
                    "clean join is waiting for provider manifest {batch_id}"
                ))
            })?;
        let manifest = OperationBatch::decode(&manifest_bytes)
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        if manifest.batch_id() != batch_id
            || manifest.workspace_id() != descriptor.workspace_id()
            || manifest.lineage_digest() != descriptor.lineage_digest()
            || manifest.origin() == BatchOrigin::BootstrapImport
        {
            return Err(SyncRuntimeRequestError::ActorRefused(format!(
                "clean join provider manifest {batch_id} is outside the descriptor authority"
            )));
        }
        for object in manifest.required_objects() {
            let path = format!("objects/{}.object", object.content_digest());
            let bytes = provider
                .read_exact(&path)
                .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
                .ok_or_else(|| {
                    SyncRuntimeRequestError::ActorRefused(format!(
                        "clean join is waiting for provider object {}",
                        object.content_digest()
                    ))
                })?;
            if ContentDigest::of(&bytes) != object.content_digest()
                || store
                    .stage_object_bytes(&bytes)
                    .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
                    != object.content_digest()
            {
                return Err(SyncRuntimeRequestError::ActorRefused(format!(
                    "clean join provider object {} has conflicting bytes",
                    object.content_digest()
                )));
            }
        }
        store
            .stage_manifest_bytes(&manifest_bytes)
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        pending.extend(manifest.causal_dependency_heads().iter().copied());
    }
    Ok(())
}

fn prepare_clean_join_candidate(
    request: &SyncRuntimeOpenRequest,
    provider: &SharedProviderTransport,
    descriptor: &CleanSharedEnrollmentDescriptorV1,
) -> Result<CleanJoinCandidate, SyncRuntimeRequestError> {
    let staging_root = request
        .archive_root
        .join(format!(".clean-join-{}", Uuid::new_v4().simple()));
    let baseline_directory = staging_root.join("baseline");
    let operation_archive_directory = staging_root.join("operations");
    fs::create_dir_all(&baseline_directory)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    let result = (|| {
        let index_path = clean_baseline_index_provider_path(descriptor.baseline_root());
        let index_bytes = provider
            .read_exact(&index_path)
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
            .ok_or_else(|| {
                SyncRuntimeRequestError::ActorRefused(
                    "clean shared descriptor arrived before its baseline index".into(),
                )
            })?;
        if BlobDescription::of(&index_bytes) != descriptor.baseline_index() {
            return Err(SyncRuntimeRequestError::ActorRefused(
                "clean shared baseline index differs from the descriptor".into(),
            ));
        }
        let index = LazyGenesisProviderIndexV1::decode(&index_bytes)
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        if index.baseline_root() != descriptor.baseline_root() {
            return Err(SyncRuntimeRequestError::ActorRefused(
                "clean shared baseline index names another root".into(),
            ));
        }
        for (file_ordinal, (name, expected)) in index.file_descriptions().into_iter().enumerate() {
            let mut file = fs::OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(baseline_directory.join(&name))
                .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
            let expected_length = usize::try_from(expected.byte_length()).map_err(|_| {
                SyncRuntimeRequestError::ActorRefused(format!(
                    "clean shared baseline file {name} is not addressable"
                ))
            })?;
            let mut written = 0_usize;
            let mut hasher = Sha256::new();
            for chunk_ordinal in 0..expected_length.div_ceil(LAZY_GENESIS_PROVIDER_CHUNK_BYTES) {
                let path = clean_baseline_chunk_provider_path(
                    descriptor.baseline_root(),
                    file_ordinal,
                    chunk_ordinal,
                );
                let bytes = provider
                    .read_exact(&path)
                    .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
                    .ok_or_else(|| {
                        SyncRuntimeRequestError::ActorRefused(format!(
                            "clean join is waiting for baseline chunk {path}"
                        ))
                    })?;
                let remaining = expected_length.saturating_sub(written);
                let expected_chunk = remaining.min(LAZY_GENESIS_PROVIDER_CHUNK_BYTES);
                if bytes.len() != expected_chunk {
                    return Err(SyncRuntimeRequestError::ActorRefused(format!(
                        "clean shared baseline chunk {path} has the wrong length"
                    )));
                }
                file.write_all(&bytes)
                    .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
                hasher.update(&bytes);
                written = written.saturating_add(bytes.len());
            }
            file.sync_all()
                .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
            let mut digest = [0_u8; 32];
            digest.copy_from_slice(&hasher.finalize());
            if written != expected_length
                || BlobDescription::from_parts(digest, written as u64) != expected
            {
                return Err(SyncRuntimeRequestError::ActorRefused(format!(
                    "clean shared baseline file {name} differs from its index"
                )));
            }
        }
        crate::filesystem_durability::sync_private_tree(&baseline_directory)
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        let baseline = LazyGenesisCandidate::open_provider_staged(&baseline_directory, &index)
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        if baseline.workspace_id() != descriptor.workspace_id()
            || baseline.lineage_digest() != descriptor.lineage_digest()
            || baseline.catalog_document_id() != descriptor.catalog_document_id()
            || baseline.source_capture() != descriptor.source_capture()
        {
            return Err(SyncRuntimeRequestError::ActorRefused(
                "clean shared baseline identity differs from the descriptor".into(),
            ));
        }
        let heads = matching_clean_join_heads(provider, descriptor)?;
        let store = ObjectStore::open(&operation_archive_directory, descriptor.workspace_id())
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        download_clean_join_tail(provider, descriptor, &store, &heads)?;
        let mut engine = ShardedHotEngine::new(
            descriptor.workspace_id(),
            descriptor.lineage_digest(),
            descriptor.catalog_document_id(),
        );
        engine
            .configure_reference_catalog_policy(ReferenceCatalogPolicyV1::default())
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        engine
            .install_lazy_genesis_baseline(Arc::new(baseline))
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        let baseline_frontier = engine
            .accepted_frontier_root()
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        let baseline_frontier_digest =
            crate::oplog::sqlite::canonical_frontier_root_digest(&baseline_frontier)
                .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        engine
            .attach_clean_archive_store(store)
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        let baseline_claim_source = engine
            .clean_transient_projection_claim_snapshot()
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
            .ok_or_else(|| {
                SyncRuntimeRequestError::ActorRefused(
                    "clean join candidate has no lazy-genesis UUID candidates".into(),
                )
            })?;
        engine
            .replay_clean_committed_tail(baseline_claim_source.as_ref())
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        drop(baseline_claim_source);
        for tip in heads
            .iter()
            .flat_map(|head| head.frontier_tips().iter().copied())
        {
            if !engine
                .accepted_frontier_contains_batch_effects(tip)
                .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
            {
                return Err(SyncRuntimeRequestError::ActorRefused(format!(
                    "clean shared baseline and provider tail did not reconstruct frontier tip {tip}"
                )));
            }
        }
        Ok(CleanJoinCandidate {
            staging_root: staging_root.clone(),
            baseline_directory: baseline_directory.clone(),
            operation_archive_directory: operation_archive_directory.clone(),
            engine: Some(engine),
            baseline_frontier_digest,
        })
    })();
    if result.is_err() {
        let _ = fs::remove_dir_all(&staging_root);
    }
    result
}

fn publish_clean_manifest_exact(
    provider: &mut SharedProviderTransport,
    batch_id: BatchId,
    bytes: &[u8],
) -> Result<(), SyncRuntimeRequestError> {
    let path = format!("manifests/{batch_id}.manifest");
    match provider
        .read_exact(&path)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
    {
        Some(existing) if existing == bytes => Ok(()),
        Some(_) => Err(SyncRuntimeRequestError::ActorRefused(format!(
            "clean provider manifest conflicts with accepted bytes at {path}"
        ))),
        None => provider
            .publish_manifest(batch_id, bytes)
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string())),
    }
}

fn publish_clean_descriptor_exact(
    provider: &mut SharedProviderTransport,
    descriptor: &CleanSharedEnrollmentDescriptorV1,
) -> Result<(), SyncRuntimeRequestError> {
    let bytes = descriptor
        .encode()
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    match provider
        .read_exact(SHARED_ENROLLMENT_DESCRIPTOR_PATH)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
    {
        Some(existing) if existing == bytes => Ok(()),
        Some(_) => Err(SyncRuntimeRequestError::ActorRefused(
            "clean provider descriptor conflicts with the enrolled authority".into(),
        )),
        None => provider
            .publish_descriptor(&bytes)
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string())),
    }
}

fn clean_frontier_head(
    engine: &ShardedHotEngine,
    descriptor: &CleanSharedEnrollmentDescriptorV1,
    device_id: DeviceId,
) -> Result<SharedProviderFrontierHeadV1, SyncRuntimeRequestError> {
    let root = engine
        .accepted_frontier_root()
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    let tips = engine
        .accepted_frontier_tip_batches()
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    SharedProviderFrontierHeadV1::new(
        descriptor.workspace_id(),
        descriptor.lineage_digest(),
        descriptor
            .digest()
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?,
        device_id,
        root.acceptance_sequence(),
        root.state_digest(),
        tips,
        None,
    )
    .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))
}

fn publish_clean_archive_batch(
    store: &ObjectStore,
    provider: &mut SharedProviderTransport,
    workspace_id: WorkspaceId,
    lineage_digest: LineageDigest,
    batch_id: BatchId,
) -> Result<(), SyncRuntimeRequestError> {
    let validated = match store
        .inspect_batch(batch_id)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
    {
        crate::oplog::BatchInspection::Ready(validated) => validated,
        crate::oplog::BatchInspection::Absent => {
            return Err(SyncRuntimeRequestError::ActorRefused(format!(
                "clean outbound batch {batch_id} is absent"
            )));
        }
        crate::oplog::BatchInspection::Staged { missing, .. } => {
            return Err(SyncRuntimeRequestError::ActorRefused(format!(
                "clean outbound batch {batch_id} is missing {} objects",
                missing.len()
            )));
        }
    };
    if validated.manifest().workspace_id() != workspace_id
        || validated.manifest().lineage_digest() != lineage_digest
    {
        return Err(SyncRuntimeRequestError::ActorRefused(format!(
            "clean outbound batch {batch_id} is outside the sharing namespace"
        )));
    }
    for object in validated.manifest().required_objects() {
        let bytes = store
            .read_object_bytes(object.content_digest())
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        publish_provider_object_exact(provider, object.content_digest(), &bytes)?;
    }
    let bytes = store
        .read_manifest_bytes(batch_id)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    publish_clean_manifest_exact(provider, batch_id, &bytes)
}

fn provider_manifest_id(path: &str) -> Option<BatchId> {
    path.strip_prefix("manifests/")
        .and_then(|name| name.strip_suffix(".manifest"))
        .and_then(|value| Uuid::parse_str(value).ok())
        .map(BatchId::from_uuid)
}

fn provider_manifest_recovery_link_id(path: &str) -> Option<BatchId> {
    path.strip_prefix(&format!(
        "{SHARED_PROVIDER_MANIFEST_RECOVERY_LINKS_NAMESPACE}/"
    ))
    .and_then(|name| name.strip_suffix(".link"))
    .and_then(|value| Uuid::parse_str(value).ok())
    .map(BatchId::from_uuid)
}

fn provider_manifest_recovery_blob_digest(path: &str) -> Option<&str> {
    let digest = path
        .strip_prefix(&format!(
            "{SHARED_PROVIDER_MANIFEST_RECOVERY_BLOBS_NAMESPACE}/"
        ))
        .and_then(|name| name.strip_suffix(".manifest"))?;
    (digest.len() == 64
        && digest
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte)))
    .then_some(digest)
}

/// Place `dependency` ahead of the batch that is waiting for it in the direct
/// provider manifest lane.
///
/// The lane only ever advances its front entry, so a batch whose causal
/// dependency is queued BEHIND it deadlocks the pair: the front batch stalls on
/// the dependency every turn while the dependency never reaches the front.
/// Delivered provider bytes produce no further filesystem event, so nothing
/// breaks that tie and a peer's edit is stranded. Membership in `queued` alone
/// therefore does not mean "will be admitted in time" — the position matters,
/// and this moves the dependency to the front either way (restoring the
/// deque/set invariant if they ever disagree).
fn promote_provider_dependency(
    manifests: &mut VecDeque<BatchId>,
    queued: &mut BTreeSet<BatchId>,
    dependency: BatchId,
) {
    queued.insert(dependency);
    if let Some(position) = manifests.iter().position(|batch| *batch == dependency) {
        if position == 0 {
            return;
        }
        manifests.remove(position);
    }
    manifests.push_front(dependency);
}

fn provider_frontier_head_path(path: &str) -> bool {
    let Some(name) = path
        .strip_prefix(SHARED_PROVIDER_FRONTIER_HEADS_NAMESPACE)
        .and_then(|path| path.strip_prefix('/'))
        .and_then(|name| name.strip_suffix(".head"))
    else {
        return false;
    };
    let Some((device, digest)) = name.rsplit_once('-') else {
        return false;
    };
    Uuid::parse_str(device).is_ok()
        && digest.len() == 64
        && digest
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
}

fn provider_publication_intent_path(path: &str) -> bool {
    let Some(name) = path
        .strip_prefix(SHARED_PROVIDER_PUBLICATION_INTENTS_NAMESPACE)
        .and_then(|path| path.strip_prefix('/'))
        .and_then(|name| name.strip_suffix(".intent"))
    else {
        return false;
    };
    let Some((identity, digest)) = name.rsplit_once('-') else {
        return false;
    };
    if identity.len() != 73 || identity.as_bytes().get(36) != Some(&b'-') {
        return false;
    }
    Uuid::parse_str(&identity[..36]).is_ok()
        && Uuid::parse_str(&identity[37..]).is_ok()
        && digest.len() == 64
        && digest
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
}

fn canonical_generated_provider_conflict(path: &str) -> Option<String> {
    let (directory, filename) = path.rsplit_once('/')?;
    let (stem, extension) = filename.rsplit_once('.')?;
    let base = sync_conflict_base(stem)?;
    let canonical = format!("{directory}/{base}.{extension}");
    match (directory, extension) {
        ("objects", "object")
            if base.len() == 64
                && base
                    .bytes()
                    .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte)) =>
        {
            Some(canonical)
        }
        ("manifests", "manifest") if Uuid::parse_str(base).is_ok() => Some(canonical),
        ("enrollment", "json") if canonical == SHARED_ENROLLMENT_DESCRIPTOR_PATH => Some(canonical),
        (SHARED_PROVIDER_FRONTIER_HEADS_NAMESPACE, "head")
            if provider_frontier_head_path(&canonical) =>
        {
            Some(canonical)
        }
        (SHARED_PROVIDER_PUBLICATION_INTENTS_NAMESPACE, "intent")
            if provider_publication_intent_path(&canonical) =>
        {
            Some(canonical)
        }
        (SHARED_PROVIDER_MANIFEST_RECOVERY_LINKS_NAMESPACE, "link")
            if provider_manifest_recovery_link_id(&canonical).is_some() =>
        {
            Some(canonical)
        }
        (SHARED_PROVIDER_MANIFEST_RECOVERY_BLOBS_NAMESPACE, "manifest")
            if provider_manifest_recovery_blob_digest(&canonical).is_some() =>
        {
            Some(canonical)
        }
        _ => None,
    }
}

fn map_ambiguous_evidence(evidence: AmbiguousEvidence) -> SyncAmbiguousEvidence {
    match evidence {
        AmbiguousEvidence::EnrollmentResidue => SyncAmbiguousEvidence::EnrollmentResidue,
        AmbiguousEvidence::EnrollmentNamespace => SyncAmbiguousEvidence::EnrollmentNamespace,
        AmbiguousEvidence::EnrollmentGraphBinding => SyncAmbiguousEvidence::EnrollmentGraphBinding,
        AmbiguousEvidence::ArchiveResidue => SyncAmbiguousEvidence::ArchiveResidue,
        AmbiguousEvidence::ArchiveNamespace => SyncAmbiguousEvidence::ArchiveNamespace,
        AmbiguousEvidence::ArchiveBinding => SyncAmbiguousEvidence::ArchiveBinding,
        AmbiguousEvidence::ActiveArchiveMismatch => SyncAmbiguousEvidence::ActiveArchiveMismatch,
    }
}

fn map_component(component: DiscoveryComponent) -> SyncRuntimeComponent {
    match component {
        DiscoveryComponent::Enrollment => SyncRuntimeComponent::Enrollment,
        DiscoveryComponent::Archive => SyncRuntimeComponent::Archive,
    }
}

