    /// Legacy managed-local generation filenames. Production no longer mints
    /// or rotates these names (stage 2d retired the anchor-tuple family); the
    /// crash-history regressions still read journals that older fixtures left
    /// behind, so the two decoders live here with their only remaining caller.
    fn managed_local_generation_segment_filename(device_id: Uuid, generation: u64) -> String {
        format!(
            "device-{}-generation-{generation:020}.segment",
            device_id.simple()
        )
    }

    fn managed_local_generation_from_name(
        name: &str,
        device_id: Uuid,
        suffix: &str,
    ) -> Option<u64> {
        let prefix = format!("device-{}-generation-", device_id.simple());
        let digits = name.strip_prefix(&prefix)?.strip_suffix(suffix)?;
        if digits.len() != 20 || !digits.bytes().all(|byte| byte.is_ascii_digit()) {
            return None;
        }
        let generation = digits.parse().ok()?;
        (format!("{generation:020}") == digits).then_some(generation)
    }

    fn managed_local_journal_frames(
        request: &SyncRuntimeOpenRequest,
    ) -> Vec<LocalJournalFrame<ManagedLocalJournalPayloadKind>> {
        let workspace_directory = managed_local_workspace_directory(request);
        let names = fs::read_dir(&workspace_directory)
            .unwrap()
            .map(|entry| entry.unwrap().file_name().into_string().unwrap())
            .collect::<Vec<_>>();
        let legacy_segment_names = names
            .iter()
            .filter(|name| name.starts_with("device-") && name.ends_with(".segment"))
            .cloned()
            .collect::<Vec<_>>();
        let v2_segment_names = names
            .iter()
            .filter(|name| name.starts_with("device-") && name.ends_with(".journal-v2"))
            .cloned()
            .collect::<Vec<_>>();
        let device = managed_local_test_device_id(if v2_segment_names.is_empty() {
            &legacy_segment_names
        } else {
            &v2_segment_names
        });
        let snapshot_directory = std::env::temp_dir().join(format!(
            "tine-managed-local-journal-snapshot-{}",
            Uuid::new_v4()
        ));
        fs::create_dir_all(&snapshot_directory).unwrap();
        let directory = Dir::open_ambient_dir(&snapshot_directory, ambient_authority()).unwrap();
        let mut frames = Vec::new();
        if let Some(segment_name) = v2_segment_names.iter().max() {
            let (selector_generation, segment_id) =
                crate::oplog::local_journal_v2_anchor::parse_managed_local_v2_segment_name(
                    segment_name,
                    device,
                )
                .expect("schema-2 segment name is canonical");
            assert!(selector_generation > 0);
            let identities = request
                .clean_identities
                .as_ref()
                .expect("clean test request retains its activation identities");
            let (anchor_generation, anchor_name) = names
                .iter()
                .filter_map(|name| {
                    parse_managed_local_v2_anchor_name(name, device)
                        .map(|generation| (generation, name))
                })
                .max_by_key(|(generation, _)| *generation)
                .expect("schema-2 segment has a selected anchor");
            let anchor = ManagedLocalGenerationAnchorV2::decode(
                &fs::read(workspace_directory.join(anchor_name)).unwrap(),
                anchor_generation,
                identities.workspace_id,
                identities.lineage_digest,
                device,
            )
            .unwrap();
            assert_eq!(anchor.selection().segment_name(), segment_name);
            assert_eq!(anchor.selection().segment_id(), segment_id);
            fs::copy(
                workspace_directory.join(segment_name),
                snapshot_directory.join(segment_name),
            )
            .unwrap();
            let frontier_name = format!(
                "{}{}",
                segment_name,
                tine_storage::formats::LOCAL_JOURNAL_FRONTIER_SUFFIX
            );
            fs::copy(
                workspace_directory.join(&frontier_name),
                snapshot_directory.join(&frontier_name),
            )
            .unwrap();
            let (journal, _) =
                LocalJournalSegmentV2::open_selected(&directory, anchor.selection()).unwrap();
            journal.replay(|frame| frames.push(frame)).unwrap();
            drop(journal);
        } else {
            let generation = names
                .iter()
                .filter_map(|name| managed_local_generation_from_name(name, device, ".anchor"))
                .max();
            let segment_name = generation.map_or_else(
                || format!("device-{}.segment", device.simple()),
                |generation| managed_local_generation_segment_filename(device, generation),
            );
            fs::copy(
                workspace_directory.join(&segment_name),
                snapshot_directory.join(&segment_name),
            )
            .unwrap();
            let directory =
                Dir::open_ambient_dir(&snapshot_directory, ambient_authority()).unwrap();
            let (journal, _) = LocalJournalSegment::open_from_sequence(
                &directory,
                &segment_name,
                device,
                generation.unwrap_or(0),
            )
            .unwrap();
            journal.replay(|frame| frames.push(frame)).unwrap();
            drop(journal);
        }
        drop(directory);
        fs::remove_dir_all(snapshot_directory).unwrap();
        frames
    }

    fn managed_local_workspace_directory(request: &SyncRuntimeOpenRequest) -> PathBuf {
        let namespace = request
            .application_runtime_root
            .join(MANAGED_LOCAL_JOURNAL_NAMESPACE);
        let workspace_directories = fs::read_dir(&namespace)
            .unwrap()
            .map(|entry| entry.unwrap().path())
            .filter(|path| path.is_dir())
            .collect::<Vec<_>>();
        assert_eq!(workspace_directories.len(), 1);
        workspace_directories.into_iter().next().unwrap()
    }

    fn managed_local_file_names(request: &SyncRuntimeOpenRequest) -> Vec<String> {
        let mut names = fs::read_dir(managed_local_workspace_directory(request))
            .unwrap()
            .map(|entry| entry.unwrap().file_name().into_string().unwrap())
            .collect::<Vec<_>>();
        names.sort();
        names
    }

    fn managed_local_test_device_id(segment_names: &[String]) -> Uuid {
        segment_names
            .iter()
            .find_map(|segment_name| {
                segment_name
                    .strip_prefix("device-")
                    .and_then(|name| {
                        name.strip_suffix(".segment")
                            .or_else(|| name.strip_suffix(".journal-v2"))
                    })
                    .and_then(|name| {
                        name.split("-generation-")
                            .next()
                            .and_then(|name| name.split("-selector-").next())
                    })
                    .and_then(|device| Uuid::parse_str(device).ok())
            })
            .expect("managed-local segment has a canonical device UUID")
    }

    fn drain_managed_local(handle: &SyncRuntimeHandle) {
        let mut last_tick = None;
        for _ in 0..4096 {
            if handle.status().unwrap().managed_local_pending == 0 {
                handle.tick().unwrap();
                return;
            }
            last_tick = Some(handle.tick().unwrap());
        }
        panic!(
            "managed-local drain did not settle: status={:?}, last_tick={last_tick:?}",
            handle.status().unwrap()
        );
    }

