    fn activate_and_prepare_shared(fixture: &ActivationFixture) -> SyncSharedEnrollmentDescriptor {
        let active = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        let handle = active.handle.expect("fixture LocalActive");
        drive_initial_feed(&handle);
        handle.prepare_shared().expect("fixture SharedActive")
    }

    #[test]
    fn managed_storage_validation_is_not_unix_uid_coupled() {
        let uid_probe = ["gete", "uid"].concat();
        for (module, source) in [
            ("wire", include_str!("oplog/wire.rs")),
            ("archive identity", include_str!("oplog/identity.rs")),
            ("enrollment", include_str!("oplog/enrollment.rs")),
            ("SQLite projection", include_str!("oplog/sqlite.rs")),
            (
                "projection receipts",
                include_str!("oplog/projection_store.rs"),
            ),
        ] {
            assert!(
                !source.contains(&uid_probe),
                "{module} admission must not depend on the Tine process uid"
            );
        }
    }

    #[test]
    fn android_receipt_bootstrap_does_not_reenter_capability_preflights() {
        let source = include_str!("oplog/projection_store.rs");
        let directory_start = source
            .find("fn ensure_directory_nofollow(")
            .expect("receipt directory helper");
        let read_start = source[directory_start..]
            .find("fn read_optional_regular(")
            .map(|offset| directory_start + offset)
            .expect("receipt read helper");
        let publication_start = source
            .find("fn publish_android_private_immutable(")
            .expect("Android receipt publication helper");
        let publication_end = source[publication_start..]
            .find("\n#[cfg(test)]\nthread_local!")
            .map(|offset| publication_start + offset)
            .expect("end of Android receipt publication helper");

        let directory = &source[directory_start..read_start];
        assert!(directory.contains("libc::mkdirat"));
        assert!(!directory.contains("root.create_dir"));

        let publication = &source[publication_start..publication_end];
        for required in ["libc::openat", "libc::renameat", "libc::unlinkat"] {
            assert!(
                publication.contains(required),
                "Android receipt publication must retain {required}"
            );
        }
        for forbidden in ["dir.open_with", "dir.rename", "dir.remove_file"] {
            assert!(
                !publication.contains(forbidden),
                "Android receipt bootstrap must not re-enter {forbidden}"
            );
        }
    }

    #[test]
    fn cold_shared_descriptor_discovery_uses_the_canonical_supported_regular_file() {
        let fixture = ActivationFixture::nested_unicode("cold-conflict-control", 0xa185);
        let descriptor = activate_and_prepare_shared(&fixture);
        let enrollment = fixture.request.provider_root.join("outbox/enrollment");
        let canonical = enrollment.join("shared-enrollment-v1.json");
        assert_eq!(
            inspect_shared_provider_cold_prefix(&fixture.request.provider_root).unwrap(),
            SyncSharedProviderColdPrefix::ReadyForDescriptorInspection,
            "the complete provider shape must still reach canonical descriptor discovery"
        );
        assert_eq!(
            inspect_shared_enrollment_for_cold_discovery(&fixture.request.provider_root)
                .unwrap()
                .unwrap(),
            descriptor
        );

        fs::write(
            enrollment.join("shared-enrollment-v1.sync-conflict-20260731-120000-ABCDEFG.json"),
            &descriptor.encoded,
        )
        .unwrap();
        fs::write(fixture.request.provider_root.join(".nomedia"), b"").unwrap();
        fs::write(
            fixture
                .request
                .provider_root
                .join("outbox/.syncthing.provider.tmp"),
            b"partial provider artifact",
        )
        .unwrap();
        assert_eq!(
            inspect_shared_provider_cold_prefix(&fixture.request.provider_root).unwrap(),
            SyncSharedProviderColdPrefix::ReadyForDescriptorInspection,
            "non-authoritative provider artifacts must not hide a valid canonical descriptor"
        );
        assert_eq!(
            inspect_shared_enrollment_for_cold_discovery(&fixture.request.provider_root)
                .unwrap()
                .unwrap(),
            descriptor,
            "cold discovery must use the canonical descriptor despite sibling artifacts"
        );
        fs::remove_file(
            enrollment.join("shared-enrollment-v1.sync-conflict-20260731-120000-ABCDEFG.json"),
        )
        .unwrap();

        fs::write(&canonical, b"{").unwrap();
        assert_eq!(
            inspect_shared_enrollment_for_cold_discovery(&fixture.request.provider_root).unwrap(),
            None,
            "a canonical filename may become visible before its final descriptor bytes"
        );
        fs::write(&canonical, &descriptor.encoded).unwrap();

        let mut unsupported: serde_json::Value =
            serde_json::from_slice(&descriptor.encoded).unwrap();
        let object = unsupported.as_object_mut().unwrap();
        let schema = if object.contains_key("schema_version") {
            object.get_mut("schema_version")
        } else {
            object.get_mut("schemaVersion")
        }
        .expect("shared descriptor schema field");
        *schema = serde_json::Value::from(u64::MAX);
        fs::write(&canonical, serde_json::to_vec(&unsupported).unwrap()).unwrap();
        assert_eq!(
            inspect_shared_enrollment_for_cold_discovery(&fixture.request.provider_root).unwrap(),
            None,
            "an incomplete or unsupported descriptor remains retryable while provider delivery settles"
        );
        fs::write(&canonical, &descriptor.encoded).unwrap();

        let extra_link = enrollment.join("descriptor-hard-link");
        fs::hard_link(&canonical, &extra_link).unwrap();
        assert!(
            inspect_shared_enrollment_for_cold_discovery(&fixture.request.provider_root).is_err(),
            "local filesystem validation errors must not be mislabeled as partial provider delivery"
        );
        fs::remove_file(extra_link).unwrap();

        #[cfg(unix)]
        {
            use std::os::unix::fs::symlink;
            let target = fixture.root.join("descriptor-target");
            fs::write(&target, &descriptor.encoded).unwrap();
            fs::remove_file(&canonical).unwrap();
            symlink(&target, &canonical).unwrap();
            assert!(
                inspect_shared_enrollment_for_cold_discovery(&fixture.request.provider_root)
                    .is_err()
            );
        }
    }

    fn settle_shared_provider(handle: &SyncRuntimeHandle) {
        for _ in 0..1_024 {
            let tick = handle.tick().unwrap();
            assert!(
                !matches!(
                    tick,
                    SyncRuntimeTick::RecoveryBlocked(_)
                        | SyncRuntimeTick::Blocked(_)
                        | SyncRuntimeTick::Terminal(_)
                        | SyncRuntimeTick::Failed(_)
                ),
                "shared provider did not settle: {tick:?}"
            );
            if matches!(tick, SyncRuntimeTick::Idle)
                && handle.status().unwrap().provider_pending == 0
            {
                return;
            }
        }
        panic!(
            "shared provider exceeded the bounded test turn budget: {:?}",
            handle.status().unwrap()
        );
    }

