    #[test]
    fn final_projection_then_split_provider_task_chain_heals_intermediate_conflict() {
        let (initiator, receiver, initiator_handle, receiver_handle) =
            joined_shared_pair("final-projection-split-provider-chain", 0xa184_0000);

        let (root, revision) = load_application_exact(&receiver_handle, "Root.md");
        let (root, revision) =
            save_application_block_text(&receiver_handle, root, revision, "TODO field task");
        settle_shared_provider(&receiver_handle);
        copy_provider_tree(
            &receiver.request.provider_root,
            &initiator.request.provider_root,
        );
        initiator_handle.observe_provider().unwrap();
        settle_shared_provider(&initiator_handle);

        let (doing, doing_revision) =
            save_application_block_text(&receiver_handle, root, revision, "DOING field task");
        settle_shared_provider(&receiver_handle);
        let intermediate_provider = receiver.root.join("intermediate-provider");
        copy_provider_tree(&receiver.request.provider_root, &intermediate_provider);

        let (_done, _done_revision) =
            save_application_block_text(&receiver_handle, doing, doing_revision, "DONE field task");
        settle_shared_provider(&receiver_handle);

        fs::copy(
            receiver.graph_root.join("Root.md"),
            initiator.graph_root.join("Root.md"),
        )
        .unwrap();
        initiator_handle
            .observe_watcher(vec![
                SyncWatcherObservation::managed_path("Root.md").unwrap()
            ])
            .unwrap();
        settle_shared_provider(&initiator_handle);

        // Only the intermediate provider frontier is visible during this
        // observation window. A later delivery of the final descendant must
        // heal any provisional conflict outcome rather than retain it forever.
        copy_provider_tree(&intermediate_provider, &initiator.request.provider_root);
        initiator_handle.observe_provider().unwrap();
        settle_shared_provider(&initiator_handle);

        copy_provider_tree(
            &receiver.request.provider_root,
            &initiator.request.provider_root,
        );
        initiator_handle.observe_provider().unwrap();
        settle_shared_provider(&initiator_handle);
        copy_provider_tree(
            &initiator.request.provider_root,
            &receiver.request.provider_root,
        );
        receiver_handle.observe_provider().unwrap();
        settle_shared_provider(&receiver_handle);
        copy_provider_tree(
            &receiver.request.provider_root,
            &initiator.request.provider_root,
        );
        initiator_handle.observe_provider().unwrap();
        settle_shared_provider(&initiator_handle);

        for (label, handle) in [
            ("split-delivery receiver", &initiator_handle),
            ("original author", &receiver_handle),
        ] {
            let (page, _) = load_application_exact(handle, "Root.md");
            assert_eq!(
                page.blocks.len(),
                1,
                "{label} retained a provisional intermediate conflict: {page:?}",
            );
            assert_eq!(page.blocks[0].raw, "DONE field task", "{label}");
        }

        let initiator_projection = fs::read(initiator.graph_root.join("Root.md")).unwrap();
        let receiver_projection = fs::read(receiver.graph_root.join("Root.md")).unwrap();
        assert_eq!(
            initiator_projection, receiver_projection,
            "managed replicas agreed in memory but left different Direct Files projections",
        );
        for fixture in [&initiator, &receiver] {
            assert!(
                relative_files(&fixture.graph_root).iter().all(|path| {
                    !path.contains(".sync-conflict-") && !path.ends_with(".projection-conflict")
                }),
                "managed convergence retained a transport or projection conflict artifact",
            );
        }

        assert!(matches!(
            initiator_handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
        assert!(matches!(
            receiver_handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
        for fixture in [&initiator, &receiver] {
            assert!(
                Graph::open(&fixture.graph_root).conflict_queue().is_empty(),
                "returning the converged projection to Direct Files exposed a Concord conflict",
            );
        }
    }

    fn joined_shared_pair_from_graph_copy(
        label: &str,
        seed: u128,
        source: &Path,
    ) -> (
        ActivationFixture,
        ActivationFixture,
        SyncRuntimeHandle,
        SyncRuntimeHandle,
    ) {
        let initiator =
            ActivationFixture::copied_graph(&format!("{label}-initiator"), seed, source);
        let mut receiver =
            ActivationFixture::copied_graph(&format!("{label}-receiver"), seed, source);
        for graph_root in [&initiator.graph_root, &receiver.graph_root] {
            let managed = graph_root.join(".tine-sync");
            if managed.exists() {
                fs::remove_dir_all(managed).unwrap();
            }
        }
        receiver.request.identities.endpoint_id =
            ProjectionEndpointId::from_uuid(Uuid::from_u128(seed + 0x10));
        receiver.request.identities.device_id = DeviceId::from_uuid(Uuid::from_u128(seed + 0x11));
        receiver.request.identities.session_id = SessionId::from_uuid(Uuid::from_u128(seed + 0x12));

        let descriptor = activate_and_prepare_shared(&initiator);
        copy_provider_tree(
            &initiator.request.provider_root,
            &receiver.request.provider_root,
        );
        let receiver_active = SyncRuntimeHandle::activate_or_resume_local(receiver.request.clone());
        let receiver_joining = receiver_active.handle.expect("receiver LocalActive");
        drive_initial_feed(&receiver_joining);
        receiver_joining
            .join_shared(descriptor)
            .unwrap_or_else(|error| panic!("real-corpus receiver could not join: {error}"));
        drop(receiver_joining);

        let initiator_handle =
            active_handle(SyncRuntimeHandle::open(reopen_request(&initiator.request)));
        let receiver_handle =
            active_handle(SyncRuntimeHandle::open(reopen_request(&receiver.request)));
        settle_shared_provider(&initiator_handle);
        settle_shared_provider(&receiver_handle);
        (initiator, receiver, initiator_handle, receiver_handle)
    }

    /// Rebase every app-private path of an activation request onto an archived
    /// copy of that private root. Adoption archives the private root whole
    /// (`archive_private_root` in the Tauri composition), so the archive is
    /// openable exactly when the same request, rebased, still opens.
    fn rebase_private_root(
        request: &SyncLocalActivationRequest,
        from: &Path,
        to: &Path,
    ) -> SyncLocalActivationRequest {
        let rebase = |path: &Path| -> PathBuf {
            match path.strip_prefix(from) {
                Ok(relative) => to.join(relative),
                Err(_) => path.to_path_buf(),
            }
        };
        SyncLocalActivationRequest {
            graph_root: request.graph_root.clone(),
            archive_root: rebase(&request.archive_root),
            enrollment_root: rebase(&request.enrollment_root),
            receipt_root: rebase(&request.receipt_root),
            database_path: rebase(&request.database_path),
            application_runtime_root: rebase(&request.application_runtime_root),
            capture_root: rebase(&request.capture_root),
            preparation_root: rebase(&request.preparation_root),
            provider_root: request.provider_root.clone(),
            provider_journal_root: rebase(&request.provider_journal_root),
            identities: request.identities.clone(),
        }
    }

    /// The identity swap the adopting device performs after setting its own
    /// managed history aside: the shared graph's three identities, this
    /// device's own device id, and everything run-local minted fresh. It is the
    /// exact shape of `SparseV2ActivationRecord::from_shared` in the Tauri
    /// composition.
    fn adopting_activation_request(
        request: &SyncLocalActivationRequest,
        descriptor: &SyncSharedEnrollmentDescriptor,
        seed: u128,
    ) -> SyncLocalActivationRequest {
        let mut adopted = request.clone();
        adopted.identities.workspace_id = descriptor.workspace_id;
        adopted.identities.lineage_digest = descriptor.lineage_digest;
        adopted.identities.catalog_document_id = descriptor.catalog_document_id;
        adopted.identities.endpoint_id = ProjectionEndpointId::from_uuid(Uuid::from_u128(seed));
        adopted.identities.preparation_id = Uuid::from_u128(seed + 1);
        adopted.identities.session_id = SessionId::from_uuid(Uuid::from_u128(seed + 2));
        adopted
    }

    fn page_contents(handle: &SyncRuntimeHandle) -> BTreeMap<String, Vec<String>> {
        let SyncRuntimeQueryReply::Pages(pages) = handle
            .query(SyncRuntimeQueryRequest::ListPages {
                page_kind: None,
                limit: MAX_MATERIALIZATION_QUERY_ROWS,
            })
            .unwrap()
        else {
            panic!("page list returned the wrong reply variant");
        };
        let mut contents = BTreeMap::new();
        for page in pages {
            let SyncRuntimeQueryReply::PageWithBlocks(Some(loaded)) = handle
                .query(SyncRuntimeQueryRequest::LoadPage {
                    page_id: page.page_id.clone(),
                    block_limit: 64,
                })
                .unwrap()
            else {
                panic!("{} did not load its blocks", page.path);
            };
            contents.insert(
                page.path.clone(),
                loaded
                    .blocks
                    .iter()
                    .map(|block| block.content.clone())
                    .collect(),
            );
        }
        contents
    }

    /// Both devices independently enabled Tine-managed storage on the same
    /// synced folder, so each minted its own `WorkspaceId`. This is the state
    /// the whole adoption packet exists for, and the first assertion is the
    /// verbatim refusal that makes a plain join impossible.
    fn independent_managed_devices(
        label: &str,
        seed: u128,
    ) -> (
        ActivationFixture,
        ActivationFixture,
        SyncSharedEnrollmentDescriptor,
        BTreeMap<String, Vec<u8>>,
    ) {
        let initiator = ActivationFixture::nested_unicode(&format!("{label}-initiator"), seed);
        // A different seed is the whole point: an independent activation mints
        // its own workspace id, lineage digest and catalog document id.
        let adopter =
            ActivationFixture::nested_unicode(&format!("{label}-adopter"), seed + 0x1_0000);
        assert_ne!(
            initiator.request.identities.workspace_id,
            adopter.request.identities.workspace_id
        );

        let initiator_handle =
            SyncRuntimeHandle::activate_or_resume_local(initiator.request.clone())
                .handle
                .expect("sharing device LocalActive");
        drive_initial_feed(&initiator_handle);
        let _ = submit_shared_page(
            &initiator_handle,
            seed + 0x2000,
            "Shared From The Other Device",
            "notes/shared from the other device.md",
            "content the adopting device is joining",
        );
        let shared_graph = user_graph_bytes(&initiator.graph_root);
        let descriptor = initiator_handle
            .prepare_shared()
            .expect("sharing device publishes its descriptor");
        drop(initiator_handle);
        (initiator, adopter, descriptor, shared_graph)
    }

    /// Fail-before evidence, kept verbatim: today a device that enabled
    /// Tine-managed storage on its own cannot join another device's graph at
    /// all, and the refusal is the identity check, not a content check.
    #[test]
    fn an_independently_activated_device_cannot_join_another_devices_managed_graph() {
        let (initiator, adopter, descriptor, _shared_graph) =
            independent_managed_devices("adoption-fail-before", 0xad00_0000);
        copy_provider_tree(
            &initiator.request.provider_root,
            &adopter.request.provider_root,
        );
        let adopter_handle = SyncRuntimeHandle::activate_or_resume_local(adopter.request.clone())
            .handle
            .expect("adopting device LocalActive");
        drive_initial_feed(&adopter_handle);
        let marker_before = read_activation_marker(&adopter.request.enrollment_root)
            .unwrap()
            .unwrap();
        let graph_before = user_graph_bytes(&adopter.graph_root);

        let refusal = adopter_handle.join_shared(descriptor).unwrap_err();

        assert_eq!(
            refusal.to_string(),
            "sync actor refused request: clean shared descriptor names another managed graph"
        );
        assert_eq!(
            read_activation_marker(&adopter.request.enrollment_root)
                .unwrap()
                .unwrap(),
            marker_before,
            "the identity refusal must not touch this device's managed authority"
        );
        assert_eq!(
            user_graph_bytes(&adopter.graph_root),
            graph_before,
            "the identity refusal must not touch a single user byte"
        );
        assert!(matches!(
            adopter_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
    }

    /// A descriptor that shares this device's workspace id but not its lineage
    /// is refused by the same check. Adoption must not treat it as an
    /// independent activation: the Tauri composition classifies it separately
    /// and refuses before it archives anything.
    #[test]
    fn a_partially_matching_lineage_is_refused_by_the_same_identity_check() {
        let (initiator, adopter, descriptor, _shared_graph) =
            independent_managed_devices("adoption-partial-lineage", 0xad04_0000);
        copy_provider_tree(
            &initiator.request.provider_root,
            &adopter.request.provider_root,
        );
        // Only the workspace id agrees. The lineage digest and catalog document
        // id remain this device's own.
        let mut partial = adopter.request.clone();
        partial.identities.workspace_id = descriptor.workspace_id;
        let adopter_handle = SyncRuntimeHandle::activate_or_resume_local(partial.clone())
            .handle
            .expect("partially matching device LocalActive");
        drive_initial_feed(&adopter_handle);
        let graph_before = user_graph_bytes(&adopter.graph_root);

        let refusal = adopter_handle.join_shared(descriptor).unwrap_err();

        assert_eq!(
            refusal.to_string(),
            "sync actor refused request: clean shared descriptor names another managed graph"
        );
        assert_eq!(user_graph_bytes(&adopter.graph_root), graph_before);
        assert!(matches!(
            adopter_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
    }

    /// Adoption, end to end, as the Tauri composition performs it: stop the
    /// adopting device's managed runtime, archive its whole private root, then
    /// re-activate from the shared descriptor's identities and join. The
    /// device's own pre-adoption history stays readable from the archive, and
    /// the shared graph's content is what it serves afterwards.
    #[test]
    fn adoption_archives_this_devices_history_readably_and_then_serves_the_shared_graph() {
        let (initiator, adopter, descriptor, shared_graph) =
            independent_managed_devices("adoption-composition", 0xad01_0000);
        let adopter_private = adopter.root.join("private");

        let adopter_handle = SyncRuntimeHandle::activate_or_resume_local(adopter.request.clone())
            .handle
            .expect("adopting device LocalActive");
        drive_initial_feed(&adopter_handle);
        let _ = submit_shared_page(
            &adopter_handle,
            0xad01_3000,
            "Only On The Adopting Device",
            "notes/only on the adopting device.md",
            "pre-adoption local edit",
        );
        assert!(matches!(
            adopter_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        drop(adopter_handle);

        // Step 1 of the composition: the private managed root moves whole,
        // exactly as `archive_private_root` renames it under the app-data
        // recovery directory. Nothing is copied and nothing is deleted.
        let archive_root = adopter.root.join("managed-history-archive/private-0");
        fs::create_dir_all(archive_root.parent().unwrap()).unwrap();
        fs::rename(&adopter_private, &archive_root).unwrap();
        // The graph-local shared namespace is deliberately NOT archived: it is
        // the other device's evidence, and the second half is about to read it.
        copy_provider_tree(
            &initiator.request.provider_root,
            &adopter.request.provider_root,
        );
        // The user's file-sync tool, not Tine, converges the Markdown/Org tree.
        // Adoption itself never rewrites user files.
        for (relative, _) in user_graph_bytes(&adopter.graph_root) {
            if !shared_graph.contains_key(&relative) {
                fs::remove_file(adopter.graph_root.join(&relative)).unwrap();
            }
        }
        for (relative, bytes) in &shared_graph {
            let destination = adopter.graph_root.join(relative);
            fs::create_dir_all(destination.parent().unwrap()).unwrap();
            fs::write(destination, bytes).unwrap();
        }

        // Step 2: activate from the descriptor's identities and join.
        let adopted_request =
            adopting_activation_request(&adopter.request, &descriptor, 0xad01_4000);
        let adopted_handle = SyncRuntimeHandle::activate_or_resume_local(adopted_request.clone())
            .handle
            .expect("adopting device re-activates from the shared identities");
        drive_initial_feed(&adopted_handle);
        adopted_handle
            .join_shared(descriptor.clone())
            .expect("adoption joins the shared graph once identities agree");
        // A completed join retires its own actor by design, so what the device
        // serves afterwards is the reopened runtime, not the joining one.
        drop(adopted_handle);
        let adopted_handle =
            active_handle(SyncRuntimeHandle::open(reopen_request(&adopted_request)));

        assert_eq!(
            adopted_handle.status().unwrap().shared_role,
            Some(SyncSharedRole::Joiner)
        );
        let served = page_contents(&adopted_handle);
        assert!(
            served.contains_key("notes/shared from the other device.md"),
            "adoption must serve the shared graph's content: {served:?}"
        );
        assert!(
            !served.contains_key("notes/only on the adopting device.md"),
            "adoption is not a merge, so this device's own page must not appear: {served:?}"
        );
        assert_eq!(
            user_graph_bytes(&adopter.graph_root),
            shared_graph,
            "adoption must not rewrite the already-converged user graph"
        );
        assert!(matches!(
            adopted_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        drop(adopted_handle);

        // The safety property: the archived predecessor is not merely present,
        // it opens and still holds this device's own pre-adoption edit.
        let archived_request =
            rebase_private_root(&adopter.request, &adopter_private, &archive_root);
        let archived = active_handle(SyncRuntimeHandle::open(reopen_request(&archived_request)));
        let preserved = page_contents(&archived);
        assert_eq!(
            preserved
                .get("notes/only on the adopting device.md")
                .map(Vec::as_slice),
            Some(["pre-adoption local edit".to_owned()].as_slice()),
            "the archived predecessor must still hold this device's own edit: {preserved:?}"
        );
        assert!(matches!(
            archived.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
    }

    /// The second half of adoption still refuses when this device's files have
    /// not converged on the shared graph's. That refusal lands after the
    /// archive, so the test proves the state it leaves: Markdown untouched,
    /// the predecessor archive still readable, nothing merged.
    #[test]
    fn adoption_stops_on_unconverged_files_and_leaves_the_archive_readable() {
        let (initiator, adopter, descriptor, shared_graph) =
            independent_managed_devices("adoption-unconverged", 0xad02_0000);
        let adopter_private = adopter.root.join("private");

        let adopter_handle = SyncRuntimeHandle::activate_or_resume_local(adopter.request.clone())
            .handle
            .expect("adopting device LocalActive");
        drive_initial_feed(&adopter_handle);
        let _ = submit_shared_page(
            &adopter_handle,
            0xad02_3000,
            "Unconverged Local Page",
            "notes/unconverged local page.md",
            "still only on this device",
        );
        assert!(matches!(
            adopter_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        drop(adopter_handle);

        let archive_root = adopter.root.join("managed-history-archive/private-0");
        fs::create_dir_all(archive_root.parent().unwrap()).unwrap();
        fs::rename(&adopter_private, &archive_root).unwrap();
        copy_provider_tree(
            &initiator.request.provider_root,
            &adopter.request.provider_root,
        );
        // The shared files arrive, but this device's own page is still here.
        for (relative, bytes) in &shared_graph {
            let destination = adopter.graph_root.join(relative);
            fs::create_dir_all(destination.parent().unwrap()).unwrap();
            fs::write(destination, bytes).unwrap();
        }
        let graph_before = user_graph_bytes(&adopter.graph_root);

        let adopted_request =
            adopting_activation_request(&adopter.request, &descriptor, 0xad02_4000);
        let adopted_handle = SyncRuntimeHandle::activate_or_resume_local(adopted_request)
            .handle
            .expect("adopting device re-activates from the shared identities");
        drive_initial_feed(&adopted_handle);

        let refusal = adopted_handle.join_shared(descriptor).unwrap_err();

        assert!(
            refusal
                .to_string()
                .contains("not in the shared provider frontier"),
            "{refusal}"
        );
        assert!(
            refusal.to_string().contains("local-only=1 shared-only=0"),
            "{refusal}"
        );
        assert!(
            refusal.to_string().contains(
                "clean join mismatch detail: local-only path=\"notes/unconverged local page.md\""
            ),
            "{refusal}"
        );
        assert!(!refusal.to_string().contains("still only on this device"));
        assert_eq!(
            user_graph_bytes(&adopter.graph_root),
            graph_before,
            "a refused adoption must not rewrite a single user byte"
        );
        assert!(matches!(
            adopted_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));

        let archived_request =
            rebase_private_root(&adopter.request, &adopter_private, &archive_root);
        let archived = active_handle(SyncRuntimeHandle::open(reopen_request(&archived_request)));
        let preserved = page_contents(&archived);
        assert_eq!(
            preserved
                .get("notes/unconverged local page.md")
                .map(Vec::as_slice),
            Some(["still only on this device".to_owned()].as_slice()),
            "a refused adoption must still leave the predecessor archive readable: {preserved:?}"
        );
        assert!(matches!(
            archived.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
    }

    fn submit_shared_page(
        handle: &SyncRuntimeHandle,
        seed: u128,
        name: &str,
        path: &str,
        content: &str,
    ) -> (BatchId, PageId, BlockId, DocumentId) {
        let page_id = PageId::from_uuid(Uuid::from_u128(seed));
        let block_id = BlockId::from_uuid(Uuid::from_u128(seed + 1));
        let document_id = DocumentId::from_uuid(Uuid::from_u128(seed + 2));
        let batch_id = submit_durable(
            handle,
            vec![
                SemanticOperation::CreatePage {
                    page_id,
                    home_document_id: document_id,
                    name: LogicalPageName::parse(name).unwrap(),
                    path: ManagedPath::parse(path).unwrap(),
                    kind: ManagedTextKind::Page,
                },
                SemanticOperation::CreateBlock {
                    block: BlockLocation {
                        block_id,
                        home_document_id: document_id,
                    },
                    page_id,
                    parent: None,
                    order: "a".into(),
                    content: content.into(),
                },
            ],
        );
        (batch_id, page_id, block_id, document_id)
    }

    fn admit_shared_page(
        handle: &SyncRuntimeHandle,
        fixture: &ActivationFixture,
        path: &str,
        body: &[u8],
    ) -> PageId {
        let file = fixture.graph_root.join(path);
        fs::create_dir_all(file.parent().unwrap()).unwrap();
        fs::write(file, body).unwrap();
        handle
            .observe_watcher(vec![SyncWatcherObservation::managed_path(path).unwrap()])
            .unwrap();
        settle_exact_feed(handle)
            .unwrap_or_else(|state| panic!("shared page {path:?} did not settle: {state:?}"));
        settle_shared_provider(handle);
        match handle
            .query(SyncRuntimeQueryRequest::ListPages {
                page_kind: None,
                limit: MAX_MATERIALIZATION_QUERY_ROWS,
            })
            .unwrap()
        {
            SyncRuntimeQueryReply::Pages(pages) => pages
                .into_iter()
                .find(|page| page.path == path)
                .and_then(|page| parse_page_id(&page.page_id).ok())
                .unwrap_or_else(|| panic!("shared page {path:?} was not materialized")),
            other => panic!("SQLite page list returned the wrong reply: {other:?}"),
        }
    }

    fn publish_shared_batch(
        handle: &SyncRuntimeHandle,
        fixture: &ActivationFixture,
        batch_id: BatchId,
    ) {
        let manifest = fixture
            .request
            .provider_root
            .join(format!("outbox/manifests/{batch_id}.manifest"));
        for _ in 0..256 {
            if manifest.is_file() {
                return;
            }
            let tick = handle.tick().unwrap();
            assert!(
                !matches!(
                    tick,
                    SyncRuntimeTick::RecoveryBlocked(_)
                        | SyncRuntimeTick::Blocked(_)
                        | SyncRuntimeTick::Terminal(_)
                        | SyncRuntimeTick::Failed(_)
                ),
                "shared batch publication failed: {tick:?}"
            );
        }
        panic!("shared batch {batch_id} was not published");
    }

    fn publish_headless_no_op(
        fixture: &ActivationFixture,
        base_batch: BatchId,
        no_op_batch: BatchId,
    ) -> OperationBatch {
        let store = ObjectStore::open(
            &fixture.request.archive_root,
            fixture.request.identities.workspace_id,
        )
        .unwrap();
        let base_manifest =
            OperationBatch::decode(&store.read_manifest_bytes(base_batch).unwrap()).unwrap();
        let semantic_document = base_manifest
            .required_objects()
            .iter()
            .find(|object| object.kind() == crate::oplog::ObjectKind::SemanticEffect)
            .expect("base batch has a semantic object")
            .document_id();
        let empty_effect =
            crate::oplog::SemanticEffect::new(Vec::new(), Vec::new(), Vec::new()).unwrap();
        let empty_effect_bytes = empty_effect.encode().unwrap();
        let empty_effect_object = OperationObject::new(
            base_manifest.workspace_id(),
            semantic_document,
            crate::oplog::ObjectKind::SemanticEffect,
            empty_effect_bytes.clone(),
        )
        .unwrap();
        let manifest = OperationBatch::new_with_causality(
            base_manifest.workspace_id(),
            base_manifest.lineage_digest(),
            no_op_batch,
            base_manifest.author_device_id(),
            base_manifest.author_session_id(),
            base_manifest.origin(),
            crate::oplog::BatchCausalDot::new(
                base_manifest.causal_dot().peer_id(),
                base_manifest.causal_dot().counter().checked_add(1).unwrap(),
            )
            .unwrap(),
            vec![base_batch],
            crate::oplog::FrontierV2::new(Vec::new()).unwrap(),
            crate::oplog::SemanticEffectDigest::of(&empty_effect_bytes),
            vec![empty_effect_object.descriptor().unwrap()],
        )
        .unwrap();
        assert!(
            manifest
                .required_objects()
                .iter()
                .all(|object| object.kind() != crate::oplog::ObjectKind::CrdtUpdate),
            "fixture no-op unexpectedly acquired a document head"
        );
        let mut provider = SharedProviderTransport::open(
            &fixture.request.provider_root,
            &fixture.request.provider_journal_root,
        )
        .unwrap();
        let descriptor = empty_effect_object.descriptor().unwrap();
        provider
            .publish_object(
                descriptor.content_digest(),
                &empty_effect_object.encode().unwrap(),
            )
            .unwrap();
        provider
            .publish_manifest(no_op_batch, &manifest.encode().unwrap())
            .unwrap();
        manifest
    }

    fn provider_object_paths(manifest: &OperationBatch) -> Vec<String> {
        manifest
            .required_objects()
            .iter()
            .map(|object| format!("objects/{}.object", object.content_digest()))
            .collect()
    }

    fn provider_complete_delivery_paths(manifest: &OperationBatch) -> Vec<String> {
        let mut delivered = provider_object_paths(manifest);
        delivered.push(format!("manifests/{}.manifest", manifest.batch_id()));
        delivered
    }

    fn direct_dependency_child_manifest(
        fixture: &ActivationFixture,
        batch_id: BatchId,
        dependency_batch: BatchId,
    ) -> OperationBatch {
        let store = ObjectStore::open(
            &fixture.request.archive_root,
            fixture.request.identities.workspace_id,
        )
        .unwrap();
        let locally_authored =
            OperationBatch::decode(&store.read_manifest_bytes(batch_id).unwrap()).unwrap();
        OperationBatch::new_with_causality(
            locally_authored.workspace_id(),
            locally_authored.lineage_digest(),
            locally_authored.batch_id(),
            locally_authored.author_device_id(),
            locally_authored.author_session_id(),
            locally_authored.origin(),
            locally_authored.causal_dot(),
            vec![dependency_batch],
            locally_authored.dependency_frontier().clone(),
            locally_authored.semantic_effect_digest(),
            locally_authored.required_objects().to_vec(),
        )
        .unwrap()
    }

    fn publish_manifest_to_provider(fixture: &ActivationFixture, manifest: &OperationBatch) {
        let store = ObjectStore::open(
            &fixture.request.archive_root,
            fixture.request.identities.workspace_id,
        )
        .unwrap();
        let mut provider = SharedProviderTransport::open(
            &fixture.request.provider_root,
            &fixture.request.provider_journal_root,
        )
        .unwrap();
        for object in manifest.required_objects() {
            provider
                .publish_object(
                    object.content_digest(),
                    &store.read_object_bytes(object.content_digest()).unwrap(),
                )
                .unwrap();
        }
        provider
            .publish_manifest(manifest.batch_id(), &manifest.encode().unwrap())
            .unwrap();
    }

    fn provider_manifest_recovery_paths(
        fixture: &ActivationFixture,
        batch_id: BatchId,
    ) -> (PathBuf, PathBuf, String, String) {
        let store = ObjectStore::open(
            &fixture.request.archive_root,
            fixture.request.identities.workspace_id,
        )
        .unwrap();
        let manifest_bytes = store.read_manifest_bytes(batch_id).unwrap();
        let link_relative =
            format!("{SHARED_PROVIDER_MANIFEST_RECOVERY_LINKS_NAMESPACE}/{batch_id}.link");
        let blob_relative = format!(
            "{SHARED_PROVIDER_MANIFEST_RECOVERY_BLOBS_NAMESPACE}/{}.manifest",
            ContentDigest::of(&manifest_bytes)
        );
        (
            fixture
                .request
                .provider_root
                .join("outbox")
                .join(&link_relative),
            fixture
                .request
                .provider_root
                .join("outbox")
                .join(&blob_relative),
            link_relative,
            blob_relative,
        )
    }

    fn reset_provider_manifest_readiness_inspections(workspace_id: WorkspaceId) {
        PROVIDER_MANIFEST_READINESS_INSPECTIONS
            .lock()
            .unwrap()
            .insert(workspace_id, 0);
    }

    fn provider_manifest_readiness_inspections(workspace_id: WorkspaceId) -> usize {
        PROVIDER_MANIFEST_READINESS_INSPECTIONS
            .lock()
            .unwrap()
            .get(&workspace_id)
            .copied()
            .unwrap_or_default()
    }

    fn reset_provider_traversal_instrumentation(workspace_id: WorkspaceId) {
        PROVIDER_TRAVERSAL_INSTRUMENTATION
            .lock()
            .unwrap()
            .insert(workspace_id, ProviderTraversalInstrumentation::default());
    }

    fn provider_traversal_instrumentation(
        workspace_id: WorkspaceId,
    ) -> ProviderTraversalInstrumentation {
        PROVIDER_TRAVERSAL_INSTRUMENTATION
            .lock()
            .unwrap()
            .get(&workspace_id)
            .copied()
            .unwrap_or_default()
    }

    fn reset_shared_join_instrumentation(workspace_id: WorkspaceId) {
        SHARED_JOIN_INSTRUMENTATION
            .lock()
            .unwrap()
            .insert(workspace_id, SharedJoinTraversalInstrumentation::default());
    }

    fn shared_join_instrumentation(
        workspace_id: WorkspaceId,
    ) -> SharedJoinTraversalInstrumentation {
        SHARED_JOIN_INSTRUMENTATION
            .lock()
            .unwrap()
            .get(&workspace_id)
            .copied()
            .unwrap_or_default()
    }

    fn archive_contains_payload(fixture: &ActivationFixture, expected: &[u8]) -> bool {
        let store = ObjectStore::open(
            &fixture.request.archive_root,
            fixture.request.identities.workspace_id,
        )
        .unwrap();
        store.committed_manifests().unwrap().iter().any(|manifest| {
            manifest.required_objects().iter().any(|descriptor| {
                let bytes = store
                    .read_object_bytes(descriptor.content_digest())
                    .unwrap();
                let object = OperationObject::decode(&bytes).unwrap();
                object
                    .payload()
                    .windows(expected.len())
                    .any(|window| window == expected)
            })
        })
    }

    fn oversized_provider_paths() -> Vec<String> {
        (0..=MAX_PROVIDER_EXACT_PATHS)
            .map(|index| format!("objects/{index:064x}.object"))
            .collect()
    }

    #[test]
    fn oversized_provider_callback_retains_scan_and_safe_shutdown_drains_it() {
        let (initiator, receiver, initiator_handle, receiver_handle) =
            joined_shared_pair("provider-oversized-callback", 0xb600);
        let (first_batch, ..) = submit_shared_page(
            &initiator_handle,
            0xb620,
            "Oversized Provider First",
            "notes/oversized-provider-first.md",
            "first retained delivery",
        );
        publish_shared_batch(&initiator_handle, &initiator, first_batch);
        settle_shared_provider(&initiator_handle);
        copy_provider_tree(
            &initiator.request.provider_root,
            &receiver.request.provider_root,
        );

        let oversized = oversized_provider_paths();
        assert!(matches!(
            receiver_handle.observe_provider_paths(oversized.clone(), false),
            Err(SyncRuntimeRequestError::RequestTooLarge {
                observations,
                ..
            }) if observations == MAX_PROVIDER_EXACT_PATHS + 1
        ));
        assert!(
            receiver_handle.status().unwrap().provider_pending > 0,
            "the rejected callback must retain one visible rescan obligation"
        );
        settle_shared_provider(&receiver_handle);
        assert!(
            receiver
                .graph_root
                .join("notes/oversized-provider-first.md")
                .is_file(),
            "a later tick did not perform the retained provider scan"
        );

        let (second_batch, ..) = submit_shared_page(
            &initiator_handle,
            0xb630,
            "Oversized Provider Shutdown",
            "notes/oversized-provider-shutdown.md",
            "shutdown-retained delivery",
        );
        publish_shared_batch(&initiator_handle, &initiator, second_batch);
        settle_shared_provider(&initiator_handle);
        copy_provider_tree(
            &initiator.request.provider_root,
            &receiver.request.provider_root,
        );
        assert!(matches!(
            receiver_handle.observe_provider_paths(oversized, false),
            Err(SyncRuntimeRequestError::RequestTooLarge { .. })
        ));
        assert!(matches!(
            receiver_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(snapshot))
                if snapshot.provider_pending == 0 && !snapshot.watcher.pending
        ));
        assert!(
            receiver
                .graph_root
                .join("notes/oversized-provider-shutdown.md")
                .is_file(),
            "Safe was published before rejected provider work converged"
        );
    }

    /// Whether the real Tauri scheduler would schedule one further turn.
    ///
    /// A transcription of `sparse_tick_needs_continuation` in
    /// `src-tauri/src/watcher.rs`: the tick result names the lane this turn
    /// took, and `has_runnable_work` names work the actor still holds. Keep the
    /// two in step; this is the whole scheduling contract the app has.
    fn production_scheduler_continues(tick: &SyncRuntimeTick, runnable: bool) -> bool {
        runnable
            || matches!(
                tick,
                SyncRuntimeTick::LocalMutation(_)
                    | SyncRuntimeTick::ProviderMutation { .. }
                    | SyncRuntimeTick::Recovering
                    | SyncRuntimeTick::RetryFull
                    // Production paces this one by backoff rather than by the
                    // progress cadence, but it does keep retrying it.
                    | SyncRuntimeTick::RecoveryBlocked(_)
            )
    }

    /// Drive an actor exactly as the production scheduler drives it.
    ///
    /// The app is NOT `settle_shared_provider`: it cannot loop on an internal
    /// inventory, and on a quiet graph nothing produces a later filesystem event
    /// to wake it. It gets exactly one bounded turn per scheduled continuation
    /// and must decide from that turn's result plus the actor's own status
    /// whether to schedule another. A drive that stops with work undone is the
    /// app hanging, not a slow test.
    fn drive_like_the_production_scheduler(handle: &SyncRuntimeHandle) -> usize {
        for turn in 1..=1_024 {
            let tick = handle.tick().unwrap();
            assert!(
                !matches!(
                    tick,
                    SyncRuntimeTick::Blocked(_)
                        | SyncRuntimeTick::Terminal(_)
                        | SyncRuntimeTick::Failed(_)
                ),
                "scheduled provider turn failed: {tick:?}"
            );
            let runnable = handle.status().unwrap().has_runnable_work();
            if !production_scheduler_continues(&tick, runnable) {
                return turn;
            }
        }
        panic!(
            "scheduled provider turns exceeded the bounded budget: {:?}",
            handle.status().unwrap()
        );
    }

    /// Provider evidence delivered while the receiving device was stopped.
    ///
    /// This is the exact device-A state of the two-device journey: another
    /// device's edit arrives as bytes inside the graph-local provider tree while
    /// this device is not running, the device reopens, its own startup scan
    /// settles its watcher epochs, and no further filesystem event is ever
    /// produced. Nothing but the actor's own knowledge of the delivered work can
    /// carry it to the page.
    #[test]
    fn provider_arrival_across_a_delivery_cut_becomes_scheduled_work() {
        let (initiator, receiver, initiator_handle, receiver_handle) =
            joined_shared_pair("provider-arrival-delivery-cut", 0xbe00);
        let (batch_id, ..) = submit_shared_page(
            &initiator_handle,
            0xbe20,
            "Provider Arrival Delivery Cut",
            "notes/provider-arrival-delivery-cut.md",
            "peer edit delivered while the receiver was stopped",
        );
        publish_shared_batch(&initiator_handle, &initiator, batch_id);
        settle_shared_provider(&initiator_handle);

        // The receiver is stopped BEFORE delivery, exactly like the journey's
        // forced kill around the external boundary. No inotify edge exists for
        // bytes written while no watcher is installed.
        drop(receiver_handle);
        copy_provider_tree(
            &initiator.request.provider_root,
            &receiver.request.provider_root,
        );

        let reopened = active_handle(SyncRuntimeHandle::open(reopen_request(&receiver.request)));
        // The one scan the production watcher performs on its first turn after
        // installing watches. Everything after this point must come from the
        // actor's own knowledge of retained work.
        reopened.observe_provider().unwrap();
        drive_like_the_production_scheduler(&reopened);

        assert!(
            receiver
                .graph_root
                .join("notes/provider-arrival-delivery-cut.md")
                .is_file(),
            "the peer's delivered edit never became scheduled actor work: {:?}",
            reopened.status().unwrap()
        );
        let settled = reopened.status().unwrap();
        assert!(
            !settled.has_runnable_work(),
            "a drained receiver must name no runnable work: {settled:?}"
        );
    }

    /// Provider arrival while the receiving actor is already running.
    ///
    /// The bytes appear inside the graph-local provider namespace, are announced
    /// once as an imprecise delivery observation, and then nothing else happens
    /// on this device. Each scheduled turn is one bounded unit, so the arrival
    /// only converges if the actor keeps naming the retained work between turns.
    #[test]
    fn provider_arrival_while_active_becomes_scheduled_work() {
        let (initiator, receiver, initiator_handle, receiver_handle) =
            joined_shared_pair("provider-arrival-while-active", 0xbe40);
        let (batch_id, ..) = submit_shared_page(
            &initiator_handle,
            0xbe60,
            "Provider Arrival While Active",
            "notes/provider-arrival-while-active.md",
            "peer edit delivered to a running receiver",
        );
        publish_shared_batch(&initiator_handle, &initiator, batch_id);
        settle_shared_provider(&initiator_handle);
        copy_provider_tree(
            &initiator.request.provider_root,
            &receiver.request.provider_root,
        );
        receiver_handle.observe_provider().unwrap();

        drive_like_the_production_scheduler(&receiver_handle);

        assert!(
            receiver
                .graph_root
                .join("notes/provider-arrival-while-active.md")
                .is_file(),
            "delivery to a running receiver was never scheduled to completion: {:?}",
            receiver_handle.status().unwrap()
        );
        assert!(
            !receiver_handle.status().unwrap().has_runnable_work(),
            "a drained running receiver must return the scheduler to sleep",
        );
    }

    /// One ordinary local external admission on the RECEIVING device, on a page
    /// that has nothing to do with the inbound provider work.
    ///
    /// This is the interleaving that used to swallow an inbound provider
    /// batch's Markdown. The local admission commits its own batch, which
    /// advances the shared page-catalog document, so the delivered intent's
    /// post-frontier stops equalling the page's current frontier even though
    /// the delivered page itself is untouched.
    fn admit_unrelated_local_external_page(
        fixture: &ActivationFixture,
        handle: &SyncRuntimeHandle,
        relative: &str,
        content: &str,
    ) {
        fs::write(fixture.graph_root.join(relative), content.as_bytes()).unwrap();
        handle
            .observe_watcher(vec![SyncWatcherObservation::managed_path(relative).unwrap()])
            .unwrap();
    }

    /// Drive the receiver the way the production scheduler does, then spend a
    /// further bounded budget of turns so "the next turn would have written it"
    /// is excluded rather than assumed.
    fn drive_receiver_past_quiescence(handle: &SyncRuntimeHandle) {
        drive_like_the_production_scheduler(handle);
        for _ in 0..40 {
            let tick = handle.tick().unwrap();
            assert!(
                !matches!(
                    tick,
                    SyncRuntimeTick::Blocked(_)
                        | SyncRuntimeTick::Terminal(_)
                        | SyncRuntimeTick::Failed(_)
                ),
                "a settled receiver produced an unsafe turn: {tick:?}"
            );
        }
    }

    fn receiver_sqlite_has_path(handle: &SyncRuntimeHandle, path: &str) -> bool {
        match handle
            .query(SyncRuntimeQueryRequest::ListPages {
                page_kind: None,
                limit: MAX_MATERIALIZATION_QUERY_ROWS,
            })
            .unwrap()
        {
            SyncRuntimeQueryReply::Pages(pages) => {
                pages.iter().any(|page| page.path.as_str() == path)
            }
            other => panic!("SQLite page list returned the wrong reply: {other:?}"),
        }
    }

    /// Deliver the initiator's outbox to a RUNNING receiver and admit an
    /// unrelated ordinary local external page in the same window, then settle.
    fn deliver_beside_a_local_admission(
        initiator: &ActivationFixture,
        receiver: &ActivationFixture,
        receiver_handle: &SyncRuntimeHandle,
        local_relative: &str,
        local_content: &str,
    ) {
        copy_provider_tree(
            &initiator.request.provider_root,
            &receiver.request.provider_root,
        );
        receiver_handle.observe_provider().unwrap();
        admit_unrelated_local_external_page(
            receiver,
            receiver_handle,
            local_relative,
            local_content,
        );
        drive_receiver_past_quiescence(receiver_handle);
    }

    /// A page created by the peer must reach the receiver's Markdown even when
    /// an ordinary local external admission is in flight on the same device.
    ///
    /// The regression this pins is durable data-VISIBILITY loss, not a
    /// projection lag: the batch was applied to SQLite, the Markdown file was
    /// never written, `clean_shutdown` still reported Safe, and a full reopen
    /// and re-drive never repaired it. Markdown is the interchange truth, so a
    /// peer's edit that never reaches a file is lost to the user, to every
    /// external tool, and to a Direct Files return.
    #[test]
    fn provider_create_projects_markdown_beside_a_concurrent_external_admission() {
        let (initiator, receiver, initiator_handle, receiver_handle) =
            joined_shared_pair("provider-beside-external-create", 0xbf00);
        let path = "notes/provider-beside-external-create.md";
        let (batch_id, ..) = submit_shared_page(
            &initiator_handle,
            0xbf20,
            "Provider Beside External Create",
            path,
            "peer edit delivered beside a local external admission",
        );
        publish_shared_batch(&initiator_handle, &initiator, batch_id);
        settle_shared_provider(&initiator_handle);

        deliver_beside_a_local_admission(
            &initiator,
            &receiver,
            &receiver_handle,
            "notes/local-beside-provider-create.md",
            "- an unrelated local external edit in the same window\n",
        );

        assert!(
            receiver_sqlite_has_path(&receiver_handle, path),
            "the delivered batch was not applied at all, so this fixture no longer pins the defect",
        );
        assert!(
            receiver.graph_root.join(path).is_file(),
            "an applied provider batch never projected its Markdown: {:?}",
            receiver_handle.status().unwrap()
        );
        assert_eq!(
            fs::read(receiver.graph_root.join(path)).unwrap(),
            b"- peer edit delivered beside a local external admission\n",
            "the projected Markdown does not hold the peer's accepted bytes",
        );
        assert!(matches!(
            receiver_handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));

        let reopened = active_handle(SyncRuntimeHandle::open(reopen_request(&receiver.request)));
        drive_receiver_past_quiescence(&reopened);
        assert!(
            receiver.graph_root.join(path).is_file(),
            "the receiver lost the projected page across a clean reopen",
        );
    }

    /// The same interleaving over a peer EDIT of a page the receiver already
    /// projected.
    #[test]
    fn provider_edit_projects_markdown_beside_a_concurrent_external_admission() {
        let (initiator, receiver, initiator_handle, receiver_handle) =
            joined_shared_pair("provider-beside-external-edit", 0xbf40);
        let path = "notes/provider-beside-external-edit.md";
        let (create_batch, _page_id, block_id, document_id) = submit_shared_page(
            &initiator_handle,
            0xbf60,
            "Provider Beside External Edit",
            path,
            "first",
        );
        publish_shared_batch(&initiator_handle, &initiator, create_batch);
        settle_shared_provider(&initiator_handle);
        copy_provider_tree(
            &initiator.request.provider_root,
            &receiver.request.provider_root,
        );
        receiver_handle.observe_provider().unwrap();
        settle_shared_provider(&receiver_handle);
        assert_eq!(
            fs::read(receiver.graph_root.join(path)).unwrap(),
            b"- first\n"
        );

        let edit_batch = submit_durable(
            &initiator_handle,
            vec![SemanticOperation::EditBlockContent {
                block: BlockLocation {
                    block_id,
                    home_document_id: document_id,
                },
                content: "second".into(),
            }],
        );
        publish_shared_batch(&initiator_handle, &initiator, edit_batch);
        settle_shared_provider(&initiator_handle);

        deliver_beside_a_local_admission(
            &initiator,
            &receiver,
            &receiver_handle,
            "notes/local-beside-provider-edit.md",
            "- an unrelated local external edit in the same window\n",
        );

        assert_eq!(
            fs::read(receiver.graph_root.join(path)).unwrap(),
            b"- second\n",
            "an applied provider EDIT never reached Markdown: {:?}",
            receiver_handle.status().unwrap()
        );
        assert!(matches!(
            receiver_handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    /// Breadth: a peer CROSS-PAGE MOVE under the same interleaving must reach
    /// BOTH pages' Markdown — the source loses the subtree, the target gains it.
    #[test]
    fn provider_cross_page_move_projects_both_pages_beside_a_concurrent_external_admission() {
        let (initiator, receiver, initiator_handle, receiver_handle) =
            joined_shared_pair("provider-beside-external-move", 0xc000);
        let source_path = "notes/provider-beside-external-move-source.md";
        let target_path = "notes/provider-beside-external-move-target.md";
        let (source_batch, source_page_id, moved_block, source_document) = submit_shared_page(
            &initiator_handle,
            0xc020,
            "Provider Beside External Move Source",
            source_path,
            "carried across pages",
        );
        publish_shared_batch(&initiator_handle, &initiator, source_batch);
        let (target_batch, target_page_id, ..) = submit_shared_page(
            &initiator_handle,
            0xc040,
            "Provider Beside External Move Target",
            target_path,
            "target anchor",
        );
        publish_shared_batch(&initiator_handle, &initiator, target_batch);
        settle_shared_provider(&initiator_handle);
        copy_provider_tree(
            &initiator.request.provider_root,
            &receiver.request.provider_root,
        );
        receiver_handle.observe_provider().unwrap();
        settle_shared_provider(&receiver_handle);
        assert!(receiver.graph_root.join(source_path).is_file());
        assert!(receiver.graph_root.join(target_path).is_file());

        let move_batch = submit_durable(
            &initiator_handle,
            vec![SemanticOperation::MoveSubtree {
                root: BlockLocation {
                    block_id: moved_block,
                    home_document_id: source_document,
                },
                from_page_id: source_page_id,
                to_page_id: target_page_id,
                parent: None,
                order: "z".into(),
            }],
        );
        publish_shared_batch(&initiator_handle, &initiator, move_batch);
        settle_shared_provider(&initiator_handle);

        deliver_beside_a_local_admission(
            &initiator,
            &receiver,
            &receiver_handle,
            "notes/local-beside-provider-move.md",
            "- an unrelated local external edit in the same window\n",
        );

        let target_bytes = fs::read(receiver.graph_root.join(target_path)).unwrap();
        assert!(
            String::from_utf8_lossy(&target_bytes).contains("carried across pages"),
            "an applied provider CROSS-PAGE MOVE never reached the target Markdown: {:?}",
            receiver_handle.status().unwrap()
        );
        let source_bytes = fs::read(receiver.graph_root.join(source_path)).unwrap();
        assert!(
            !String::from_utf8_lossy(&source_bytes).contains("carried across pages"),
            "an applied provider CROSS-PAGE MOVE left the subtree in the source Markdown: {:?}",
            receiver_handle.status().unwrap()
        );
        assert!(matches!(
            receiver_handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    /// Deliver every provider batch the initiator has published to the receiver
    /// and drive the receiver exactly as the production scheduler would.
    fn deliver_provider_to_receiver(
        initiator: &ActivationFixture,
        receiver: &ActivationFixture,
        receiver_handle: &SyncRuntimeHandle,
    ) {
        copy_provider_tree(
            &initiator.request.provider_root,
            &receiver.request.provider_root,
        );
        receiver_handle.observe_provider().unwrap();
        drive_like_the_production_scheduler(receiver_handle);
    }

    /// A peer's DELETE, delivered to a running receiver with no concurrent local
    /// work of any kind. The user-visible outcome is the only thing asserted:
    /// the Markdown file the peer deleted is gone from this device's graph.
    #[test]
    fn provider_delete_removes_the_receiver_markdown() {
        let (initiator, receiver, initiator_handle, receiver_handle) =
            joined_shared_pair("provider-delete-converges", 0xbf00);
        let path = "notes/provider-delete-converges.md";
        let (create_batch, page_id, block_id, _) = submit_shared_page(
            &initiator_handle,
            0xbf20,
            "Provider Delete Converges",
            path,
            "peer page that will be deleted",
        );
        publish_shared_batch(&initiator_handle, &initiator, create_batch);
        settle_shared_provider(&initiator_handle);
        deliver_provider_to_receiver(&initiator, &receiver, &receiver_handle);
        assert!(
            receiver.graph_root.join(path).is_file(),
            "the peer's page never reached the receiver's graph: {:?}",
            receiver_handle.status().unwrap()
        );

        let delete_batch = submit_durable(
            &initiator_handle,
            vec![
                SemanticOperation::DeleteSubtree {
                    root_block_id: block_id,
                    page_id,
                },
                SemanticOperation::DeletePage { page_id },
            ],
        );
        publish_shared_batch(&initiator_handle, &initiator, delete_batch);
        settle_shared_provider(&initiator_handle);
        assert!(
            !initiator.graph_root.join(path).exists(),
            "the initiator's own deletion did not reach its own graph"
        );

        deliver_provider_to_receiver(&initiator, &receiver, &receiver_handle);

        assert!(
            !receiver.graph_root.join(path).exists(),
            "a delivered peer DELETE never removed the receiver's Markdown: {:?}",
            receiver_handle.status().unwrap()
        );
        assert!(
            matches!(
                receiver_handle.clean_shutdown().unwrap(),
                SyncShutdownOutcome::Safe(_)
            ),
            "a converged receiver must publish a Safe shutdown"
        );
    }

    /// A peer's RENAME (a path release plus a path acquisition) delivered to a
    /// running receiver with no concurrent local work.
    #[test]
    fn provider_rename_moves_the_receiver_markdown() {
        let (initiator, receiver, initiator_handle, receiver_handle) =
            joined_shared_pair("provider-rename-converges", 0xbf40);
        let old_path = "notes/provider-rename-converges.md";
        let new_path = "notes/provider-rename-converges-renamed.md";
        let (create_batch, page_id, _, _) = submit_shared_page(
            &initiator_handle,
            0xbf60,
            "Provider Rename Converges",
            old_path,
            "peer page that will be renamed",
        );
        publish_shared_batch(&initiator_handle, &initiator, create_batch);
        settle_shared_provider(&initiator_handle);
        deliver_provider_to_receiver(&initiator, &receiver, &receiver_handle);
        assert!(
            receiver.graph_root.join(old_path).is_file(),
            "the peer's page never reached the receiver's graph: {:?}",
            receiver_handle.status().unwrap()
        );

        let rename_batch = submit_durable(
            &initiator_handle,
            vec![SemanticOperation::RenamePagesAndRewriteReferrers {
                page_changes: vec![PageRename {
                    page_id,
                    new_name: LogicalPageName::parse("Provider Rename Converges Renamed").unwrap(),
                    new_path: ManagedPath::parse(new_path).unwrap(),
                }],
                block_rewrites: Vec::new(),
                page_preamble_rewrites: Vec::new(),
            }],
        );
        publish_shared_batch(&initiator_handle, &initiator, rename_batch);
        settle_shared_provider(&initiator_handle);
        assert!(!initiator.graph_root.join(old_path).exists());
        assert!(initiator.graph_root.join(new_path).is_file());

        deliver_provider_to_receiver(&initiator, &receiver, &receiver_handle);

        assert!(
            receiver.graph_root.join(new_path).is_file(),
            "a delivered peer RENAME never created the receiver's new Markdown: {:?}",
            receiver_handle.status().unwrap()
        );
        assert_eq!(
            fs::read(receiver.graph_root.join(new_path)).unwrap(),
            b"- peer page that will be renamed\n"
        );
        assert!(
            !receiver.graph_root.join(old_path).exists(),
            "a delivered peer RENAME left the receiver's old Markdown behind: {:?}",
            receiver_handle.status().unwrap()
        );
        assert!(
            matches!(
                receiver_handle.clean_shutdown().unwrap(),
                SyncShutdownOutcome::Safe(_)
            ),
            "a converged receiver must publish a Safe shutdown"
        );
    }

    /// A peer moves a block subtree to another page and then deletes the page it
    /// emptied. The delivered batch carries a `Present` intent for the target and
    /// an `Absent` intent for the source in one manifest, so both halves have to
    /// converge on this device.
    #[test]
    fn provider_cross_page_move_then_delete_converges_on_the_receiver() {
        let (initiator, receiver, initiator_handle, receiver_handle) =
            joined_shared_pair("provider-move-then-delete", 0xbf80);
        let source_path = "notes/provider-move-then-delete-source.md";
        let target_path = "notes/provider-move-then-delete-target.md";
        let (source_batch, source_page_id, block_id, home_document_id) = submit_shared_page(
            &initiator_handle,
            0xbfa0,
            "Provider Move Then Delete Source",
            source_path,
            "carried subtree",
        );
        publish_shared_batch(&initiator_handle, &initiator, source_batch);
        let (target_batch, target_page_id, ..) = submit_shared_page(
            &initiator_handle,
            0xbfc0,
            "Provider Move Then Delete Target",
            target_path,
            "target base",
        );
        publish_shared_batch(&initiator_handle, &initiator, target_batch);
        settle_shared_provider(&initiator_handle);
        deliver_provider_to_receiver(&initiator, &receiver, &receiver_handle);
        assert!(receiver.graph_root.join(source_path).is_file());
        assert!(receiver.graph_root.join(target_path).is_file());

        let move_batch = submit_durable(
            &initiator_handle,
            vec![
                SemanticOperation::MoveSubtree {
                    root: BlockLocation {
                        block_id,
                        home_document_id,
                    },
                    from_page_id: source_page_id,
                    to_page_id: target_page_id,
                    parent: None,
                    order: "z".into(),
                },
                SemanticOperation::DeletePage {
                    page_id: source_page_id,
                },
            ],
        );
        publish_shared_batch(&initiator_handle, &initiator, move_batch);
        settle_shared_provider(&initiator_handle);
        assert!(!initiator.graph_root.join(source_path).exists());

        deliver_provider_to_receiver(&initiator, &receiver, &receiver_handle);

        assert!(
            !receiver.graph_root.join(source_path).exists(),
            "the emptied source page's Markdown survived a delivered delete: {:?}",
            receiver_handle.status().unwrap()
        );
        assert_eq!(
            fs::read(receiver.graph_root.join(target_path)).unwrap(),
            b"- target base\n- carried subtree\n",
            "the delivered cross-page move never reached the target Markdown"
        );
        assert!(matches!(
            receiver_handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    /// A peer's DELETE for a path this device does not hold. Removing nothing is
    /// the convergent answer, and it must be reported as done rather than retried
    /// forever.
    #[test]
    fn provider_delete_of_a_path_absent_from_the_receiver_converges() {
        let (initiator, receiver, initiator_handle, receiver_handle) =
            joined_shared_pair("provider-delete-absent-locally", 0xc000);
        let path = "notes/provider-delete-absent-locally.md";
        let (create_batch, page_id, block_id, _) = submit_shared_page(
            &initiator_handle,
            0xc020,
            "Provider Delete Absent Locally",
            path,
            "peer page removed underneath the receiver",
        );
        publish_shared_batch(&initiator_handle, &initiator, create_batch);
        settle_shared_provider(&initiator_handle);
        deliver_provider_to_receiver(&initiator, &receiver, &receiver_handle);
        assert!(receiver.graph_root.join(path).is_file());

        let delete_batch = submit_durable(
            &initiator_handle,
            vec![
                SemanticOperation::DeleteSubtree {
                    root_block_id: block_id,
                    page_id,
                },
                SemanticOperation::DeletePage { page_id },
            ],
        );
        publish_shared_batch(&initiator_handle, &initiator, delete_batch);
        settle_shared_provider(&initiator_handle);
        copy_provider_tree(
            &initiator.request.provider_root,
            &receiver.request.provider_root,
        );

        // The file is already gone here -- another tool removed it, or a prior
        // attempt completed the removal and crashed before its receipt landed.
        fs::remove_file(receiver.graph_root.join(path)).unwrap();
        receiver_handle
            .observe_watcher(vec![SyncWatcherObservation::managed_path(path).unwrap()])
            .unwrap();
        receiver_handle.observe_provider().unwrap();
        drive_like_the_production_scheduler(&receiver_handle);

        assert!(
            !receiver.graph_root.join(path).exists(),
            "a delivered DELETE re-created a path that was already absent: {:?}",
            receiver_handle.status().unwrap()
        );
        assert!(matches!(
            receiver_handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    /// A peer's DELETE arriving against a receiver-local external edit of the
    /// same page. The edit must be in immutable local history, the deletion must
    /// reach a settled outcome, and the device must never spin.
    #[test]
    fn provider_delete_racing_a_local_edit_of_the_same_page_settles() {
        let (initiator, receiver, initiator_handle, receiver_handle) =
            joined_shared_pair("provider-delete-races-local-edit", 0xc040);
        let path = "notes/provider-delete-races-local-edit.md";
        let (create_batch, page_id, block_id, _) = submit_shared_page(
            &initiator_handle,
            0xc060,
            "Provider Delete Races Local Edit",
            path,
            "shared base",
        );
        publish_shared_batch(&initiator_handle, &initiator, create_batch);
        settle_shared_provider(&initiator_handle);
        deliver_provider_to_receiver(&initiator, &receiver, &receiver_handle);
        assert!(receiver.graph_root.join(path).is_file());

        let delete_batch = submit_durable(
            &initiator_handle,
            vec![
                SemanticOperation::DeleteSubtree {
                    root_block_id: block_id,
                    page_id,
                },
                SemanticOperation::DeletePage { page_id },
            ],
        );
        publish_shared_batch(&initiator_handle, &initiator, delete_batch);
        settle_shared_provider(&initiator_handle);
        copy_provider_tree(
            &initiator.request.provider_root,
            &receiver.request.provider_root,
        );

        let sentinel = "receiver edited this while the peer was deleting it";
        fs::write(
            receiver.graph_root.join(path),
            format!("- {sentinel}\n").as_bytes(),
        )
        .unwrap();
        receiver_handle
            .observe_watcher(vec![SyncWatcherObservation::managed_path(path).unwrap()])
            .unwrap();
        receiver_handle.observe_provider().unwrap();
        drive_like_the_production_scheduler(&receiver_handle);

        assert!(
            archive_root_contains_bytes(&receiver, sentinel.as_bytes()),
            "the racing local edit was destroyed instead of captured in immutable \
             local history: {:?}",
            receiver_handle.status().unwrap()
        );
        // Either side may win the race; a spin is not an outcome. If the edit
        // won, the file keeps exactly the receiver's bytes and nothing else.
        if receiver.graph_root.join(path).exists() {
            assert_eq!(
                fs::read(receiver.graph_root.join(path)).unwrap(),
                format!("- {sentinel}\n").as_bytes(),
                "a retained remote deletion rewrote the receiver's external bytes"
            );
        }
        assert!(
            !receiver_handle.status().unwrap().has_runnable_work(),
            "a settled receiver must name no runnable work: {:?}",
            receiver_handle.status().unwrap()
        );
    }

    /// A peer deletes a page and then gives its exact path to a different page.
    /// The delivered release must never remove the file the new owner owns:
    /// path ownership, not the deleted page's lifecycle, is what authorizes a
    /// removal.
    #[test]
    fn provider_delete_then_reuse_of_the_same_path_keeps_the_new_owner() {
        let (initiator, receiver, initiator_handle, receiver_handle) =
            joined_shared_pair("provider-delete-then-reuse-path", 0xc080);
        let path = "notes/provider-delete-then-reuse-path.md";
        let (create_batch, page_id, block_id, _) = submit_shared_page(
            &initiator_handle,
            0xc0a0,
            "Provider Delete Then Reuse Path",
            path,
            "first owner",
        );
        publish_shared_batch(&initiator_handle, &initiator, create_batch);
        settle_shared_provider(&initiator_handle);
        deliver_provider_to_receiver(&initiator, &receiver, &receiver_handle);
        assert_eq!(
            fs::read(receiver.graph_root.join(path)).unwrap(),
            b"- first owner\n"
        );

        let delete_batch = submit_durable(
            &initiator_handle,
            vec![
                SemanticOperation::DeleteSubtree {
                    root_block_id: block_id,
                    page_id,
                },
                SemanticOperation::DeletePage { page_id },
            ],
        );
        publish_shared_batch(&initiator_handle, &initiator, delete_batch);
        settle_shared_provider(&initiator_handle);
        let (reuse_batch, ..) = submit_shared_page(
            &initiator_handle,
            0xc0c0,
            "Provider Delete Then Reuse Path Second",
            path,
            "second owner",
        );
        publish_shared_batch(&initiator_handle, &initiator, reuse_batch);
        settle_shared_provider(&initiator_handle);
        assert_eq!(
            fs::read(initiator.graph_root.join(path)).unwrap(),
            b"- second owner\n"
        );

        // Both batches arrive together, so the release and the reacquisition of
        // the same exact path are settled in one delivery.
        deliver_provider_to_receiver(&initiator, &receiver, &receiver_handle);

        assert_eq!(
            fs::read(receiver.graph_root.join(path)).unwrap(),
            b"- second owner\n",
            "the delivered release removed or stale-kept the path its new owner \
             owns: {:?}",
            receiver_handle.status().unwrap()
        );
        assert!(matches!(
            receiver_handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    /// Whether the receiver's immutable local history retains these exact bytes.
    ///
    /// Deliberately NOT `archive_contains_payload`, which only walks
    /// `committed_manifests()` -> `required_objects()` and returns false for
    /// bytes that are demonstrably retained on disk. This scans what the device
    /// actually kept.
    fn archive_root_contains_bytes(fixture: &ActivationFixture, expected: &[u8]) -> bool {
        let mut stack = vec![fixture.request.archive_root.clone()];
        while let Some(dir) = stack.pop() {
            let Ok(entries) = fs::read_dir(&dir) else {
                continue;
            };
            for entry in entries.flatten() {
                let path = entry.path();
                if path.is_dir() {
                    stack.push(path);
                } else if fs::read(&path).is_ok_and(|bytes| {
                    bytes
                        .windows(expected.len())
                        .any(|window| window == expected)
                }) {
                    return true;
                }
            }
        }
        false
    }

    /// The direct provider lane only ever advances its front entry, so a batch
    /// whose causal dependency sits BEHIND it in the same queue can never make
    /// progress: it stalls on the dependency every turn while the dependency
    /// never reaches the front, and delivered bytes produce no further
    /// filesystem event to break the tie. Observed as a receiving device that
    /// held a peer's edit forever with the actor reporting runnable work on
    /// every turn. Queue order comes from provider scan order, so the journey
    /// only reproduces it sometimes; this pins the rule itself.
    #[test]
    fn a_dependency_queued_behind_its_dependent_is_promoted_ahead_of_it() {
        let dependent = BatchId::new();
        let dependency = BatchId::new();
        let unrelated = BatchId::new();

        let mut manifests = VecDeque::from(vec![dependent, dependency, unrelated]);
        let mut queued = BTreeSet::from([dependent, dependency, unrelated]);
        promote_provider_dependency(&mut manifests, &mut queued, dependency);
        assert_eq!(
            manifests.front().copied(),
            Some(dependency),
            "a dependency already queued behind its dependent must be promoted ahead of it",
        );
        assert_eq!(
            manifests
                .iter()
                .filter(|batch| **batch == dependency)
                .count(),
            1,
            "promotion must move the dependency, never duplicate it",
        );
        assert_eq!(manifests.len(), 3, "promotion must not drop queued work");

        // A dependency that is not queued at all is still admitted first, and a
        // dependency already at the front stays put.
        let mut manifests = VecDeque::from(vec![dependent]);
        let mut queued = BTreeSet::from([dependent]);
        promote_provider_dependency(&mut manifests, &mut queued, dependency);
        assert_eq!(manifests.front().copied(), Some(dependency));
        assert!(queued.contains(&dependency));
        promote_provider_dependency(&mut manifests, &mut queued, dependency);
        assert_eq!(
            manifests,
            VecDeque::from(vec![dependency, dependent]),
            "re-promoting the front dependency must be a no-op",
        );
    }

    /// Several delivered items must drain to zero under the same one-turn-per-
    /// continuation budget, and ordinary page reads must interleave with that
    /// drain rather than queue behind the whole backlog.
    #[test]
    fn multiple_delivered_provider_items_drain_to_zero_without_starving_reads() {
        let (initiator, receiver, initiator_handle, receiver_handle) =
            joined_shared_pair("provider-arrival-multi-drain", 0xbe80);
        let paths = [
            "notes/provider-arrival-multi-one.md",
            "notes/provider-arrival-multi-two.md",
            "notes/provider-arrival-multi-three.md",
        ];
        for (index, path) in paths.iter().enumerate() {
            let seed = 0xbea0 + (index as u128) * 0x10;
            let (batch_id, ..) = submit_shared_page(
                &initiator_handle,
                seed,
                &format!("Provider Arrival Multi {index}"),
                path,
                "one of several delivered items",
            );
            publish_shared_batch(&initiator_handle, &initiator, batch_id);
        }
        settle_shared_provider(&initiator_handle);

        drop(receiver_handle);
        copy_provider_tree(
            &initiator.request.provider_root,
            &receiver.request.provider_root,
        );
        let reopened = active_handle(SyncRuntimeHandle::open(reopen_request(&receiver.request)));
        reopened.observe_provider().unwrap();

        // Interleave an ordinary application read with every scheduled turn.
        // Each turn is one bounded unit, so a read can never wait for the whole
        // backlog.
        for turn in 1..=1_024 {
            let tick = reopened.tick().unwrap();
            assert!(
                !matches!(
                    tick,
                    SyncRuntimeTick::Blocked(_)
                        | SyncRuntimeTick::Terminal(_)
                        | SyncRuntimeTick::Failed(_)
                ),
                "scheduled provider turn failed: {tick:?}"
            );
            match reopened
                .query(SyncRuntimeQueryRequest::ListPages {
                    page_kind: None,
                    limit: MAX_MATERIALIZATION_QUERY_ROWS,
                })
                .unwrap_or_else(|error| {
                    panic!("an ordinary page read was starved during the provider drain: {error}")
                }) {
                SyncRuntimeQueryReply::Pages(_) => {}
                other => panic!("SQLite page list returned the wrong reply: {other:?}"),
            }
            let runnable = reopened.status().unwrap().has_runnable_work();
            if !production_scheduler_continues(&tick, runnable) {
                break;
            }
            // Three delivered items settle in well under this budget. The bound
            // is deliberately tight: a lane that stalls — for example a batch
            // waiting on a dependency queued behind it — must fail here rather
            // than spin, because in production that state is a peer edit that
            // never arrives.
            assert!(
                turn < 128,
                "the delivered backlog never drained: {:?}",
                reopened.status().unwrap()
            );
        }

        for path in paths {
            assert!(
                receiver.graph_root.join(path).is_file(),
                "delivered item {path} never became scheduled actor work: {:?}",
                reopened.status().unwrap()
            );
        }
        let settled = reopened.status().unwrap();
        assert!(
            !settled.has_runnable_work(),
            "a fully drained receiver must return the scheduler to sleep: {settled:?}"
        );
    }

    /// The anti-hot-loop direction. A shared actor with nothing delivered and
    /// nothing observed must name no runnable work, so the production scheduler
    /// arms no timer and genuinely sleeps.
    #[test]
    fn a_quiet_shared_actor_names_no_runnable_work() {
        let (_initiator, _receiver, initiator_handle, receiver_handle) =
            joined_shared_pair("provider-arrival-quiescent", 0xbec0);
        for handle in [&initiator_handle, &receiver_handle] {
            let status = handle.status().unwrap();
            assert!(
                !status.has_runnable_work(),
                "a settled shared actor must not keep the scheduler awake: {status:?}"
            );
            assert!(matches!(handle.tick().unwrap(), SyncRuntimeTick::Idle));
            assert!(!handle.status().unwrap().has_runnable_work());
        }
    }

    #[test]
    fn imprecise_observation_during_provider_cursor_forces_a_second_scan() {
        let (initiator, receiver, initiator_handle, receiver_handle) =
            joined_shared_pair("provider-rescan-generation", 0xb700);
        let (batch_id, ..) = submit_shared_page(
            &initiator_handle,
            0xb720,
            "Provider Rescan Generation",
            "notes/provider-rescan-generation.md",
            "created behind first cursor",
        );
        publish_shared_batch(&initiator_handle, &initiator, batch_id);
        settle_shared_provider(&initiator_handle);

        receiver_handle.observe_provider().unwrap();
        // Consume only the descriptor. The first small head cursor remains
        // active when the second imprecise callback is linearized.
        let tick = receiver_handle.tick().unwrap();
        assert!(
            !matches!(
                tick,
                SyncRuntimeTick::RecoveryBlocked(_)
                    | SyncRuntimeTick::Blocked(_)
                    | SyncRuntimeTick::Terminal(_)
                    | SyncRuntimeTick::Failed(_)
            ),
            "first provider cursor failed: {tick:?}"
        );
        assert!(receiver_handle.status().unwrap().provider_pending > 0);

        copy_provider_tree(
            &initiator.request.provider_root,
            &receiver.request.provider_root,
        );
        receiver_handle.observe_provider().unwrap();
        settle_shared_provider(&receiver_handle);
        assert!(
            receiver
                .graph_root
                .join("notes/provider-rescan-generation.md")
                .is_file(),
            "the observation linearized during the first cursor was erased at its completion"
        );
    }

    #[derive(Clone, Copy)]
    enum ProviderWatcherDeliveryOrder {
        ProviderThenWatcher,
        WatcherThenProvider,
    }

    fn receiver_external_edit_precedes_remote_delete(
        label: &str,
        seed: u128,
        order: ProviderWatcherDeliveryOrder,
    ) {
        let (initiator, receiver, initiator_handle, receiver_handle) =
            joined_shared_pair(label, seed);
        let path = "notes/receiver-external-before-delete.md";
        let (create_batch, page_id, block_id, _) = submit_shared_page(
            &initiator_handle,
            seed + 0x20,
            "Receiver External Before Delete",
            path,
            "shared base",
        );
        publish_shared_batch(&initiator_handle, &initiator, create_batch);
        settle_shared_provider(&initiator_handle);
        copy_provider_tree(
            &initiator.request.provider_root,
            &receiver.request.provider_root,
        );
        receiver_handle.observe_provider().unwrap();
        settle_shared_provider(&receiver_handle);
        assert_eq!(
            fs::read(receiver.graph_root.join(path)).unwrap(),
            b"- shared base\n"
        );

        let delete_batch = submit_durable(
            &initiator_handle,
            vec![
                SemanticOperation::DeleteSubtree {
                    root_block_id: block_id,
                    page_id,
                },
                SemanticOperation::DeletePage { page_id },
            ],
        );
        publish_shared_batch(&initiator_handle, &initiator, delete_batch);
        settle_shared_provider(&initiator_handle);
        copy_provider_tree(
            &initiator.request.provider_root,
            &receiver.request.provider_root,
        );

        let sentinel = format!("receiver external bytes {seed:x}");
        fs::write(
            receiver.graph_root.join(path),
            format!("- {sentinel}\n").as_bytes(),
        )
        .unwrap();
        let provider_path = format!("manifests/{delete_batch}.manifest");
        match order {
            ProviderWatcherDeliveryOrder::ProviderThenWatcher => {
                receiver_handle
                    .observe_provider_paths(vec![provider_path], false)
                    .unwrap();
                receiver_handle
                    .observe_watcher(vec![SyncWatcherObservation::managed_path(path).unwrap()])
                    .unwrap();
            }
            ProviderWatcherDeliveryOrder::WatcherThenProvider => {
                receiver_handle
                    .observe_watcher(vec![SyncWatcherObservation::managed_path(path).unwrap()])
                    .unwrap();
                receiver_handle
                    .observe_provider_paths(vec![provider_path], false)
                    .unwrap();
            }
        }

        while receiver_handle.status().unwrap().watcher.pending {
            let tick = receiver_handle.tick().unwrap();
            assert!(
                !matches!(
                    tick,
                    SyncRuntimeTick::RecoveryBlocked(_)
                        | SyncRuntimeTick::Blocked(_)
                        | SyncRuntimeTick::Terminal(_)
                ),
                "the observed local watcher epoch did not settle safely: {tick:?}"
            );
        }
        assert!(
            archive_contains_payload(&receiver, sentinel.as_bytes()),
            "the receiver's external bytes were not captured in immutable local history"
        );
        for _ in 0..256 {
            let tick = receiver_handle.tick().unwrap();
            match tick {
                SyncRuntimeTick::RecoveryBlocked(_) => break,
                SyncRuntimeTick::Idle
                    if receiver_handle.status().unwrap().provider_pending == 0 =>
                {
                    break;
                }
                SyncRuntimeTick::Recovering
                | SyncRuntimeTick::Idle
                | SyncRuntimeTick::AdmittedNoop { .. }
                | SyncRuntimeTick::AdmittedComplete { .. }
                | SyncRuntimeTick::RetryFull => {}
                other => panic!("remote deletion reached an unsafe outcome: {other:?}"),
            }
        }
        assert!(
            archive_contains_payload(&receiver, sentinel.as_bytes()),
            "remote deletion discarded the already-captured receiver bytes"
        );
        if receiver.graph_root.join(path).is_file() {
            assert_eq!(
                fs::read(receiver.graph_root.join(path)).unwrap(),
                format!("- {sentinel}\n").as_bytes(),
                "a blocked remote deletion rewrote the receiver's external bytes"
            );
        }
    }

    #[test]
    fn observed_receiver_external_edit_precedes_remote_delete_in_both_callback_orders() {
        receiver_external_edit_precedes_remote_delete(
            "provider-first-before-watcher",
            0xb800,
            ProviderWatcherDeliveryOrder::ProviderThenWatcher,
        );
        receiver_external_edit_precedes_remote_delete(
            "watcher-first-before-provider",
            0xb900,
            ProviderWatcherDeliveryOrder::WatcherThenProvider,
        );
    }

    #[test]
    fn safe_reopen_repairs_a_completely_lost_provider_namespace() {
        let fixture = make_shared_fixture("provider-safe-namespace-repair", 0xba00);
        let _descriptor = activate_and_prepare_shared(&fixture);
        let handle = active_handle(SyncRuntimeHandle::open(reopen_request(&fixture.request)));
        settle_shared_provider(&handle);
        let (batch_id, ..) = submit_shared_page(
            &handle,
            0xba20,
            "Safe Namespace Repair",
            "notes/safe-namespace-repair.md",
            "accepted before provider loss",
        );
        publish_shared_batch(&handle, &fixture, batch_id);
        assert!(matches!(
            handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        let manifest_names = fs::read_dir(fixture.request.provider_root.join("outbox/manifests"))
            .unwrap()
            .map(|entry| entry.unwrap().file_name())
            .collect::<Vec<_>>();
        assert!(!manifest_names.is_empty());

        crate::test_support::remove_dir_all(&fixture.request.provider_root);
        let repaired = active_handle(SyncRuntimeHandle::open(reopen_request(&fixture.request)));
        settle_shared_provider(&repaired);
        assert!(
            inspect_shared_enrollment(&fixture.request.provider_root)
                .unwrap()
                .is_some(),
            "safe reopen did not restore the private descriptor"
        );
        for name in manifest_names {
            assert!(
                fixture
                    .request
                    .provider_root
                    .join("outbox/manifests")
                    .join(name)
                    .is_file(),
                "safe reopen did not republish an accepted manifest"
            );
        }
        assert_eq!(
            fs::read_dir(
                fixture
                    .request
                    .provider_root
                    .join("outbox")
                    .join(SHARED_PROVIDER_FRONTIER_HEADS_NAMESPACE)
            )
            .unwrap()
            .count(),
            1,
            "namespace loss repair did not publish a current own-device head"
        );
        assert!(matches!(
            repaired.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
    }

    #[test]
    fn complete_namespace_loss_repair_above_head_scan_cap_is_chunked() {
        const TEST_HEAD_SCAN_LIMIT: usize = 8;
        const HISTORICAL_BATCHES: usize = TEST_HEAD_SCAN_LIMIT + 4;

        let fixture = make_shared_fixture("provider-namespace-repair-above-cap", 0xea00);
        let _descriptor = activate_and_prepare_shared(&fixture);
        let handle = active_handle(SyncRuntimeHandle::open(reopen_request(&fixture.request)));
        settle_shared_provider(&handle);
        for index in 0..HISTORICAL_BATCHES {
            submit_shared_page(
                &handle,
                0xea20 + (index as u128) * 4,
                &format!("Namespace Repair History {index}"),
                &format!("notes/namespace-repair-history-{index}.md"),
                "cheap lower-cap repair fixture",
            );
        }
        settle_shared_provider(&handle);
        assert!(matches!(
            handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        let manifest_count_before =
            fs::read_dir(fixture.request.provider_root.join("outbox/manifests"))
                .unwrap()
                .count();
        assert!(
            manifest_count_before > TEST_HEAD_SCAN_LIMIT,
            "fixture did not exceed its isolated head-scan cap"
        );

        crate::test_support::remove_dir_all(&fixture.request.provider_root);
        PROVIDER_HEAD_SCAN_LIMIT_OVERRIDES.lock().unwrap().insert(
            fixture.request.identities.workspace_id,
            TEST_HEAD_SCAN_LIMIT,
        );
        reset_provider_traversal_instrumentation(fixture.request.identities.workspace_id);
        let repaired = active_handle(SyncRuntimeHandle::open(reopen_request(&fixture.request)));

        for _ in 0..64 {
            let tick = repaired.tick().unwrap();
            assert!(
                !matches!(
                    tick,
                    SyncRuntimeTick::RecoveryBlocked(_)
                        | SyncRuntimeTick::Blocked(_)
                        | SyncRuntimeTick::Terminal(_)
                        | SyncRuntimeTick::Failed(_)
                ),
                "descriptor repair failed: {tick:?}"
            );
            if fixture
                .request
                .provider_root
                .join("outbox")
                .join(SHARED_ENROLLMENT_DESCRIPTOR_PATH)
                .is_file()
            {
                break;
            }
        }
        assert_eq!(
            fs::read_dir(
                fixture
                    .request
                    .provider_root
                    .join("outbox")
                    .join(SHARED_PROVIDER_FRONTIER_HEADS_NAMESPACE)
            )
            .unwrap()
            .count(),
            0,
            "descriptor repair unexpectedly published a head in the same tick"
        );
        fail_once_at_provider_recovery_publication_cut(
            fixture.request.identities.workspace_id,
            ProviderRecoveryPublicationTestCut::AfterRecoveryBeforeCanonical,
        );
        let mut mirror_before_canonical = false;
        for _ in 0..64 {
            let tick = repaired.tick().unwrap();
            assert_eq!(
                fs::read_dir(
                    fixture
                        .request
                        .provider_root
                        .join("outbox")
                        .join(SHARED_PROVIDER_FRONTIER_HEADS_NAMESPACE)
                )
                .unwrap()
                .count(),
                0,
                "namespace repair published a head before canonical/object repair settled"
            );
            if matches!(
                tick,
                SyncRuntimeTick::RecoveryBlocked(ref detail)
                    if detail.contains("after_recovery_before_canonical")
            ) {
                mirror_before_canonical = true;
                break;
            }
            assert!(
                !matches!(
                    tick,
                    SyncRuntimeTick::Blocked(_)
                        | SyncRuntimeTick::Terminal(_)
                        | SyncRuntimeTick::Failed(_)
                ),
                "namespace repair failed before its recovery/canonical cut: {tick:?}"
            );
        }
        assert!(
            mirror_before_canonical,
            "namespace repair did not expose the mirror-before-canonical crash cut"
        );
        assert!(
            fs::read_dir(
                fixture
                    .request
                    .provider_root
                    .join("outbox")
                    .join(SHARED_PROVIDER_MANIFEST_RECOVERY_LINKS_NAMESPACE)
            )
            .unwrap()
            .count()
                > 0,
            "namespace repair cut did not durably publish recovery evidence"
        );
        assert_eq!(
            fs::read_dir(
                fixture
                    .request
                    .provider_root
                    .join("outbox")
                    .join(SHARED_PROVIDER_FRONTIER_HEADS_NAMESPACE)
            )
            .unwrap()
            .count(),
            0,
            "namespace repair published a head between mirror backfill and canonical repair"
        );
        fail_once_at_provider_recovery_publication_cut(
            fixture.request.identities.workspace_id,
            ProviderRecoveryPublicationTestCut::AfterRecoveryBeforeCanonical,
        );
        assert!(
            repaired.clean_shutdown().is_err(),
            "namespace repair reached Safe while canonical/object publication was pending"
        );
        drop(repaired);
        let repaired = active_handle(SyncRuntimeHandle::open(reopen_request(&fixture.request)));

        let intents = fixture
            .request
            .provider_root
            .join("outbox")
            .join(SHARED_PROVIDER_PUBLICATION_INTENTS_NAMESPACE);
        let mut max_visible_intents = 0;
        let mut settled = false;
        for _ in 0..4_096 {
            let tick = repaired.tick().unwrap();
            assert!(
                !matches!(
                    tick,
                    SyncRuntimeTick::RecoveryBlocked(_)
                        | SyncRuntimeTick::Blocked(_)
                        | SyncRuntimeTick::Terminal(_)
                        | SyncRuntimeTick::Failed(_)
                ),
                "bounded namespace repair failed: {tick:?}"
            );
            max_visible_intents = max_visible_intents.max(fs::read_dir(&intents).unwrap().count());
            if matches!(tick, SyncRuntimeTick::Idle)
                && repaired.status().unwrap().provider_pending == 0
            {
                settled = true;
                break;
            }
        }
        PROVIDER_HEAD_SCAN_LIMIT_OVERRIDES
            .lock()
            .unwrap()
            .remove(&fixture.request.identities.workspace_id);

        assert!(settled, "bounded namespace repair did not settle");
        assert!(
            max_visible_intents <= 1,
            "repair accumulated {max_visible_intents} intents instead of retiring each chunk"
        );
        assert_eq!(fs::read_dir(&intents).unwrap().count(), 0);
        assert_eq!(
            fs::read_dir(fixture.request.provider_root.join("outbox/manifests"),)
                .unwrap()
                .count(),
            manifest_count_before
        );
        let traversal = provider_traversal_instrumentation(fixture.request.identities.workspace_id);
        assert!(
            traversal.full_scan_entries >= 2 && traversal.head_entries <= TEST_HEAD_SCAN_LIMIT,
            "the crash-reopen fallback was not resumable and bounded: {traversal:?}"
        );
        assert!(matches!(
            repaired.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(ref snapshot)) if snapshot.provider_pending == 0
        ));
    }

