    fn recursive_file_bytes(root: &Path) -> BTreeMap<String, Vec<u8>> {
        let mut files = BTreeMap::new();
        if !root.is_dir() {
            return files;
        }
        let mut pending = vec![root.to_path_buf()];
        while let Some(directory) = pending.pop() {
            let mut entries = fs::read_dir(directory)
                .unwrap()
                .map(Result::unwrap)
                .collect::<Vec<_>>();
            entries.sort_by_key(std::fs::DirEntry::file_name);
            for entry in entries {
                if entry.file_type().unwrap().is_dir() {
                    pending.push(entry.path());
                } else {
                    let relative = entry
                        .path()
                        .strip_prefix(root)
                        .unwrap()
                        .to_string_lossy()
                        .replace('\\', "/");
                    files.insert(relative, fs::read(entry.path()).unwrap());
                }
            }
        }
        files
    }

    fn immutable_archive_bytes(archive_root: &Path) -> BTreeMap<String, Vec<u8>> {
        recursive_file_bytes(archive_root)
            .into_iter()
            .filter(|(path, _)| {
                ["objects/", "batches/", "bootstrap-v1/"]
                    .iter()
                    .any(|prefix| path.starts_with(prefix))
            })
            .collect()
    }

    #[derive(Debug)]
    struct ActivationScaleReceipt {
        source_files: usize,
        source_bytes: usize,
        blocks: usize,
        total_ms: u128,
        phase_ms: Vec<(SyncLocalActivationPhase, u128)>,
        clean: CleanActivationInstrumentation,
        clean_marker_present: bool,
        retired_artifacts: Vec<String>,
        operation_batches: usize,
    }

    fn activation_source_counts(root: &Path) -> (usize, usize, usize) {
        let sources = user_graph_bytes(root);
        sources
            .iter()
            .filter(|(path, _)| {
                matches!(
                    Path::new(path.as_str())
                        .extension()
                        .and_then(|value| value.to_str()),
                    Some("md" | "markdown" | "org")
                )
            })
            .map(|(_, source)| source)
            .fold(
                (0_usize, 0_usize, 0_usize),
                |(files, bytes, blocks), source| {
                    (
                        files + 1,
                        bytes + source.len(),
                        blocks
                            + source
                                .split(|byte| *byte == b'\n')
                                .filter(|line| {
                                    line.starts_with(b"- ")
                                        || line.starts_with(b"* ")
                                        || line.starts_with(b"** ")
                                })
                                .count(),
                    )
                },
            )
    }

    fn activate_with_scale_receipt(fixture: &ActivationFixture) -> ActivationScaleReceipt {
        let (source_files, source_bytes, blocks) = activation_source_counts(&fixture.graph_root);
        let before = user_graph_bytes(&fixture.graph_root);
        let started = std::time::Instant::now();
        let mut transitions = Vec::new();
        let activated = SyncRuntimeHandle::activate_or_resume_local_with_progress(
            fixture.request.clone(),
            |phase| {
                let elapsed = started.elapsed();
                if std::env::var_os("TINE_ACTIVATION_TRACE").is_some() {
                    eprintln!("activation phase {:?} at {} ms", phase, elapsed.as_millis());
                }
                transitions.push((phase, elapsed));
            },
        );
        let total = started.elapsed();
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        assert_eq!(user_graph_bytes(&fixture.graph_root), before);
        let expected = [
            SyncLocalActivationPhase::PrivateSetup,
            SyncLocalActivationPhase::SourceCapture,
            SyncLocalActivationPhase::BootstrapImportPreparation,
            SyncLocalActivationPhase::ImmutablePublicationInstall,
            SyncLocalActivationPhase::SqliteOpenBuild,
            SyncLocalActivationPhase::ReconciliationBaselineActorOpen,
        ];
        assert_eq!(
            transitions
                .iter()
                .map(|(phase, _)| *phase)
                .collect::<Vec<_>>(),
            expected
        );
        let phase_ms = transitions
            .iter()
            .enumerate()
            .map(|(index, (phase, at))| {
                let end = transitions
                    .get(index + 1)
                    .map(|(_, next)| *next)
                    .unwrap_or(total);
                (*phase, end.saturating_sub(*at).as_millis())
            })
            .collect();
        drop(activated.handle);
        let clean = take_clean_activation_instrumentation();
        let clean_marker_present = fixture
            .request
            .enrollment_root
            .join(crate::oplog::lazy_genesis::LAZY_GENESIS_ACTIVATION_MARKER_FILE)
            .is_file();
        let mut retired_artifacts = [
            "bootstrap-v1",
            "engine-history",
            "projection-work-index-v1",
            "reference-catalog-v2",
            "managed-local-journal-v1",
            "inactive-bootstrap-publication-v1",
        ]
        .iter()
        .filter(|name| fixture.request.archive_root.join(name).exists())
        .map(|name| format!("archive/{name}"))
        .collect::<Vec<_>>();
        for (label, root) in [
            ("capture scratch", &fixture.request.capture_root),
            ("preparation scratch", &fixture.request.preparation_root),
        ] {
            if !recursive_file_bytes(root).is_empty() {
                retired_artifacts.push(label.to_owned());
            }
        }
        let operation_batches = fs::read_dir(
            clean_operation_archive_directory(&fixture.request.archive_root).join("batches"),
        )
        .map(|entries| entries.filter_map(Result::ok).count())
        .unwrap_or(0);
        ActivationScaleReceipt {
            source_files,
            source_bytes,
            blocks,
            total_ms: total.as_millis(),
            phase_ms,
            clean,
            clean_marker_present,
            retired_artifacts,
            operation_batches,
        }
    }

    fn assert_activation_near_linear(
        small: &ActivationScaleReceipt,
        large: &ActivationScaleReceipt,
    ) {
        // Permit at most 1.5x normalized wall time plus a one-second fixed-cost
        // allowance. A quadratic implementation at the retained ~2x input
        // scales fails this discriminator, while fsync and scheduler noise do
        // not turn an otherwise linear debug-build receipt flaky.
        let observed = 2_u128
            .saturating_mul(large.total_ms)
            .saturating_mul(small.source_bytes as u128);
        let ceiling = 3_u128
            .saturating_mul(small.total_ms.saturating_add(1_000))
            .saturating_mul(large.source_bytes as u128);
        assert!(
            observed <= ceiling,
            "scaled activation exceeded the near-linear normalized ceiling: small={small:?}, large={large:?}"
        );
    }

    #[test]
    fn detailed_activation_progress_reports_preparation_parts_and_summary_observationally() {
        let fixture = ActivationFixture::nested_unicode("detailed-progress", 0xa08f);
        let before = user_graph_bytes(&fixture.graph_root);
        let mut updates = Vec::new();
        let activated = SyncRuntimeHandle::activate_or_resume_local_with_detailed_progress(
            fixture.request.clone(),
            |update| updates.push(update),
        );
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        assert_eq!(user_graph_bytes(&fixture.graph_root), before);

        let phases = updates
            .iter()
            .filter_map(|update| match update {
                SyncLocalActivationProgress::Phase { phase } => Some(*phase),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            phases,
            vec![
                SyncLocalActivationPhase::PrivateSetup,
                SyncLocalActivationPhase::SourceCapture,
                SyncLocalActivationPhase::BootstrapImportPreparation,
                SyncLocalActivationPhase::ImmutablePublicationInstall,
                SyncLocalActivationPhase::SqliteOpenBuild,
                SyncLocalActivationPhase::ReconciliationBaselineActorOpen,
            ]
        );
        assert!(
            !updates.iter().any(|update| matches!(
                update,
                SyncLocalActivationProgress::BootstrapPreparationSubphase { .. }
                    | SyncLocalActivationProgress::BootstrapDetachedAuthoring { .. }
                    | SyncLocalActivationProgress::BootstrapPreparationSummary { .. }
            )),
            "clean activation must not report the retired operation-spool, partition, detached-authoring, or sealing pipeline"
        );
        drop(activated.handle);
    }

    #[test]
    fn retained_clean_reactivation_reports_each_recovery_boundary() {
        let fixture = ActivationFixture::nested_unicode("retained-reactivation-progress", 0xa091);
        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        let handle = activated.handle.expect("fresh activation opens its actor");
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
        drop(handle);

        let mut updates = Vec::new();
        let reopened = SyncRuntimeHandle::activate_or_resume_local_with_detailed_progress(
            fixture.request.clone(),
            |update| updates.push(update),
        );
        assert_eq!(reopened.status, SyncLocalActivationStatus::Active);
        let phases = updates
            .iter()
            .filter_map(|update| match update {
                SyncLocalActivationProgress::Phase { phase } => Some(*phase),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            phases,
            vec![
                SyncLocalActivationPhase::RetainedRuntimeOpen,
                SyncLocalActivationPhase::RetainedRuntimeTailReplay,
                SyncLocalActivationPhase::RetainedRuntimeProjectionRepair,
                SyncLocalActivationPhase::RetainedRuntimeActorOpen,
            ]
        );
        let handle = reopened
            .handle
            .expect("retained activation opens its actor");
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    #[test]
    fn activation_progress_is_ordered_exact_byte_and_structurally_near_linear() {
        let small = ActivationFixture::scaled("scale-small", 0xa090, 4);
        let large = ActivationFixture::scaled("scale-large", 0xa0a0, 8);
        let small_receipt = activate_with_scale_receipt(&small);
        let large_receipt = activate_with_scale_receipt(&large);
        eprintln!("activation scale small: {small_receipt:?}");
        eprintln!("activation scale large: {large_receipt:?}");
        assert_eq!(large_receipt.source_files, small_receipt.source_files + 4);
        assert!(large_receipt.source_bytes > small_receipt.source_bytes);
        assert!(large_receipt.blocks > small_receipt.blocks);
        assert_eq!(small_receipt.phase_ms.len(), 6);
        assert_eq!(large_receipt.phase_ms.len(), 6);
        for receipt in [&small_receipt, &large_receipt] {
            assert_eq!(
                receipt.clean.source_files, receipt.source_files as u64,
                "the clean builder must consume one activation record per source page"
            );
            assert_eq!(
                receipt.clean.source_bytes,
                (receipt.source_bytes as u64).saturating_mul(2),
                "the clean builder must account for the initial capture plus one sealed-source lowering read"
            );
            assert!(
                receipt.clean.parser_nodes >= receipt.blocks as u64,
                "the parser-owned activation record must cover every outline block"
            );
            assert!(
                receipt.clean.activation_record_bytes > 0,
                "the clean builder must retain a bounded parser-owned record stream"
            );
            assert!(
                !receipt.clean.activation_records_spilled,
                "the small structural fixture must remain on the bounded in-memory record path"
            );
            assert!(
                receipt.clean_marker_present,
                "clean activation must publish its sole authority marker last"
            );
            assert!(
                receipt.retired_artifacts.is_empty(),
                "clean activation retained retired bootstrap, Patricia, journal, shadow, backup, or capture artifacts: {:?}",
                receipt.retired_artifacts
            );
            assert_eq!(
                receipt.operation_batches, 0,
                "operation-free genesis must not fabricate an edit batch per imported page"
            );
        }
        assert_activation_near_linear(&small_receipt, &large_receipt);
    }

    #[test]
    #[ignore = "manual audit probe (2026-08-26): primitive count tables for the five audited operations"]
    fn ms_cost_audit_five_operation_probe() {
        assert!(
            !cfg!(debug_assertions),
            "release-only; run cargo test -p tine-core --release --lib ms_cost_audit_five_operation_probe -- --ignored --nocapture"
        );
        let source = real_graph_copy_source_from_env("TINE_MS_AUDIT_GRAPH_COPY");
        let fixture = ActivationFixture::copied_graph("ms-cost-audit", 0xa0f9, &source);

        fn report(label: &str, before: &crate::perf_count::Snapshot) -> crate::perf_count::Snapshot {
            let now = crate::perf_count::snapshot();
            eprintln!("{}", now.report_since(before, label));
            eprint!("{}", tine_storage::audit_counters::drain_attribution());
            crate::perf_count::snapshot()
        }

        let pc = crate::perf_count::snapshot();
        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        let handle = activated.handle.expect("audit probe activates");
        let pc = report("enable-ms:activate", &pc);
        drive_initial_feed_with_turn_budget(&handle, 4096);
        let pc = report("enable-ms:initial-feed", &pc);

        let pages = match handle.application_page_inventory().unwrap() {
            SyncApplicationPageInventoryOutcome::Loaded { pages } => pages,
            other => panic!("audit probe inventory did not load: {other:?}"),
        };
        let mut journals: Vec<String> = pages
            .iter()
            .map(|entry| entry.rel_path.clone())
            .filter(|path| path.starts_with("journals/"))
            .collect();
        journals.sort();
        let mut day1 = None;
        let mut day2 = None;
        for path in &journals {
            let (page, _) = load_application_exact(&handle, path);
            if page.blocks.is_empty() {
                continue;
            }
            if day1.is_none() {
                day1 = Some(path.clone());
            } else {
                day2 = Some(path.clone());
                break;
            }
        }
        let day1 = day1.expect("audit corpus has a nonempty journal day");
        let day2 = day2.expect("audit corpus has a second nonempty journal day");
        eprintln!("ms-audit selected day1={day1} day2={day2}");
        let pc = report("selection(untimed)", &pc);

        // (b) open page — cold-ish, second page, warm repeat.
        let _ = load_application_exact(&handle, &day1);
        let pc = report("open-page:day1", &pc);
        let _ = load_application_exact(&handle, &day2);
        let pc = report("open-page:day2", &pc);
        let _ = load_application_exact(&handle, &day1);
        let mut pc = report("open-page:day1-warm-repeat", &pc);

        // (c) save a single-block edit, three samples, foreground and drain split.
        for sample in 0..3 {
            let (page, revision) = load_application_exact(&handle, &day1);
            let pc_load = report(&format!("save:{sample}:pre-load"), &pc);
            let _ = save_application_block_text(
                &handle,
                page,
                revision,
                &format!("ms audit save sample {sample}"),
            );
            let pc_save = report(&format!("save:{sample}:foreground"), &pc_load);
            drain_managed_local(&handle);
            pc = report(&format!("save:{sample}:deferred-drain"), &pc_save);
        }

        // (d) move the first block of day1 to day2 (cross-day move), then drain.
        let (source_page, source_revision) = load_application_exact(&handle, &day1);
        let (destination_page, destination_revision) = load_application_exact(&handle, &day2);
        let moved_identity = source_page.blocks[0].id.clone();
        let pc_move = report("move:pre-load(untimed)", &pc);
        let outcome = handle
            .move_application_subtrees(SyncApplicationMoveSubtreesRequest {
                episode_id: Uuid::new_v4().to_string(),
                source_path: source_page.path.clone(),
                source_revision,
                destination_path: destination_page.path.clone(),
                destination_revision,
                roots: vec![SyncApplicationMoveRoot {
                    identity: moved_identity,
                    raw_rewrite: None,
                }],
                placement: SyncApplicationMovePlacement::Root { position: 0 },
                admission: application_move_admission(),
            })
            .unwrap();
        assert!(
            matches!(
                outcome,
                SyncApplicationMoveSubtreesOutcome::Committed { .. }
            ),
            "audit move did not commit: {outcome:?}"
        );
        let pc_moved = report("move:foreground", &pc_move);
        drain_managed_local(&handle);
        let pc = report("move:deferred-drain", &pc_moved);

        // (e) clean shutdown.
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
        let _ = report("clean-shutdown", &pc);
    }

