    #[test]
    #[ignore = "manual release benchmark: unsafe reopen after an aged managed history"]
    fn managed_crash_reopen_aged_history_manual_benchmark() {
        assert!(
            !cfg!(debug_assertions),
            "this receipt is release-only; run cargo test -p tine-core --release --lib managed_crash_reopen_aged_history_manual_benchmark -- --ignored --nocapture"
        );
        let source = real_graph_copy_source_from_env("TINE_MANAGED_CRASH_REOPEN_GRAPH_COPY");
        let rounds = std::env::var("TINE_MANAGED_CRASH_REOPEN_ROUNDS")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .filter(|value| *value > 0)
            .unwrap_or(32);
        let fixture = ActivationFixture::copied_graph("managed-crash-reopen-aged", 0xa0e7, &source);
        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        let handle = activated.handle.expect("real graph copy activates");
        drive_initial_feed(&handle);

        let pages = match handle.application_page_inventory().unwrap() {
            SyncApplicationPageInventoryOutcome::Loaded { pages } => pages,
            other => panic!("managed page inventory did not load: {other:?}"),
        };
        let mut editable = pages
            .into_iter()
            .map(|entry| entry.rel_path)
            .filter(|path| !load_application_exact(&handle, path).0.blocks.is_empty())
            .take(rounds.max(1))
            .collect::<Vec<_>>();
        editable.sort();
        assert!(!editable.is_empty(), "real graph copy has an editable page");

        let aging_started = Instant::now();
        for round in 0..rounds {
            let path = &editable[round % editable.len()];
            let (page, revision) = load_application_exact(&handle, path);
            let _ = save_application_block_text(
                &handle,
                page,
                revision,
                &format!("aged-history benchmark edit {round}"),
            );
            drain_managed_local(&handle);
        }
        let aging = aging_started.elapsed();

        let pending_path = editable[rounds % editable.len()].clone();
        let (page, revision) = load_application_exact(&handle, &pending_path);
        let _ = save_application_block_text(
            &handle,
            page,
            revision,
            "aged-history benchmark pending edit",
        );
        assert_eq!(handle.status().unwrap().managed_local_pending, 1);
        drop(handle);

        let started = Instant::now();
        let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
        let elapsed = started.elapsed();
        assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
        let reopened = reopened.handle.expect("aged history reopens safely");
        let (page, _) = load_application_exact(&reopened, &pending_path);
        assert_eq!(page.blocks[0].raw, "aged-history benchmark pending edit");
        eprintln!(
            "managed_crash_reopen_aged rounds={rounds} aging_ms={:.3} elapsed_ms={:.3}",
            startup_ms(aging),
            startup_ms(elapsed),
        );
        assert!(
            elapsed < Duration::from_secs(10),
            "aged-history crash reopen exceeded the 10-second real-corpus recovery ceiling: elapsed_ms={:.3}",
            startup_ms(elapsed),
        );
        assert!(matches!(
            reopened.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    #[test]
    #[ignore = "manual release benchmark: committed edit to peer-visible latency on two graph copies"]
    fn managed_two_device_sync_latency_real_corpora_manual_benchmark() {
        assert!(
            !cfg!(debug_assertions),
            "this receipt is release-only; run cargo test -p tine-core --release managed_two_device_sync_latency_real_corpora_manual_benchmark -- --ignored --nocapture"
        );
        const EDITS: usize = 50;
        let corpora = [
            ("tine-test", "TINE_SYNC_LATENCY_TINE_TEST", 0xa0e0_u128),
            (
                "logseq-anonymized",
                "TINE_SYNC_LATENCY_LOGSEQ_ANONYMIZED",
                0xa1e0_u128,
            ),
        ];

        for (label, variable, seed) in corpora {
            let source = real_graph_copy_source_from_env(variable);
            let (author, receiver, author_handle, receiver_handle) =
                joined_shared_pair_from_graph_copy(label, seed, &source);
            let mut latency_us = Vec::with_capacity(EDITS);
            for index in 0..EDITS {
                let operation_seed = seed + 0x1_000 + index as u128 * 8;
                let (batch_id, page_id, ..) = submit_shared_page(
                    &author_handle,
                    operation_seed,
                    &format!("Sync latency {label} {index}"),
                    &format!("pages/sync-latency-{label}-{index}.md"),
                    &format!("committed sync latency marker {label} {index}"),
                );
                let committed = std::time::Instant::now();
                publish_shared_batch(&author_handle, &author, batch_id);
                settle_shared_provider(&author_handle);
                let delivered = copy_provider_batch(
                    &author,
                    &receiver,
                    batch_id,
                    ProviderBatchDelivery::Complete,
                );
                receiver_handle
                    .observe_provider_paths(delivered, false)
                    .unwrap();

                let mut visible = false;
                for _ in 0..1_024 {
                    let tick = receiver_handle.tick().unwrap();
                    assert!(
                        !matches!(
                            tick,
                            SyncRuntimeTick::RecoveryBlocked(_)
                                | SyncRuntimeTick::Blocked(_)
                                | SyncRuntimeTick::Terminal(_)
                                | SyncRuntimeTick::Failed(_)
                        ),
                        "peer admission failed for {label} edit {index}: {tick:?}"
                    );
                    visible = matches!(
                        receiver_handle
                            .query(SyncRuntimeQueryRequest::LoadPage {
                                page_id: page_id.to_string(),
                                block_limit: 4,
                            })
                            .unwrap(),
                        SyncRuntimeQueryReply::PageWithBlocks(Some(_))
                    );
                    if visible {
                        break;
                    }
                }
                assert!(visible, "peer did not expose {label} edit {index}");
                latency_us.push(committed.elapsed().as_micros() as u64);
            }

            latency_us.sort_unstable();
            let percentile = |percent: usize| latency_us[(latency_us.len() - 1) * percent / 100];
            let mean_us = latency_us.iter().copied().sum::<u64>() / latency_us.len() as u64;
            let p95_us = percentile(95);
            let max_us = latency_us[latency_us.len() - 1];
            eprintln!(
                "managed_sync_latency corpus={label} edits={EDITS} min_us={} p50_us={} p95_us={} max_us={} mean_us={mean_us}",
                latency_us[0],
                percentile(50),
                p95_us,
                max_us,
            );
            // This excludes a sync provider's own network/scan delay: it gates
            // Tine's author publication, exact provider transfer, peer
            // admission, SQLite projection, and query visibility. The first
            // real-corpus receipt measured 539.600/588.501 ms p95 and
            // 549.098/612.280 ms max. Keep bounded margin for host variance,
            // but do not let Tine consume seconds before the provider has even
            // entered the picture.
            assert!(
                p95_us < 750_000,
                "managed device-to-device application latency exceeded 750 ms p95 for {label}: p95_us={p95_us}"
            );
            assert!(
                max_us < 1_000_000,
                "managed device-to-device application latency exceeded one second for {label}: max_us={max_us}"
            );
            assert!(matches!(
                author_handle.clean_shutdown(),
                Ok(SyncShutdownOutcome::Safe(_))
            ));
            assert!(matches!(
                receiver_handle.clean_shutdown(),
                Ok(SyncShutdownOutcome::Safe(_))
            ));
        }
    }

