    #[test]
    #[ignore = "manual release 1,000/3,000/10,000-page activation timing receipt"]
    fn activation_scaled_manual_phase_receipt() {
        assert!(
            !cfg!(debug_assertions),
            "this receipt is release-only; run cargo test -p tine-core --release activation_scaled_manual_phase_receipt -- --ignored --nocapture"
        );
        let page_counts = std::env::var("TINE_ACTIVATION_PAGE_COUNTS")
            .ok()
            .map(|value| {
                value
                    .split(',')
                    .map(|part| {
                        part.trim()
                            .parse::<usize>()
                            .expect("TINE_ACTIVATION_PAGE_COUNTS entries must be integers")
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_else(|| vec![1_000, 3_000, 10_000]);
        assert!(
            !page_counts.is_empty(),
            "at least one page count is required"
        );

        // Keep exactly one synthetic graph alive at a time. The receipt is a
        // measurement oracle, not a latency budget: it validates the measured
        // graph and activation outcome but never turns today's known cost into
        // a false pass/fail threshold.
        for (index, total_pages) in page_counts.into_iter().enumerate() {
            let additional_pages = total_pages
                .checked_sub(3)
                .expect("page counts must include the three seed documents");
            let fixture = ActivationFixture::scaled(
                &format!("manual-scale-{total_pages}"),
                0xa0b0 + index as u128 * 0x10,
                additional_pages,
            );
            let receipt = activate_with_scale_receipt(&fixture);
            assert_eq!(receipt.source_files, total_pages, "{receipt:?}");
            assert!(
                receipt.blocks >= additional_pages.saturating_mul(9),
                "{receipt:?}"
            );
            assert!(
                !receipt.phase_ms.is_empty(),
                "activation receipt must retain its current phase breakdown: {receipt:?}"
            );

            let cold_started = std::time::Instant::now();
            let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
            assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
            let cold_ms = cold_started.elapsed().as_millis();
            eprintln!(
                "activation_manual pages={total_pages} total_ms={} cold_reopen_ms={cold_ms} source_bytes={} blocks={} phases={:?} clean={:?}",
                receipt.total_ms,
                receipt.source_bytes,
                receipt.blocks,
                receipt.phase_ms,
                receipt.clean,
            );
            drop(reopened.handle);
        }
    }

    fn startup_ms(duration: Duration) -> f64 {
        duration.as_secs_f64() * 1_000.0
    }

    fn startup_median(samples: &[Duration]) -> Duration {
        assert!(
            !samples.is_empty(),
            "benchmark receipt has at least one sample"
        );
        let mut ordered = samples.to_vec();
        ordered.sort_unstable();
        ordered[ordered.len() / 2]
    }

    fn startup_p95(samples: &[Duration]) -> Duration {
        assert!(
            !samples.is_empty(),
            "benchmark receipt has at least one sample"
        );
        let mut ordered = samples.to_vec();
        ordered.sort_unstable();
        let index = (ordered.len() * 95).div_ceil(100).saturating_sub(1);
        ordered[index]
    }

    #[derive(Clone, Copy)]
    struct ManagedApplicationSaveBenchmarkSample {
        caller: Duration,
        application_stages: ManagedApplicationSaveStageTimings,
        preparation_stages: TrustedLocalPreparationStageTimings,
        local_mutation_detail: crate::oplog::hot_engine::LocalMutationDetailTimings,
        local_mutation_detail_accounting: ManagedApplicationSaveDetailAccounting,
        stages: TrustedLocalCommitStageTimings,
        page_local_reads: ManagedApplicationSavePageLocalReads,
    }

    #[derive(Clone, Copy, Debug)]
    struct ManagedApplicationSaveDetailAccounting {
        author_operations_ex_snapshot: Duration,
        core_remainder: Duration,
        draft_remainder: Duration,
        finalize_remainder: Duration,
    }

    #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
    struct ManagedApplicationSavePageLocalReads {
        external_points: usize,
        history_points: usize,
    }

    fn managed_application_save_quantiles(
        samples: &[ManagedApplicationSaveBenchmarkSample],
        select: impl Fn(&ManagedApplicationSaveBenchmarkSample) -> Duration,
    ) -> (Duration, Duration) {
        let values = samples.iter().map(select).collect::<Vec<_>>();
        (startup_median(&values), startup_p95(&values))
    }

    fn managed_application_save_benchmark_target_blocks(
        configured: Option<&str>,
    ) -> Result<usize, String> {
        let target_blocks = match configured {
            Some(value) => value.trim().parse::<usize>().map_err(|error| {
                format!("contains {value:?}, which is not an unsigned block count: {error}")
            })?,
            None => 10,
        };
        if !(1..=MAX_SYNC_EDITOR_BLOCKS).contains(&target_blocks) {
            return Err(format!(
                "must be in 1..={MAX_SYNC_EDITOR_BLOCKS} public editor blocks, got {target_blocks}"
            ));
        }
        Ok(target_blocks)
    }

    fn managed_application_save_benchmark_p95_ceiling(target_blocks: usize) -> Duration {
        assert!(
            (1..=MAX_SYNC_EDITOR_BLOCKS).contains(&target_blocks),
            "managed application-save benchmark target blocks must be in 1..={MAX_SYNC_EDITOR_BLOCKS}: {target_blocks}"
        );
        if target_blocks <= 10 {
            Duration::from_millis(15)
        } else {
            Duration::from_millis(50)
        }
    }

    #[test]
    #[ignore = "manual release benchmark: journal-first cross-page foreground and derivative latency"]
    fn managed_cross_page_move_100_and_10000_page_manual_benchmark() {
        assert!(
            !cfg!(debug_assertions),
            "this receipt is release-only; run cargo test -p tine-core --release managed_cross_page_move_100_and_10000_page_manual_benchmark -- --ignored --nocapture"
        );
        const SAMPLES: usize = 7;
        let page_counts = std::env::var("TINE_MANAGED_MOVE_BENCH_PAGES")
            .ok()
            .map(|value| {
                value
                    .split(',')
                    .map(|part| part.trim().parse::<usize>().unwrap())
                    .collect::<Vec<_>>()
            })
            .unwrap_or_else(|| vec![100, 10_000]);
        for (scale_index, total_pages) in page_counts.into_iter().enumerate() {
            assert!(total_pages >= 4);
            let fixture = ActivationFixture::scaled(
                &format!("managed-cross-page-move-{total_pages}"),
                0xa1880 + scale_index as u128 * 0x100,
                total_pages - 3,
            );
            let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
            assert_eq!(activated.status, SyncLocalActivationStatus::Active);
            let handle = activated.handle.expect("move benchmark activates");
            drive_initial_feed_with_turn_budget(&handle, total_pages.saturating_add(128));
            let (mut left, mut left_revision) = load_application_exact(&handle, "Root.md");
            let (mut right, mut right_revision) =
                load_application_exact(&handle, "diary/nested/25-07-2026.org");
            let moved_identity = left.blocks[0].id.clone();

            let mut caller_samples = Vec::with_capacity(SAMPLES);
            let mut foreground_samples = Vec::with_capacity(SAMPLES);
            let mut preparation_samples = Vec::with_capacity(SAMPLES);
            let mut episode_samples = Vec::with_capacity(SAMPLES);
            let mut journal_overlay_samples = Vec::with_capacity(SAMPLES);
            let mut response_samples = Vec::with_capacity(SAMPLES);
            let mut derivative_samples = Vec::with_capacity(SAMPLES);
            let mut derivative_stages = BTreeMap::<String, Duration>::new();
            let mut last_detail = None;
            let mut last_derivative_detail = None;
            for sample in 0..SAMPLES {
                let left_to_right = sample % 2 == 0;
                let (source, source_revision, destination, destination_revision) = if left_to_right
                {
                    (&left, &left_revision, &right, &right_revision)
                } else {
                    (&right, &right_revision, &left, &left_revision)
                };
                let request = SyncApplicationMoveSubtreesRequest {
                    episode_id: Uuid::new_v4().to_string(),
                    source_path: source.path.clone(),
                    source_revision: source_revision.clone(),
                    destination_path: destination.path.clone(),
                    destination_revision: destination_revision.clone(),
                    roots: vec![SyncApplicationMoveRoot {
                        identity: moved_identity.clone(),
                        raw_rewrite: None,
                    }],
                    placement: SyncApplicationMovePlacement::Root { position: 0 },
                    admission: application_move_admission(),
                };
                let before = handle
                    .managed_application_save_instrumentation()
                    .expect("move benchmark reads foreground counters");
                let started = Instant::now();
                let outcome = handle.move_application_subtrees(request).unwrap();
                caller_samples.push(started.elapsed());
                let SyncApplicationMoveSubtreesOutcome::Committed {
                    recovered: false,
                    source,
                    destination,
                    ..
                } = outcome
                else {
                    panic!("move benchmark foreground outcome was not direct: {outcome:?}");
                };
                if left_to_right {
                    left = source.page;
                    left_revision = source.revision;
                    right = destination.page;
                    right_revision = destination.revision;
                } else {
                    right = source.page;
                    right_revision = source.revision;
                    left = destination.page;
                    left_revision = destination.revision;
                }
                let after = handle
                    .managed_application_save_instrumentation()
                    .expect("move benchmark reads post-commit counters");
                assert!(after.forbidden.since(before.forbidden).is_none());
                assert_eq!(
                    after.graph_wide.since(before.graph_wide),
                    GraphWideCommitWork::default()
                );
                foreground_samples.push(after.move_stages.foreground_total);
                preparation_samples.push(after.move_stages.preparation);
                episode_samples.push(after.move_stages.episode_publication);
                journal_overlay_samples.push(after.move_stages.journal_and_hot_overlay);
                response_samples.push(after.move_stages.queue_and_response);
                last_detail = Some(after);
                let derivative_started = Instant::now();
                for _ in 0..4096 {
                    let status = handle.status().unwrap();
                    if status.managed_local_pending == 0 {
                        break;
                    }
                    let stage = status
                        .managed_local_stage
                        .unwrap_or_else(|| "unknown".into());
                    let stage_started = Instant::now();
                    let tick = handle.tick().unwrap();
                    *derivative_stages.entry(stage).or_default() += stage_started.elapsed();
                    assert!(
                        !matches!(
                            tick,
                            SyncRuntimeTick::RecoveryBlocked(_)
                                | SyncRuntimeTick::Blocked(_)
                                | SyncRuntimeTick::Failed(_)
                                | SyncRuntimeTick::Terminal(_)
                        ),
                        "move benchmark derivative failed: {tick:?}"
                    );
                }
                assert_eq!(handle.status().unwrap().managed_local_pending, 0);
                let after_derivative = handle
                    .managed_application_save_instrumentation()
                    .expect("move benchmark reads derivative instrumentation");
                assert_eq!(
                    after_derivative.engine.catalog_authenticated_exact_loads,
                    after.engine.catalog_authenticated_exact_loads,
                    "block-only move derivative must not reconstruct the graph-sized catalog",
                );
                assert_eq!(
                    after_derivative.engine.catalog_current_loads,
                    after.engine.catalog_current_loads,
                    "block-only move derivative must not load the graph-sized current catalog",
                );
                assert_eq!(
                    after_derivative.engine.authenticated_page_identity_lookups,
                    after.engine.authenticated_page_identity_lookups,
                    "block-only move derivative must use exact SQLite page rows rather than the legacy authenticated scratch catalog",
                );
                assert_eq!(
                    after_derivative.forbidden.graph_wide_catalog_validations,
                    after.forbidden.graph_wide_catalog_validations,
                    "block-only move derivative must reuse the retained catalog shape proof rather than validating the graph-sized catalog",
                );
                last_derivative_detail = Some(after_derivative.derivative_stages);
                derivative_samples.push(derivative_started.elapsed());
            }

            let receipt = |samples: &[Duration]| (startup_median(samples), startup_p95(samples));
            let (caller_p50, caller_p95) = receipt(&caller_samples);
            let (foreground_p50, foreground_p95) = receipt(&foreground_samples);
            let (preparation_p50, preparation_p95) = receipt(&preparation_samples);
            let (episode_p50, episode_p95) = receipt(&episode_samples);
            let (journal_p50, journal_p95) = receipt(&journal_overlay_samples);
            let (response_p50, response_p95) = receipt(&response_samples);
            let (derivative_p50, derivative_p95) = receipt(&derivative_samples);
            eprintln!(
                "managed_cross_page_move pages={total_pages} samples={SAMPLES} caller_p50_ms={:.3} caller_p95_ms={:.3} foreground_p50_ms={:.3} foreground_p95_ms={:.3} preparation_p50_ms={:.3} preparation_p95_ms={:.3} episode_p50_ms={:.3} episode_p95_ms={:.3} journal_overlay_p50_ms={:.3} journal_overlay_p95_ms={:.3} response_p50_ms={:.3} response_p95_ms={:.3} derivative_p50_ms={:.3} derivative_p95_ms={:.3}",
                startup_ms(caller_p50),
                startup_ms(caller_p95),
                startup_ms(foreground_p50),
                startup_ms(foreground_p95),
                startup_ms(preparation_p50),
                startup_ms(preparation_p95),
                startup_ms(episode_p50),
                startup_ms(episode_p95),
                startup_ms(journal_p50),
                startup_ms(journal_p95),
                startup_ms(response_p50),
                startup_ms(response_p95),
                startup_ms(derivative_p50),
                startup_ms(derivative_p95),
            );
            let detail = last_detail.expect("move benchmark records at least one sample");
            assert!(
                detail.local_mutation_detail.move_page_home_hint_hits >= 2,
                "scale receipt must use the bounded page-home route: {:?}",
                detail.local_mutation_detail
            );
            assert_eq!(
                detail.local_mutation_detail.move_page_home_hot_catalog_hits,
                0
            );
            eprintln!(
                "managed_cross_page_move_detail pages={total_pages} preparation={:?} mutation={:?} commit={:?}",
                detail.preparation_stages,
                detail.local_mutation_detail,
                detail.commit_stages,
            );
            eprintln!(
                "managed_cross_page_move_derivative_stages pages={total_pages} stages={derivative_stages:?}"
            );
            eprintln!(
                "managed_cross_page_move_derivative_detail pages={total_pages} stages={:?}",
                last_derivative_detail.expect("move benchmark records derivative detail")
            );
            assert!(
                caller_p95 < Duration::from_millis(50),
                "cross-page caller p95 must remain below 50 ms at {total_pages} pages: {caller_p95:?}"
            );
        }
    }

    #[test]
    #[ignore = "manual release benchmark: bounded page create, rename, and delete at graph scale"]
    fn managed_page_mutations_100_and_10000_page_manual_benchmark() {
        assert!(
            !cfg!(debug_assertions),
            "this receipt is release-only; run cargo test -p tine-core --release managed_page_mutations_100_and_10000_page_manual_benchmark -- --ignored --nocapture"
        );
        const SAMPLES: usize = 5;
        let page_counts = std::env::var("TINE_MANAGED_PAGE_MUTATION_BENCH_PAGES")
            .ok()
            .map(|value| {
                value
                    .split(',')
                    .map(|part| part.trim().parse::<usize>().unwrap())
                    .collect::<Vec<_>>()
            })
            .unwrap_or_else(|| vec![100, 10_000]);
        for (scale_index, total_pages) in page_counts.into_iter().enumerate() {
            assert!(total_pages >= 4);
            let fixture = ActivationFixture::scaled(
                &format!("managed-page-mutations-{total_pages}"),
                0xa1900 + scale_index as u128 * 0x100,
                total_pages - 3,
            );
            let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
            assert_eq!(activated.status, SyncLocalActivationStatus::Active);
            let handle = activated.handle.expect("page-mutation benchmark activates");
            drive_initial_feed_with_turn_budget(&handle, total_pages.saturating_add(128));
            let assert_bounded =
                |label: &str,
                 before: ManagedApplicationSaveInstrumentation,
                 after: ManagedApplicationSaveInstrumentation| {
                    let forbidden = after.forbidden.since(before.forbidden);
                    assert_eq!(
                        (
                            forbidden.sqlite_drains,
                            forbidden.archive_object_reads,
                            forbidden.projection_receipt_loads,
                            forbidden.graph_wide_catalog_decodes,
                            forbidden.graph_wide_catalog_validations,
                        ),
                        (0, 0, 0, 0, 0),
                        "{label} performed forbidden global/derivative work: {forbidden:?}"
                    );
                    assert_eq!(
                        after.graph_wide.since(before.graph_wide),
                        GraphWideCommitWork::default(),
                        "{label} performed graph-wide work"
                    );
                };

            let mut create_samples = Vec::with_capacity(SAMPLES);
            let mut rename_samples = Vec::with_capacity(SAMPLES);
            let mut delete_samples = Vec::with_capacity(SAMPLES);
            for sample in 0..SAMPLES {
                let source_name = format!("Bounded mutation source {sample}");
                let target_name = format!("Bounded mutation target {sample}");

                let before = handle
                    .managed_application_save_instrumentation()
                    .expect("page-create benchmark reads counters");
                let started = Instant::now();
                let (created, _) = accepted_new_application_page(
                    &handle,
                    &source_name,
                    vec![BlockDto {
                        id: format!("temporary-bounded-create-{sample}"),
                        raw: "bounded page mutation".into(),
                        ..BlockDto::default()
                    }],
                );
                create_samples.push(started.elapsed());
                let after = handle
                    .managed_application_save_instrumentation()
                    .expect("page-create benchmark reads post counters");
                assert_bounded("one-page creation", before, after);
                drain_managed_local(&handle);

                let before = handle
                    .managed_application_save_instrumentation()
                    .expect("page-rename benchmark reads counters");
                let started = Instant::now();
                assert_eq!(
                    handle
                        .mutate_application_graph(SyncApplicationGraphMutationRequest::RenamePage {
                            old: source_name.clone(),
                            new: target_name.clone(),
                            expected_path: Some(created.path),
                        })
                        .unwrap(),
                    SyncApplicationUnitOutcome::Applied
                );
                rename_samples.push(started.elapsed());
                let after = handle
                    .managed_application_save_instrumentation()
                    .expect("page-rename benchmark reads post counters");
                assert_bounded("one-page rename", before, after);
                drain_managed_local(&handle);

                let (renamed, _) =
                    load_application_logical(&handle, &target_name, SyncPageKind::Page);
                let before = handle
                    .managed_application_save_instrumentation()
                    .expect("page-delete benchmark reads counters");
                let started = Instant::now();
                assert_eq!(
                    handle
                        .mutate_application_graph(SyncApplicationGraphMutationRequest::DeletePage {
                            name: target_name,
                            page_kind: SyncPageKind::Page,
                            expected_path: Some(renamed.path),
                        })
                        .unwrap(),
                    SyncApplicationUnitOutcome::Applied
                );
                delete_samples.push(started.elapsed());
                let after = handle
                    .managed_application_save_instrumentation()
                    .expect("page-delete benchmark reads post counters");
                assert_bounded("one-page deletion", before, after);
                drain_managed_local(&handle);
            }

            let receipt = |samples: &[Duration]| (startup_median(samples), startup_p95(samples));
            let (create_p50, create_p95) = receipt(&create_samples);
            let (rename_p50, rename_p95) = receipt(&rename_samples);
            let (delete_p50, delete_p95) = receipt(&delete_samples);
            eprintln!(
                "managed_page_mutations pages={total_pages} samples={SAMPLES} create_p50_ms={:.3} create_p95_ms={:.3} rename_p50_ms={:.3} rename_p95_ms={:.3} delete_p50_ms={:.3} delete_p95_ms={:.3}",
                startup_ms(create_p50),
                startup_ms(create_p95),
                startup_ms(rename_p50),
                startup_ms(rename_p95),
                startup_ms(delete_p50),
                startup_ms(delete_p95),
            );
        }
    }

    #[test]
    #[ignore = "manual release benchmark: managed application saves at 100 and 10,000 pages"]
    fn managed_application_save_100_and_10000_page_manual_benchmark() {
        assert!(
            !cfg!(debug_assertions),
            "this receipt is release-only; run cargo test -p tine-core --release managed_application_save_100_and_10000_page_manual_benchmark -- --ignored --nocapture"
        );
        const NAMED_PAGE: &str = "Synthetic 0";
        let page_counts = std::env::var("TINE_MANAGED_APPLICATION_SAVE_BENCH_PAGES")
            .ok()
            .map(|value| {
                value
                    .split(',')
                    .map(|part| {
                        part.trim().parse::<usize>().unwrap_or_else(|error| {
                            panic!(
                                "TINE_MANAGED_APPLICATION_SAVE_BENCH_PAGES contains {part:?}: {error}"
                            )
                        })
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_else(|| vec![100, 10_000]);
        assert!(
            !page_counts.is_empty() && page_counts.iter().all(|pages| *pages >= 4),
            "managed application-save benchmark needs nonempty total page counts of at least four: {page_counts:?}"
        );
        let target_blocks = managed_application_save_benchmark_target_blocks(
            std::env::var("TINE_MANAGED_APPLICATION_SAVE_BENCH_TARGET_BLOCKS")
                .ok()
                .as_deref(),
        )
        .unwrap_or_else(|error| {
            panic!("TINE_MANAGED_APPLICATION_SAVE_BENCH_TARGET_BLOCKS {error}")
        });
        let p95_ceiling = managed_application_save_benchmark_p95_ceiling(target_blocks);
        let runs = std::env::var("TINE_MANAGED_APPLICATION_SAVE_BENCH_RUNS")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .filter(|runs| *runs > 0)
            .unwrap_or(1);
        let warmups = std::env::var("TINE_MANAGED_APPLICATION_SAVE_BENCH_WARMUPS")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .unwrap_or(2);
        let samples_per_run = std::env::var("TINE_MANAGED_APPLICATION_SAVE_BENCH_SAMPLES")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .filter(|samples| *samples > 0)
            .unwrap_or(5);
        let edits_per_run = warmups
            .checked_add(samples_per_run)
            .expect("managed application-save edit count must fit usize");

        for total_pages in page_counts {
            let additional_pages = total_pages - 3;
            let mut managed_samples = Vec::with_capacity(runs * samples_per_run);
            let mut managed_runs = Vec::with_capacity(runs);
            let mut direct_files_samples = Vec::with_capacity(runs * samples_per_run);

            for run in 0..runs {
                let mut managed_run_samples = Vec::with_capacity(samples_per_run);
                let unrelated_blocks = if total_pages >= 10_000 { 1 } else { 10 };
                let fixture = ActivationFixture::scaled_with_target_and_unrelated_blocks(
                    &format!("managed-application-save-{total_pages}-run-{run}"),
                    0xa120 + total_pages as u128 * 16 + run as u128,
                    additional_pages,
                    target_blocks,
                    unrelated_blocks,
                );
                let mut expected_graph = user_graph_bytes(&fixture.graph_root);
                let (source_pages, _, _) = activation_source_counts(&fixture.graph_root);
                assert_eq!(source_pages, total_pages);
                let request = reopen_request(&fixture.request);

                // Activation/import and its startup catch-up are intentionally
                // outside the caller-observed save interval.
                let activated =
                    SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
                assert_eq!(activated.status, SyncLocalActivationStatus::Active);
                let handle = activated
                    .handle
                    .expect("managed application benchmark activation retains a runtime handle");
                // Exact-feed work is page-batched. A fixed 128-turn fixture
                // budget predates the 10k corpus and can reject healthy
                // bounded progress before the save gate is measured. One turn
                // per source page plus slack remains finite while covering any
                // legal batching width.
                drive_initial_feed_with_turn_budget(&handle, total_pages.saturating_add(128));
                let initial_journal = handle
                    .managed_application_save_instrumentation()
                    .expect("benchmark activation exposes local-journal instrumentation");
                assert_eq!(initial_journal.managed_local_next_sequence, 0);
                assert_eq!(initial_journal.managed_local_pending, 0);

                let (mut page, mut revision) =
                    load_application_logical(&handle, NAMED_PAGE, SyncPageKind::Page);
                let target_path = page.path.clone();
                let unchanged_path = expected_graph
                    .keys()
                    .find(|path| *path != &target_path)
                    .expect("scaled benchmark has an unrelated sentinel page")
                    .clone();
                let unchanged_bytes = expected_graph[&unchanged_path].clone();
                let mut expected_journal_targets = Vec::with_capacity(edits_per_run);
                for edit in 0..edits_per_run {
                    let content = format!(
                        "managed application save total-pages={total_pages} run={run} edit={edit}"
                    );
                    page.blocks[0].raw = content.clone();
                    let page_blocks = flatten_application_blocks(&page.blocks).len();
                    let timed = edit >= warmups;
                    let counters_before = handle
                        .managed_application_save_instrumentation()
                        .expect("benchmark save obtains actor foreground instrumentation");
                    let __pc_before = crate::perf_count::snapshot();
                    let started = Instant::now();
                    let outcome = handle
                        .save_application_page(SyncApplicationPageSaveRequest {
                            target: SyncApplicationPageSaveTarget::Existing {
                                path: target_path.clone(),
                                revision: revision.clone(),
                            },
                            page,
                        })
                        .expect("ordinary managed application save succeeds");
                    let caller = started.elapsed();
                    let __pc_after = crate::perf_count::snapshot();
                    if timed {
                        eprintln!(
                            "{}",
                            __pc_after.report_since(
                                &__pc_before,
                                &format!("save pages={total_pages} blocks={target_blocks} edit={edit}")
                            )
                        );
                    }
                    let counters_after = handle
                        .managed_application_save_instrumentation()
                        .expect("benchmark save obtains post-save foreground instrumentation");
                    let (returned, returned_revision) = match outcome {
                        SyncApplicationPageSaveOutcome::Saved { page, revision, .. } => {
                            (page, revision)
                        }
                        other => {
                            panic!("ordinary managed application save was not direct: {other:?}")
                        }
                    };
                    assert_eq!(returned.path, target_path);
                    assert_eq!(returned.blocks[0].raw, content);
                    assert_ne!(returned_revision, revision);

                    let exact_bytes = fs::read(fixture.graph_root.join(&target_path)).unwrap();
                    assert_eq!(
                        counters_after.managed_local_next_sequence,
                        counters_before.managed_local_next_sequence + 1,
                        "each ordinary save appends exactly one managed-local journal frame"
                    );
                    assert_eq!(
                        counters_after.managed_local_pending,
                        counters_before.managed_local_pending + 1,
                        "the benchmark keeps each accepted frame pending until the post-measurement drain"
                    );
                    expected_journal_targets.push((target_path.clone(), exact_bytes.clone()));
                    expected_graph.insert(target_path.clone(), exact_bytes);
                    assert_eq!(
                        fs::read(fixture.graph_root.join(&unchanged_path)).unwrap(),
                        unchanged_bytes,
                        "ordinary application save leaves an unrelated graph file untouched"
                    );
                    let parsed = Graph::open(&fixture.graph_root)
                        .load_by_path(&target_path)
                        .unwrap()
                        .expect("saved target remains an exact graph page");
                    assert_parser_dto_semantics(&returned, &parsed);
                    let immediate = load_application_exact(&handle, &target_path);
                    assert_parser_dto_semantics(&returned, &immediate.0);
                    assert_eq!(
                        immediate.1, returned_revision,
                        "the returned application revision must be the next save conflict base"
                    );

                    if timed {
                        let page_local_reads = assert_managed_application_save_foreground_counters(
                            counters_before,
                            counters_after,
                            page_blocks,
                        );
                        let local_mutation_detail_accounting =
                            assert_managed_application_save_detail_accounting(
                                counters_after.preparation_stages,
                                counters_after.local_mutation_detail,
                                page_blocks,
                            );
                        assert_managed_application_save_editor_request_accounting(
                            counters_after.application_stages,
                            page_blocks,
                            counters_after.local_mutation_detail,
                            counters_after.prepared_editor_projection,
                        );
                        let sample = ManagedApplicationSaveBenchmarkSample {
                            caller,
                            application_stages: counters_after.application_stages,
                            preparation_stages: counters_after.preparation_stages,
                            local_mutation_detail: counters_after.local_mutation_detail,
                            local_mutation_detail_accounting,
                            stages: counters_after.commit_stages,
                            page_local_reads,
                        };
                        managed_samples.push(sample);
                        managed_run_samples.push(sample);
                    }
                    page = returned;
                    revision = returned_revision;
                }

                // Inspect the active segment before derivative drain can
                // compact its authenticated prefix into a generation anchor.
                let foreground_frames = managed_local_journal_frames(&request);
                assert_eq!(foreground_frames.len(), expected_journal_targets.len());
                for (sequence, (frame, (expected_path, expected_target))) in foreground_frames
                    .iter()
                    .zip(&expected_journal_targets)
                    .enumerate()
                {
                    assert_eq!(frame.sequence(), sequence as u64);
                    let record = crate::oplog::decode_managed_local_record(frame).unwrap();
                    assert_eq!(record.projection().intent().path().as_str(), expected_path);
                    assert_eq!(
                        record.projection().intent().target().bytes(),
                        Some(expected_target.as_slice()),
                        "each retained journal frame names the exact graph bytes returned by its save"
                    );
                }

                // All foreground saves above are consecutive. Derivative work
                // begins only after their timing and byte/semantic receipts.
                for _ in 0..edits_per_run.saturating_mul(16).saturating_add(128) {
                    if handle.status().unwrap().managed_local_pending == 0 {
                        break;
                    }
                    handle.tick().unwrap();
                }
                assert_eq!(handle.status().unwrap().managed_local_pending, 0);
                assert_eq!(user_graph_bytes(&fixture.graph_root), expected_graph);
                assert!(matches!(
                    handle.clean_shutdown().unwrap(),
                    SyncShutdownOutcome::Safe(_)
                ));
                let device_id = request
                    .clean_identities
                    .as_ref()
                    .expect("benchmark reopen retains clean identities")
                    .device_id
                    .as_uuid();
                assert!(
                    managed_local_file_names(&request).iter().any(|name| {
                        parse_managed_local_v2_anchor_name(name, device_id)
                            .is_some_and(|generation| generation > 1)
                    }),
                    "drain plus test-threshold compaction advances schema-2 authority"
                );

                let reopened = active_handle(SyncRuntimeHandle::open(request));
                drive_initial_feed_with_turn_budget(&reopened, total_pages.saturating_add(128));
                let restored = load_application_exact(&reopened, &target_path);
                assert_parser_dto_semantics(&page, &restored.0);
                assert_eq!(revision, restored.1);
                assert_eq!(user_graph_bytes(&fixture.graph_root), expected_graph);
                assert!(matches!(
                    reopened.clean_shutdown().unwrap(),
                    SyncShutdownOutcome::Safe(_)
                ));

                // Direct Files saves are a separately reported comparable
                // user operation: they avoid the managed application request,
                // actor crossing, journal, and retained semantic overlay.
                let direct_fixture = ActivationFixture::scaled_with_target_and_unrelated_blocks(
                    &format!("direct-files-save-{total_pages}-run-{run}"),
                    0xa220 + total_pages as u128 * 16 + run as u128,
                    additional_pages,
                    target_blocks,
                    unrelated_blocks,
                );
                let mut direct_expected_graph = user_graph_bytes(&direct_fixture.graph_root);
                let (source_pages, _, _) = activation_source_counts(&direct_fixture.graph_root);
                assert_eq!(source_pages, total_pages);
                let direct_graph = Graph::open_checked(&direct_fixture.graph_root)
                    .expect("direct fixture graph opens");
                direct_graph.warm_cache();
                let mut direct_page = direct_graph
                    .load_named(NAMED_PAGE, PageKind::Page)
                    .expect("direct benchmark named-page request succeeds")
                    .expect("direct benchmark synthetic page exists");
                let direct_target_path = direct_page.path.clone();
                let direct_unchanged_path = direct_expected_graph
                    .keys()
                    .find(|path| *path != &direct_target_path)
                    .expect("scaled direct benchmark has an unrelated sentinel page")
                    .clone();
                let direct_unchanged_bytes = direct_expected_graph[&direct_unchanged_path].clone();
                for edit in 0..edits_per_run {
                    let content = format!(
                        "direct files save total-pages={total_pages} run={run} edit={edit}"
                    );
                    let direct_block = &mut direct_page.blocks[0];
                    direct_block.raw = content;
                    direct_block.marker = None;
                    direct_block.properties.clear();
                    direct_block.tags.clear();
                    let started = Instant::now();
                    let next_revision = direct_graph
                        .save_page(&direct_page, direct_page.rev.as_deref())
                        .expect("direct existing-page save succeeds");
                    let caller = started.elapsed();
                    direct_page.rev = Some(next_revision.clone());
                    let exact_bytes =
                        fs::read(direct_fixture.graph_root.join(&direct_target_path)).unwrap();
                    direct_expected_graph.insert(direct_target_path.clone(), exact_bytes);
                    assert_eq!(
                        fs::read(direct_fixture.graph_root.join(&direct_unchanged_path)).unwrap(),
                        direct_unchanged_bytes,
                        "direct save leaves an unrelated graph file untouched"
                    );
                    let parsed = Graph::open(&direct_fixture.graph_root)
                        .load_by_path(&direct_target_path)
                        .unwrap()
                        .expect("direct saved target remains an exact graph page");
                    assert_parser_dto_semantics(&direct_page, &parsed);
                    assert_eq!(parsed.rev.as_deref(), Some(next_revision.as_str()));
                    if edit >= warmups {
                        direct_files_samples.push(caller);
                    }
                }
                assert_eq!(
                    user_graph_bytes(&direct_fixture.graph_root),
                    direct_expected_graph,
                    "the completed Direct Files edit sequence changes exactly its target file"
                );
                managed_runs.push(managed_run_samples);
            }

            assert_eq!(managed_samples.len(), runs * samples_per_run);
            assert_eq!(managed_runs.len(), runs);
            assert_eq!(direct_files_samples.len(), runs * samples_per_run);
            let (managed_p50, managed_p95) =
                managed_application_save_quantiles(&managed_samples, |sample| sample.caller);
            let direct_files_p50 = startup_median(&direct_files_samples);
            let direct_files_p95 = startup_p95(&direct_files_samples);
            eprintln!(
                "managed_application_save_bench total_pages={total_pages} target_blocks={target_blocks} runs={runs} warmups={warmups} samples_per_run={samples_per_run} managed_application_save: {} managed_application_save_runs: {} direct_files_existing_page_save_p50_ms={:.3} direct_files_existing_page_save_p95_ms={:.3} (reported separately; this operation does not perform managed caller work)",
                managed_application_save_phase_receipt(&managed_samples),
                managed_application_save_run_receipt(&managed_runs),
                startup_ms(direct_files_p50),
                startup_ms(direct_files_p95),
            );
            if target_blocks <= 10 {
                assert!(
                    managed_p50 < Duration::from_millis(10),
                    "managed application save ordinary-page p50 exceeded 10 ms at scale={total_pages} pages target_blocks={target_blocks}: p50={managed_p50:?} p95={managed_p95:?}"
                );
            }
            assert!(
                managed_p95 < p95_ceiling,
                "managed application save p95 exceeded {:?} at scale={total_pages} pages target_blocks={target_blocks}: p50={managed_p50:?} p95={managed_p95:?}",
                p95_ceiling,
            );
        }
    }

    #[test]
    fn managed_application_save_benchmark_target_blocks_follow_the_public_save_boundary() {
        assert_eq!(MAX_SYNC_EDITOR_BLOCKS, 511);
        assert_eq!(
            managed_application_save_benchmark_target_blocks(None),
            Ok(10)
        );
        assert_eq!(
            managed_application_save_benchmark_target_blocks(Some(" 511 ")),
            Ok(MAX_SYNC_EDITOR_BLOCKS)
        );
        assert!(managed_application_save_benchmark_target_blocks(Some("0")).is_err());
        assert!(managed_application_save_benchmark_target_blocks(Some("512")).is_err());
        assert!(managed_application_save_benchmark_target_blocks(Some("not-a-count")).is_err());
        assert_eq!(
            managed_application_save_benchmark_p95_ceiling(10),
            Duration::from_millis(15)
        );
        assert_eq!(
            managed_application_save_benchmark_p95_ceiling(11),
            Duration::from_millis(50)
        );
        assert_eq!(
            managed_application_save_benchmark_p95_ceiling(MAX_SYNC_EDITOR_BLOCKS),
            Duration::from_millis(50)
        );
    }

    fn managed_application_save_read_quantiles(
        samples: &[ManagedApplicationSaveBenchmarkSample],
        select: impl Fn(&ManagedApplicationSaveBenchmarkSample) -> usize,
    ) -> (usize, usize, usize) {
        assert!(
            !samples.is_empty(),
            "benchmark receipt has at least one sample"
        );
        let mut values = samples.iter().map(select).collect::<Vec<_>>();
        values.sort_unstable();
        let p50 = values[values.len() / 2];
        let p95 = values[(values.len() * 95).div_ceil(100).saturating_sub(1)];
        (p50, p95, *values.last().unwrap())
    }

    fn checked_save_detail_remainder(
        parent: Duration,
        children: impl IntoIterator<Item = Duration>,
        label: &str,
    ) -> Duration {
        let used = children.into_iter().fold(Duration::ZERO, |sum, child| {
            sum.checked_add(child)
                .unwrap_or_else(|| panic!("managed save {label} child durations overflow"))
        });
        parent.checked_sub(used).unwrap_or_else(|| {
            panic!(
                "managed save {label} timing children exceed their parent: parent={parent:?} children={used:?}"
            )
        })
    }

    fn assert_save_detail_remainder_bounded(parent: Duration, remainder: Duration, label: &str) {
        let fractional = parent.checked_div(20).unwrap_or(Duration::ZERO);
        let ceiling = Duration::from_millis(1).max(fractional);
        assert!(
            remainder <= ceiling,
            "managed save {label} instrumentation leaves too much unaccounted time: parent={parent:?} remainder={remainder:?} ceiling={ceiling:?}"
        );
    }

    fn assert_managed_application_save_detail_accounting(
        preparation: TrustedLocalPreparationStageTimings,
        detail: crate::oplog::hot_engine::LocalMutationDetailTimings,
        page_blocks: usize,
    ) -> ManagedApplicationSaveDetailAccounting {
        let author_operations_ex_snapshot = detail
            .author_operations_inclusive
            .checked_sub(detail.before_semantic_snapshots_child)
            .unwrap_or_else(|| {
                panic!(
                    "managed save nested before-snapshot timing exceeds author operations: {detail:?}"
                )
            });
        let core_remainder = checked_save_detail_remainder(
            detail.core_total,
            [
                detail.core_preflight,
                detail.author_operations_inclusive,
                detail.identity_trigger_validation,
                detail.after_semantic_snapshots,
                detail.effect_derive_encode,
                detail.dependencies_frontier,
                detail.delta_export_object_construction,
                detail.manifest_path_authority,
                detail.prospective_document_capture,
            ],
            "core",
        );
        let draft_remainder = checked_save_detail_remainder(
            preparation.draft,
            [
                detail.core_total,
                detail.before_projection_materialization,
                detail.post_projection_materialization,
                detail.projection_requirement_assembly,
            ],
            "draft",
        );
        let finalize_remainder = checked_save_detail_remainder(
            preparation.finalize,
            [
                detail.finalize_authority_checks,
                detail.finalize_base_objects,
                detail.finalize_projection_intents,
                detail.finalize_seal_pending,
            ],
            "finalize",
        );
        assert_save_detail_remainder_bounded(detail.core_total, core_remainder, "core");
        assert_save_detail_remainder_bounded(preparation.draft, draft_remainder, "draft");
        assert_save_detail_remainder_bounded(preparation.finalize, finalize_remainder, "finalize");
        assert_eq!(detail.draft_calls, 1, "ordinary save drafts exactly once");
        assert_eq!(detail.core_calls, 1, "ordinary save prepares one core");
        assert_eq!(
            detail.finalize_calls, 1,
            "ordinary save finalizes exactly once"
        );
        assert_eq!(
            detail.operation_count, 1,
            "ordinary save emits one semantic operation"
        );
        assert_eq!(
            detail.effect_block_deltas, 1,
            "ordinary save changes exactly one semantic block"
        );
        assert_eq!(
            detail.affected_documents, 1,
            "ordinary save affects one document"
        );
        assert_eq!(
            detail.affected_heads, 1,
            "ordinary save records one document head"
        );
        assert_eq!(
            detail.before_projection_pages, 1,
            "ordinary save materializes one pre-page"
        );
        assert_eq!(
            detail.post_projection_pages, 1,
            "ordinary save materializes one post-page"
        );
        assert_eq!(
            detail.projection_requirements, 1,
            "ordinary save assembles one requirement"
        );
        assert_eq!(
            detail.delta_exports, 1,
            "ordinary save exports one CRDT delta"
        );
        assert_eq!(
            detail.captured_documents, 1,
            "ordinary save captures one post-document"
        );
        assert_eq!(
            detail.finalize_captured_inputs, 1,
            "ordinary save finalizer sees one input"
        );
        assert_eq!(
            detail.finalize_projection_intents_count, 1,
            "ordinary save finalizer seals one intent"
        );
        assert_eq!(
            detail.before_snapshot_documents, 1,
            "ordinary save snapshots one pre-document"
        );
        assert_eq!(
            detail.after_snapshot_documents, 1,
            "ordinary save snapshots one post-document"
        );
        assert_eq!(
            detail.before_snapshot_blocks, page_blocks,
            "ordinary save pre-snapshot block count"
        );
        assert_eq!(
            detail.after_snapshot_blocks, page_blocks,
            "ordinary save post-snapshot block count"
        );
        assert!(
            detail.delta_export_bytes > 0,
            "ordinary save exports nonempty CRDT bytes"
        );
        assert!(
            detail.constructed_object_bytes > 0,
            "ordinary save constructs objects"
        );
        assert!(
            detail.finalize_projection_intent_bytes > 0,
            "ordinary save encodes an intent"
        );
        ManagedApplicationSaveDetailAccounting {
            author_operations_ex_snapshot,
            core_remainder,
            draft_remainder,
            finalize_remainder,
        }
    }

    fn assert_managed_application_save_editor_request_accounting(
        stages: ManagedApplicationSaveStageTimings,
        page_blocks: usize,
        detail: crate::oplog::hot_engine::LocalMutationDetailTimings,
        prepared: PreparedEditorProjectionInstrumentation,
    ) {
        assert_save_detail_remainder_bounded(
            stages.editor_transaction_build,
            stages.editor_request_remainder,
            "editor request",
        );
        assert_eq!(
            (
                stages.editor_block_id_resolution_passes,
                stages.editor_block_ids_visited
            ),
            (1, page_blocks)
        );
        assert_eq!(
            (
                stages.editor_requested_current_map_builds,
                stages.editor_requested_current_map_entries
            ),
            (1, page_blocks)
        );
        assert_eq!(
            (
                stages.editor_requested_membership_derivations,
                stages.editor_requested_membership_entries
            ),
            (1, page_blocks)
        );
        assert_eq!(
            stages.editor_accepted_renders, prepared.accepted_renders,
            "stage accounting must report whether predecessor rendering was actually required"
        );
        assert!(stages.editor_accepted_renders <= 1);
        assert_eq!(stages.editor_accepted_rendered_blocks, page_blocks);
        assert_eq!(
            (
                stages.editor_target_renders,
                stages.editor_target_rendered_blocks
            ),
            (1, page_blocks)
        );
        assert_eq!(stages.editor_accepted_parses, 1);
        assert_eq!(stages.editor_target_parses, 1);
        assert!(stages.editor_accepted_parse_bytes > 0);
        assert!(stages.editor_target_parse_bytes > 0);
        assert_eq!(stages.editor_target_dto_converted_blocks, page_blocks);
        assert_eq!(
            (
                stages.transaction_current_map_builds,
                stages.transaction_current_map_entries
            ),
            (1, page_blocks)
        );
        assert_eq!(
            (
                stages.transaction_membership_derivations,
                stages.transaction_membership_entries
            ),
            (1, page_blocks)
        );
        assert_eq!(
            (
                stages.transaction_outline_depth_derivations,
                stages.transaction_outline_depth_entries
            ),
            (1, page_blocks)
        );
        assert_eq!(
            (
                stages.transaction_create_scan_passes,
                stages.transaction_create_scan_entries
            ),
            (1, page_blocks)
        );
        assert_eq!(
            (
                stages.transaction_edit_scan_passes,
                stages.transaction_edit_scan_entries
            ),
            (1, page_blocks)
        );
        assert_eq!(
            (
                stages.transaction_reorder_scan_passes,
                stages.transaction_reorder_scan_entries
            ),
            (1, page_blocks)
        );
        assert_eq!(
            (
                stages.transaction_delete_desired_set_scans,
                stages.transaction_delete_desired_set_entries
            ),
            (1, page_blocks)
        );
        assert_eq!(
            (
                stages.transaction_delete_current_set_scans,
                stages.transaction_delete_current_set_entries
            ),
            (1, page_blocks)
        );
        assert_eq!(
            (
                stages.transaction_delete_root_scans,
                stages.transaction_delete_root_entries
            ),
            (1, page_blocks)
        );
        assert_eq!(
            (
                stages.transaction_emitted_create,
                stages.transaction_emitted_edit,
                stages.transaction_emitted_reorder,
                stages.transaction_emitted_delete,
                stages.transaction_emitted_preamble,
                stages.transaction_emitted_rename,
                stages.transaction_emitted_kind,
            ),
            (0, 1, 0, 0, 0, 0, 0),
        );
        assert_eq!(
            (
                stages.transaction_inner_validations,
                stages.transaction_inner_validation_operations
            ),
            (1, 1)
        );
        assert_eq!(
            (
                stages.transaction_outer_validations,
                stages.transaction_outer_validation_operations
            ),
            (1, 1)
        );
        assert_eq!(
            (prepared.created, prepared.reused, prepared.fallback),
            (1, 1, 0)
        );
        assert_eq!(
            detail.before_projection_full_materializations, 0,
            "timed consecutive saves must not reconstruct their pre-page"
        );
        assert_eq!(detail.before_projection_affine_attempts, 1);
        assert_eq!(detail.before_projection_affine_reuses, 1);
        assert_eq!(detail.before_projection_affine_fallbacks, 0);
        assert_eq!(detail.before_projection_affine_snapshot_blocks, page_blocks);
        assert_eq!(detail.post_projection_affine_attempts, 1);
        assert_eq!(detail.post_projection_affine_reuses, 1);
        assert_eq!(detail.post_projection_affine_fallbacks, 0);
        assert_eq!(detail.post_projection_affine_candidate_blocks, page_blocks);
        assert_eq!(prepared.capture_sealed_pending_local_predecessor_success, 1);
        assert_eq!(prepared.finalizer_sealed_pending_local_predecessor_use, 1);
        assert_eq!(prepared.finalizer_predecessor_replay_render, 0);
    }

    fn managed_application_save_detail_phase_receipt(
        samples: &[ManagedApplicationSaveBenchmarkSample],
    ) -> String {
        macro_rules! duration_quantiles {
            ($field:ident) => {{
                let (p50, p95) = managed_application_save_quantiles(samples, |sample| {
                    sample.local_mutation_detail.$field
                });
                format!(
                    "{}p50_ms={:.3} {}p95_ms={:.3}",
                    concat!(stringify!($field), "_"),
                    startup_ms(p50),
                    concat!(stringify!($field), "_"),
                    startup_ms(p95),
                )
            }};
        }
        macro_rules! count_summary {
            ($field:ident) => {{
                let mut values = samples
                    .iter()
                    .map(|sample| sample.local_mutation_detail.$field)
                    .collect::<Vec<_>>();
                values.sort_unstable();
                format!(
                    "{}min={} {}median={} {}max={}",
                    concat!(stringify!($field), "_"),
                    values[0],
                    concat!(stringify!($field), "_"),
                    values[values.len() / 2],
                    concat!(stringify!($field), "_"),
                    values[values.len() - 1],
                )
            }};
        }
        macro_rules! accounting_duration_quantiles {
            ($field:ident) => {{
                let (p50, p95) = managed_application_save_quantiles(samples, |sample| {
                    sample.local_mutation_detail_accounting.$field
                });
                format!(
                    "{}p50_ms={:.3} {}p95_ms={:.3}",
                    concat!(stringify!($field), "_"),
                    startup_ms(p50),
                    concat!(stringify!($field), "_"),
                    startup_ms(p95),
                )
            }};
        }
        let correlated_vector = |sample: &ManagedApplicationSaveBenchmarkSample| {
            format!(
                "caller={:?} application_stages={:?} preparation_stages={:?} commit_stages={:?} local_mutation_detail={:?} derived={:?}",
                sample.caller,
                sample.application_stages,
                sample.preparation_stages,
                sample.stages,
                sample.local_mutation_detail,
                sample.local_mutation_detail_accounting,
            )
        };
        let mut actor_ranked = samples.iter().collect::<Vec<_>>();
        actor_ranked.sort_unstable_by_key(|sample| sample.application_stages.actor_total);
        let p50 = actor_ranked[actor_ranked.len() / 2];
        let p95 = actor_ranked[(actor_ranked.len() * 95).div_ceil(100).saturating_sub(1)];
        [
            duration_quantiles!(core_total),
            duration_quantiles!(core_preflight),
            duration_quantiles!(author_operations_inclusive),
            duration_quantiles!(before_semantic_snapshots_child),
            duration_quantiles!(identity_trigger_validation),
            duration_quantiles!(after_semantic_snapshots),
            duration_quantiles!(effect_derive_encode),
            duration_quantiles!(dependencies_frontier),
            duration_quantiles!(delta_export_object_construction),
            duration_quantiles!(manifest_path_authority),
            duration_quantiles!(prospective_document_capture),
            duration_quantiles!(before_projection_materialization),
            duration_quantiles!(post_projection_materialization),
            duration_quantiles!(projection_requirement_assembly),
            duration_quantiles!(finalize_authority_checks),
            duration_quantiles!(finalize_base_objects),
            duration_quantiles!(finalize_projection_intents),
            duration_quantiles!(finalize_seal_pending),
            accounting_duration_quantiles!(author_operations_ex_snapshot),
            accounting_duration_quantiles!(core_remainder),
            accounting_duration_quantiles!(draft_remainder),
            accounting_duration_quantiles!(finalize_remainder),
            count_summary!(core_calls),
            count_summary!(operation_count),
            count_summary!(before_snapshot_documents),
            count_summary!(before_snapshot_blocks),
            count_summary!(after_snapshot_documents),
            count_summary!(after_snapshot_blocks),
            count_summary!(effect_block_deltas),
            count_summary!(affected_documents),
            count_summary!(affected_heads),
            count_summary!(delta_exports),
            count_summary!(delta_export_bytes),
            count_summary!(constructed_object_bytes),
            count_summary!(captured_documents),
            count_summary!(before_projection_pages),
            count_summary!(post_projection_affine_attempts),
            count_summary!(post_projection_affine_reuses),
            count_summary!(post_projection_affine_fallbacks),
            count_summary!(post_projection_affine_candidate_blocks),
            count_summary!(post_projection_pages),
            count_summary!(projection_requirements),
            count_summary!(draft_calls),
            count_summary!(finalize_captured_inputs),
            count_summary!(finalize_base_objects_count),
            count_summary!(finalize_projection_intents_count),
            count_summary!(finalize_projection_intent_bytes),
            count_summary!(finalize_final_objects),
            count_summary!(finalize_calls),
            format!("actor_ranked_p50_vector={}", correlated_vector(p50)),
            format!("actor_ranked_p95_vector={}", correlated_vector(p95)),
        ]
        .join(" ")
    }

    fn managed_application_save_run_receipt(
        runs: &[Vec<ManagedApplicationSaveBenchmarkSample>],
    ) -> String {
        assert!(
            !runs.is_empty() && runs.iter().all(|samples| !samples.is_empty()),
            "managed application save receipt requires timed samples for every run"
        );
        let mut p50s = Vec::with_capacity(runs.len());
        let mut p95s = Vec::with_capacity(runs.len());
        let per_run = runs
            .iter()
            .enumerate()
            .map(|(run, samples)| {
                let (p50, p95) =
                    managed_application_save_quantiles(samples, |sample| sample.caller);
                p50s.push(p50);
                p95s.push(p95);
                format!(
                    "run{run}_caller_p50_ms={:.3} run{run}_caller_p95_ms={:.3}",
                    startup_ms(p50),
                    startup_ms(p95),
                )
            })
            .collect::<Vec<_>>()
            .join(" ");
        let median_p50 = startup_median(&p50s);
        let median_p95 = startup_median(&p95s);
        let spread = |values: &mut Vec<Duration>| {
            values.sort_unstable();
            values[values.len() - 1]
                .checked_sub(values[0])
                .expect("sorted durations have a nonnegative range")
        };
        let mad = |values: &[Duration], median: Duration| {
            let deviations = values
                .iter()
                .map(|value| value.abs_diff(median))
                .collect::<Vec<_>>();
            startup_median(&deviations)
        };
        let p50_mad = mad(&p50s, median_p50);
        let p95_mad = mad(&p95s, median_p95);
        let p50_range = spread(&mut p50s);
        let p95_range = spread(&mut p95s);
        format!(
            "{per_run} run_p50_median_ms={:.3} run_p50_range_ms={:.3} run_p50_mad_ms={:.3} run_p95_median_ms={:.3} run_p95_range_ms={:.3} run_p95_mad_ms={:.3}",
            startup_ms(median_p50),
            startup_ms(p50_range),
            startup_ms(p50_mad),
            startup_ms(median_p95),
            startup_ms(p95_range),
            startup_ms(p95_mad),
        )
    }

